import re
from functools import cmp_to_key

def sort_versions(versions: list[str]) -> list[str]:
    """
    Sort version strings according to Semantic Versioning 2.0.0 precedence.

    Args:
        versions: List of version strings to sort

    Returns:
        Sorted list of version strings

    Raises:
        ValueError: If any version string is invalid
    """

    # Regex pattern for semantic versioning
    # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
    pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([a-zA-Z0-9.-]+))?(?:\+([a-zA-Z0-9.-]+))?$'

    def parse_version(version_str: str):
        """Parse a version string and return structured components."""
        match = re.match(pattern, version_str)
        if not match:
            raise ValueError(f"Invalid version: {version_str}")

        major, minor, patch, prerelease, build = match.groups()

        # Validate prerelease format if present
        if prerelease is not None:
            identifiers = prerelease.split('.')
            for identifier in identifiers:
                if not identifier:
                    raise ValueError(f"Invalid version: {version_str}")
                if not re.match(r'^[0-9A-Za-z-]+$', identifier):
                    raise ValueError(f"Invalid version: {version_str}")
                # Check for leading zeros in numeric identifiers
                if identifier.isdigit() and len(identifier) > 1 and identifier[0] == '0':
                    raise ValueError(f"Invalid version: {version_str}")

        # Validate build format if present
        if build is not None:
            identifiers = build.split('.')
            for identifier in identifiers:
                if not identifier:
                    raise ValueError(f"Invalid version: {version_str}")
                if not re.match(r'^[0-9A-Za-z-]+$', identifier):
                    raise ValueError(f"Invalid version: {version_str}")

        return {
            'major': int(major),
            'minor': int(minor),
            'patch': int(patch),
            'prerelease': prerelease.split('.') if prerelease else None,
            'build': build,
            'original': version_str
        }

    def compare_identifiers(id1, id2):
        """Compare two prerelease identifiers according to semver rules."""
        is_num1 = id1.isdigit()
        is_num2 = id2.isdigit()

        # Both numeric: compare numerically
        if is_num1 and is_num2:
            return int(id1) - int(id2)

        # One numeric, one not: numeric has lower precedence
        if is_num1:
            return -1
        if is_num2:
            return 1

        # Both non-numeric: lexical comparison
        return -1 if id1 < id2 else (1 if id1 > id2 else 0)

    def compare_versions(v1, v2):
        """Compare two parsed versions. Returns -1, 0, or 1."""
        # Compare major.minor.patch
        if v1['major'] != v2['major']:
            return -1 if v1['major'] < v2['major'] else 1
        if v1['minor'] != v2['minor']:
            return -1 if v1['minor'] < v2['minor'] else 1
        if v1['patch'] != v2['patch']:
            return -1 if v1['patch'] < v2['patch'] else 1

        # Compare prerelease
        pre1 = v1['prerelease']
        pre2 = v2['prerelease']

        # No prerelease means higher precedence
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # v1 > v2
        if pre2 is None:
            return -1  # v1 < v2

        # Both have prerelease: compare identifier by identifier
        for i in range(min(len(pre1), len(pre2))):
            cmp = compare_identifiers(pre1[i], pre2[i])
            if cmp != 0:
                return cmp

        # If all compared identifiers are equal, longer prerelease has higher precedence
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1

        return 0

    # Parse all versions
    parsed = []
    for i, version_str in enumerate(versions):
        parsed.append((parse_version(version_str), i))

    # Sort using stable sort with original index as tiebreaker
    sorted_versions = sorted(
        parsed,
        key=cmp_to_key(lambda x, y: compare_versions(x[0], y[0]) or (x[1] - y[1]))
    )

    return [v[0]['original'] for v in sorted_versions]

import re
from typing import Tuple

def sort_versions(versions: list[str]) -> list[str]:
    """
    Sorts version strings in ascending order of Semantic Versioning 2.0.0 precedence.

    Args:
        versions: List of version strings to sort

    Returns:
        Sorted list of version strings

    Raises:
        ValueError: If any string is not a valid semantic version
    """

    def parse_version(version: str) -> Tuple:
        """Parse a version string and return a tuple for comparison."""
        # Regex pattern for semantic versioning 2.0.0
        # MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([a-zA-Z0-9\-\.]+))?(?:\+([a-zA-Z0-9\-\.]+))?$'

        match = re.match(pattern, version)
        if not match:
            raise ValueError(f"Invalid version string: {version}")

        major, minor, patch, prerelease, build = match.groups()

        major, minor, patch = int(major), int(minor), int(patch)

        # Validate prerelease identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            for identifier in prerelease_identifiers:
                if not identifier:
                    raise ValueError(f"Invalid version string: {version}")
                # Check for valid characters
                if not all(c in '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-' for c in identifier):
                    raise ValueError(f"Invalid version string: {version}")
                # Check for leading zeros in numeric identifiers
                if identifier.isdigit() and len(identifier) > 1 and identifier[0] == '0':
                    raise ValueError(f"Invalid version string: {version}")

        # Validate build identifiers
        if build:
            build_identifiers = build.split('.')
            for identifier in build_identifiers:
                if not identifier:
                    raise ValueError(f"Invalid version string: {version}")
                # Check for valid characters
                if not all(c in '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-' for c in identifier):
                    raise ValueError(f"Invalid version string: {version}")

        # Parse prerelease identifiers for comparison
        prerelease_tuple: Tuple = ()
        if prerelease:
            prerelease_list = []
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_list.append((0, int(identifier)))  # 0 for numeric
                else:
                    prerelease_list.append((1, identifier))  # 1 for non-numeric
            prerelease_tuple = tuple(prerelease_list)

        # Return comparison key:
        # 1. Compare major, minor, patch numerically
        # 2. If prerelease exists, it has lower precedence (use empty tuple for no prerelease)
        # 3. For prerelease comparison, numeric identifiers come before non-numeric
        # 4. Build metadata is ignored (not included in tuple)

        # If no prerelease, use a sentinel that sorts after any prerelease
        if prerelease:
            return (major, minor, patch, (0, prerelease_tuple))
        else:
            return (major, minor, patch, (1,))  # (1,) sorts after (0, ...)

    # Validate all versions first
    parsed_versions = []
    for i, version in enumerate(versions):
        try:
            parsed = parse_version(version)
            parsed_versions.append((parsed, i, version))
        except ValueError as e:
            raise ValueError(str(e))

    # Sort by parsed version, maintaining original order for equal versions (stable sort)
    # The tuple includes original index to maintain stability for versions with same precedence
    parsed_versions.sort(key=lambda x: (x[0], x[1]))

    return [v[2] for v in parsed_versions]

import re
from functools import cmp_to_key


def sort_versions(versions: list[str]) -> list[str]:
    """
    Sorts version strings according to Semantic Versioning 2.0.0 precedence.

    Args:
        versions: List of version strings to sort

    Returns:
        Sorted list of version strings

    Raises:
        ValueError: If any version string is invalid
    """

    def parse_version(version_str: str) -> tuple:
        """
        Parse a version string into components.
        Returns a tuple suitable for sorting.
        Raises ValueError if the version is invalid.
        """
        # Pattern for semantic versioning: MAJOR.MINOR.PATCH[-PRERELEASE][+BUILD]
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([a-zA-Z0-9.-]+))?(?:\+([a-zA-Z0-9.-]+))?$'
        match = re.match(pattern, version_str)

        if not match:
            raise ValueError(f"Invalid version: {version_str}")

        major, minor, patch, prerelease, build = match.groups()
        major, minor, patch = int(major), int(minor), int(patch)

        # Validate prerelease identifiers
        if prerelease:
            prerelease_parts = prerelease.split('.')
            for part in prerelease_parts:
                if not part:  # Empty identifier
                    raise ValueError(f"Invalid version: {version_str}")
                if not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise ValueError(f"Invalid version: {version_str}")
                # Check for leading zeros in numeric identifiers
                if part.isdigit() and len(part) > 1 and part[0] == '0':
                    raise ValueError(f"Invalid version: {version_str}")

        # Validate build identifiers (just existence check, leading zeros allowed)
        if build:
            build_parts = build.split('.')
            for part in build_parts:
                if not part:  # Empty identifier
                    raise ValueError(f"Invalid version: {version_str}")
                if not re.match(r'^[0-9A-Za-z-]+$', part):
                    raise ValueError(f"Invalid version: {version_str}")

        # Parse prerelease identifiers for comparison
        prerelease_parts = []
        if prerelease:
            prerelease_parts = prerelease.split('.')

        return (major, minor, patch, prerelease_parts)

    def compare_prerelease(pre1: list, pre2: list) -> int:
        """
        Compare two prerelease identifier lists.
        Returns: -1 if pre1 < pre2, 0 if equal, 1 if pre1 > pre2
        """
        # Shorter prerelease list has lower precedence if all compared parts are equal
        for i in range(min(len(pre1), len(pre2))):
            id1, id2 = pre1[i], pre2[i]
            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare as integers
                val1, val2 = int(id1), int(id2)
                if val1 < val2:
                    return -1
                elif val1 > val2:
                    return 1
            elif is_num1:
                # Numeric has lower precedence than non-numeric
                return -1
            elif is_num2:
                # Non-numeric has higher precedence than numeric
                return 1
            else:
                # Both non-numeric: lexical comparison
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # All compared identifiers are equal
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        else:
            return 0

    def compare_versions(v1: str, v2: str) -> int:
        """
        Compare two version strings.
        Returns: -1 if v1 < v2, 0 if equal, 1 if v1 > v2
        """
        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        # Compare MAJOR.MINOR.PATCH
        if major1 != major2:
            return -1 if major1 < major2 else 1
        if minor1 != minor2:
            return -1 if minor1 < minor2 else 1
        if patch1 != patch2:
            return -1 if patch1 < patch2 else 1

        # MAJOR.MINOR.PATCH are equal
        # Version without prerelease has higher precedence
        if not pre1 and not pre2:
            return 0
        elif not pre1:
            return 1
        elif not pre2:
            return -1

        # Both have prerelease: compare them
        return compare_prerelease(pre1, pre2)

    # Validate all versions first
    for v in versions:
        parse_version(v)

    # Sort using the comparison function (stable sort preserves order for equal elements)
    return sorted(versions, key=cmp_to_key(compare_versions))

import re
from functools import cmp_to_key

def sort_versions(versions: list[str]) -> list[str]:
    """
    Sort version strings according to Semantic Versioning 2.0.0 precedence.

    Args:
        versions: List of version strings to sort

    Returns:
        Sorted list of version strings

    Raises:
        ValueError: If any version string is invalid
    """

    def parse_version(version_str: str) -> tuple:
        """
        Parse a version string into its components.

        Returns a tuple of (major, minor, patch, prerelease_list, build, original_index)
        where prerelease_list is a list of identifiers or None if no prerelease.
        """
        # Pattern for semantic versioning
        pattern = r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z\-]+(?:\.[0-9A-Za-z\-]+)*))?(?:\+([0-9A-Za-z\-]+(?:\.[0-9A-Za-z\-]+)*))?$'

        match = re.match(pattern, version_str)
        if not match:
            raise ValueError(f"Invalid version string: {version_str}")

        major, minor, patch, prerelease, build = match.groups()

        major, minor, patch = int(major), int(minor), int(patch)

        # Validate and parse prerelease
        if prerelease:
            prerelease_parts = prerelease.split('.')
            # Validate each part
            for part in prerelease_parts:
                if not part:
                    raise ValueError(f"Invalid version string: {version_str}")
                # Check for invalid characters
                if not re.match(r'^[0-9A-Za-z\-]+$', part):
                    raise ValueError(f"Invalid version string: {version_str}")
                # Check for leading zeros in numeric identifiers
                if part.isdigit() and len(part) > 1 and part[0] == '0':
                    raise ValueError(f"Invalid version string: {version_str}")
        else:
            prerelease_parts = None

        # Validate build (we don't need to parse it for comparison, just validate)
        if build:
            build_parts = build.split('.')
            for part in build_parts:
                if not part:
                    raise ValueError(f"Invalid version string: {version_str}")
                if not re.match(r'^[0-9A-Za-z\-]+$', part):
                    raise ValueError(f"Invalid version string: {version_str}")

        return (major, minor, patch, prerelease_parts)

    def compare_identifiers(id1, id2) -> int:
        """Compare two prerelease identifiers according to semver rules."""
        is_id1_numeric = id1.isdigit()
        is_id2_numeric = id2.isdigit()

        # Both numeric: compare numerically
        if is_id1_numeric and is_id2_numeric:
            return -1 if int(id1) < int(id2) else (1 if int(id1) > int(id2) else 0)

        # One numeric, one not: numeric is lower precedence
        if is_id1_numeric:
            return -1
        if is_id2_numeric:
            return 1

        # Both non-numeric: compare lexically
        return -1 if id1 < id2 else (1 if id1 > id2 else 0)

    def compare_versions(v1_data, v2_data) -> int:
        """Compare two parsed versions according to semver precedence."""
        major1, minor1, patch1, pre1 = v1_data
        major2, minor2, patch2, pre2 = v2_data

        # Compare major, minor, patch numerically
        for n1, n2 in [(major1, major2), (minor1, minor2), (patch1, patch2)]:
            if n1 < n2:
                return -1
            if n1 > n2:
                return 1

        # If major.minor.patch are equal, check prerelease
        # A version with prerelease has lower precedence than without
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:  # v1 has no prerelease, v2 has
            return 1
        if pre2 is None:  # v2 has no prerelease, v1 has
            return -1

        # Both have prerelease: compare identifier by identifier
        for i in range(min(len(pre1), len(pre2))):
            cmp = compare_identifiers(pre1[i], pre2[i])
            if cmp != 0:
                return cmp

        # If all compared identifiers are equal, the one with more identifiers has higher precedence
        if len(pre1) < len(pre2):
            return -1
        if len(pre1) > len(pre2):
            return 1

        return 0

    # Parse all versions and validate
    parsed_versions = []
    for i, version_str in enumerate(versions):
        parsed = parse_version(version_str)
        parsed_versions.append((parsed, i, version_str))

    # Sort using the comparison function, maintaining original order for equal versions
    parsed_versions.sort(key=cmp_to_key(lambda x, y: compare_versions(x[0], y[0]) or (x[1] - y[1])))

    return [version_str for _, _, version_str in parsed_versions]

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with a single unpaired backslash
    """

    # Validate pattern - check for trailing unescaped backslash
    if pattern.endswith('\\') and not pattern.endswith('\\\\'):
        # Check if it's actually unpaired
        num_backslashes = 0
        for i in range(len(pattern) - 1, -1, -1):
            if pattern[i] == '\\':
                num_backslashes += 1
            else:
                break
        if num_backslashes % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    def parse_pattern(p: str) -> list:
        """Parse pattern into tokens"""
        tokens = []
        i = 0
        while i < len(p):
            if p[i] == '\\':
                if i + 1 >= len(p):
                    raise ValueError("Pattern ends with unpaired backslash")
                tokens.append(('literal', p[i + 1]))
                i += 2
            elif p[i] == '*':
                if i + 1 < len(p) and p[i + 1] == '*':
                    tokens.append(('doublestar', '**'))
                    i += 2
                else:
                    tokens.append(('star', '*'))
                    i += 1
            elif p[i] == '?':
                tokens.append(('question', '?'))
                i += 1
            elif p[i] == '[':
                # Parse character class
                j = i + 1
                if j < len(p) and p[j] == '!':
                    j += 1
                if j < len(p) and p[j] == ']':
                    j += 1
                while j < len(p) and p[j] != ']':
                    j += 1
                if j >= len(p):
                    # No closing bracket, treat [ as literal
                    tokens.append(('literal', '['))
                    i += 1
                else:
                    tokens.append(('charset', p[i:j+1]))
                    i = j + 1
            else:
                tokens.append(('literal', p[i]))
                i += 1
        return tokens

    def parse_segments(pattern: str) -> list:
        """Split pattern by / and handle ** segments specially"""
        segments = pattern.split('/')
        result = []
        for seg in segments:
            result.append(seg)
        return result

    def match_segment(pattern_seg: str, path_seg: str) -> bool:
        """Match a single path segment against a pattern segment"""
        i, j = 0, 0
        while i < len(pattern_seg) or j < len(path_seg):
            if i < len(pattern_seg) and pattern_seg[i] == '\\':
                if i + 1 >= len(pattern_seg):
                    return False
                if j >= len(path_seg) or pattern_seg[i + 1] != path_seg[j]:
                    return False
                i += 2
                j += 1
            elif i < len(pattern_seg) and pattern_seg[i] == '?':
                if j >= len(path_seg):
                    return False
                j += 1
                i += 1
            elif i < len(pattern_seg) and pattern_seg[i] == '*':
                if i + 1 < len(pattern_seg) and pattern_seg[i + 1] == '*':
                    i += 2
                else:
                    # Single star - match any characters in this segment
                    if i + 1 >= len(pattern_seg):
                        return True
                    # Try to match rest of pattern with suffix of path
                    rest_pattern = pattern_seg[i + 1:]
                    for k in range(j, len(path_seg) + 1):
                        if match_segment(rest_pattern, path_seg[k:]):
                            return True
                    return False
            elif i < len(pattern_seg) and pattern_seg[i] == '[':
                if j >= len(path_seg):
                    return False
                j_end = i + 1
                if j_end < len(pattern_seg) and pattern_seg[j_end] == '!':
                    j_end += 1
                if j_end < len(pattern_seg) and pattern_seg[j_end] == ']':
                    j_end += 1
                while j_end < len(pattern_seg) and pattern_seg[j_end] != ']':
                    j_end += 1
                if j_end >= len(pattern_seg):
                    if path_seg[j] != '[':
                        return False
                    i += 1
                    j += 1
                else:
                    if not match_charset(pattern_seg[i:j_end+1], path_seg[j]):
                        return False
                    i = j_end + 1
                    j += 1
            elif i < len(pattern_seg) and pattern_seg[i] == path_seg[j]:
                i += 1
                j += 1
            else:
                return False
        return True

    def match_charset(charset_pattern: str, char: str) -> bool:
        """Match a character against a character class"""
        negated = False
        i = 1
        if charset_pattern[1] == '!':
            negated = True
            i = 2
        charset_pattern = charset_pattern[1:-1]
        if charset_pattern.startswith('!'):
            charset_pattern = charset_pattern[1:]
            negated = True

        matched = False
        i = 0
        while i < len(charset_pattern):
            if i + 2 < len(charset_pattern) and charset_pattern[i + 1] == '-':
                if ord(charset_pattern[i]) <= ord(char) <= ord(charset_pattern[i + 2]):
                    matched = True
                i += 3
            else:
                if charset_pattern[i] == char:
                    matched = True
                i += 1

        return matched != negated

    # Split into segments
    path_segments = path.split('/')
    pattern_segments = parse_segments(pattern)

    # Match using dynamic programming / recursion
    def match_segments(p_idx: int, pa_idx: int) -> bool:
        """Match pattern segments starting at p_idx against path segments starting at pa_idx"""
        # Base cases
        if p_idx >= len(pattern_segments) and pa_idx >= len(path_segments):
            return True
        if p_idx >= len(pattern_segments):
            return False

        p_seg = pattern_segments[p_idx]

        # Check if this is a ** segment (whole segment)
        if p_seg == '**':
            # ** matches zero or more segments
            # Try matching zero segments
            if match_segments(p_idx + 1, pa_idx):
                return True
            # Try matching one or more segments
            if pa_idx < len(path_segments):
                if match_segments(p_idx, pa_idx + 1):
                    return True
            return False

        # Regular segment
        if pa_idx >= len(path_segments):
            return False

        if match_segment(p_seg, path_segments[pa_idx]):
            return match_segments(p_idx + 1, pa_idx + 1)
        return False

    return match_segments(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with a single unpaired backslash
    """

    # Validate: pattern must not end with single unpaired backslash
    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into tokens
    tokens = _parse_pattern(pattern)

    # Split path into segments
    path_segments = path.split('/')

    # Match against path segments
    return _match_tokens(tokens, path_segments, 0, 0)


def _parse_pattern(pattern: str) -> list:
    """Parse a glob pattern into tokens for matching."""
    tokens = []
    i = 0

    while i < len(pattern):
        if pattern[i] == '\\':
            # Escaped character
            if i + 1 < len(pattern):
                tokens.append(('literal', pattern[i + 1]))
                i += 2
            else:
                raise ValueError("Pattern ends with unpaired backslash")
        elif pattern[i] == '*':
            # Check for ** pattern
            if i + 1 < len(pattern) and pattern[i + 1] == '*':
                tokens.append(('doublestar',))
                i += 2
            else:
                tokens.append(('star',))
                i += 1
        elif pattern[i] == '?':
            tokens.append(('question',))
            i += 1
        elif pattern[i] == '[':
            # Character class
            j = i + 1
            negate = False

            if j < len(pattern) and pattern[j] == '!':
                negate = True
                j += 1

            # Find closing bracket
            if j < len(pattern) and pattern[j] == ']':
                # ] right after [ or [!
                j += 1

            bracket_start = j
            while j < len(pattern) and pattern[j] != ']':
                j += 1

            if j >= len(pattern):
                # No closing bracket, treat [ as literal
                tokens.append(('literal', '['))
                i += 1
            else:
                # Found closing bracket
                char_class = pattern[bracket_start:j]
                tokens.append(('charset', char_class, negate))
                i = j + 1
        else:
            tokens.append(('literal', pattern[i]))
            i += 1

    return tokens


def _match_tokens(tokens: list, path_segments: list, token_idx: int, segment_idx: int) -> bool:
    """Recursively match tokens against path segments."""

    # Base case: both exhausted
    if token_idx >= len(tokens) and segment_idx >= len(path_segments):
        return True

    # Base case: tokens exhausted but segments remain
    if token_idx >= len(tokens):
        return False

    # Base case: segments exhausted but tokens remain
    if segment_idx >= len(path_segments):
        # Check if remaining tokens can match empty
        return _can_match_empty(tokens, token_idx)

    token = tokens[token_idx]
    segment = path_segments[segment_idx]

    if token[0] == 'doublestar':
        # ** matches zero or more segments
        # Try matching zero segments
        if _match_tokens(tokens, path_segments, token_idx + 1, segment_idx):
            return True
        # Try matching one or more segments
        if _match_tokens(tokens, path_segments, token_idx, segment_idx + 1):
            return True
        return False
    else:
        # Regular token matches within a single segment
        if _match_segment(tokens, token_idx, segment):
            # Recursively match rest of segment and next token
            rest_segment, next_token_idx = _match_segment_rest(tokens, token_idx, segment)
            if rest_segment is not None and next_token_idx > token_idx:
                if rest_segment == '':
                    return _match_tokens(tokens, path_segments, next_token_idx, segment_idx + 1)
                else:
                    # Continue matching in same segment
                    return _match_tokens_in_segment(tokens, next_token_idx, rest_segment, segment_idx, path_segments)
        return False


def _match_tokens_in_segment(tokens: list, token_idx: int, segment_rest: str, segment_idx: int, path_segments: list) -> bool:
    """Match remaining tokens within the current segment."""

    if token_idx >= len(tokens):
        return segment_rest == ''

    if segment_idx >= len(path_segments):
        # This shouldn't happen in normal flow
        return False

    # This is a simplified approach - we need a better token matching
    # Restart with a more integrated approach
    return False


def _match_segment(tokens: list, token_idx: int, segment: str) -> bool:
    """Check if a token can start matching a segment."""
    if token_idx >= len(tokens):
        return False

    token = tokens[token_idx]

    if token[0] == 'literal':
        return len(segment) > 0 and segment[0] == token[1]
    elif token[0] == 'question':
        return len(segment) > 0
    elif token[0] == 'star':
        return True
    elif token[0] == 'charset':
        return len(segment) > 0 and _match_charset(segment[0], token[1], token[2])

    return False


def _match_segment_rest(tokens: list, token_idx: int, segment: str) -> tuple:
    """Try to match as much of segment as possible with tokens starting at token_idx."""
    # Use a simpler approach: match segment character by character
    pos = 0
    tidx = token_idx

    while tidx < len(tokens) and pos < len(segment):
        token = tokens[tidx]

        if token[0] == 'literal':
            if segment[pos] != token[1]:
                return None, tidx
            pos += 1
            tidx += 1
        elif token[0] == 'question':
            pos += 1
            tidx += 1
        elif token[0] == 'star':
            # Star matches zero or more chars in this segment
            # Try greedy first, then backtrack
            # For now, try to match rest
            remaining = segment[pos:]
            if _try_match_rest(tokens, tidx + 1, remaining):
                return '', tidx + 1
            pos += 1
        elif token[0] == 'charset':
            if not _match_charset(segment[pos], token[1], token[2]):
                return None, tidx
            pos += 1
            tidx += 1
        elif token[0] == 'doublestar':
            # Should not happen in segment context
            return segment[pos:], tidx

    if tidx >= len(tokens):
        if pos == len(segment):
            return '', tidx
        else:
            return None, tidx

    if pos == len(segment):
        return '', tidx

    return None, tidx


def _try_match_rest(tokens: list, token_idx: int, segment: str) -> bool:
    """Try to match remaining segment with remaining tokens."""
    if token_idx >= len(tokens):
        return segment == ''

    token = tokens[token_idx]

    if token[0] == 'literal':
        idx = segment.find(token[1])
        if idx >= 0:
            return _try_match_rest(tokens, token_idx + 1, segment[idx + 1:])
        return False
    elif token[0] == 'star':
        return _try_match_rest(tokens, token_idx + 1, segment)

    return segment == ''


def _match_charset(char: str, charset: str, negate: bool) -> bool:
    """Check if a character matches a character set."""
    i = 0
    matched = False

    while i < len(charset):
        if i + 2 < len(charset) and charset[i + 1] == '-':
            # Range
            start = charset[i]
            end = charset[i + 2]
            if start <= char <= end:
                matched = True
                break
            i += 3
        else:
            if char == charset[i]:
                matched = True
                break
            i += 1

    return matched if not negate else not matched


def _can_match_empty(tokens: list, token_idx: int) -> bool:
    """Check if remaining tokens can match zero segments."""
    while token_idx < len(tokens):
        token = tokens[token_idx]
        if token[0] not in ('star', 'doublestar'):
            return False
        token_idx += 1
    return True


# Rewrite with cleaner recursive approach
def glob_match(pattern: str, path: str) -> bool:
    """Check if a path matches a glob pattern."""

    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Split pattern into segments
    pattern_parts = _split_pattern(pattern)
    path_parts = path.split('/')

    return _match_parts(pattern_parts, path_parts, 0, 0)


def _split_pattern(pattern: str) -> list:
    """Split pattern by / into parts, handling escaped slashes."""
    parts = []
    current = []
    i = 0

    while i < len(pattern):
        if pattern[i] == '\\' and i + 1 < len(pattern):
            current.append(pattern[i:i+2])
            i += 2
        elif pattern[i] == '/':
            parts.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(pattern[i])
            i += 1

    if current or not pattern or pattern.endswith('/'):
        parts.append(''.join(current))

    return parts


def _match_parts(pattern_parts: list, path_parts: list, p_idx: int, path_idx: int) -> bool:
    """Match pattern parts against path parts."""

    if p_idx >= len(pattern_parts) and path_idx >= len(path_parts):
        return True

    if p_idx >= len(pattern_parts):
        return False

    pattern_part = pattern_parts[p_idx]

    if pattern_part == '**':
        # Doublestar matches zero or more path segments
        if _match_parts(pattern_parts, path_parts, p_idx + 1, path_idx):
            return True
        if path_idx < len(path_parts):
            return _match_parts(pattern_parts, path_parts, p_idx, path_idx + 1)
        return False
    else:
        # Regular part must match one path segment
        if path_idx >= len(path_parts):
            return False

        if _match_segment_pattern(pattern_part, path_parts[path_idx]):
            return _match_parts(pattern_parts, path_parts, p_idx + 1, path_idx + 1)

        return False


def _match_segment_pattern(pattern: str, segment: str) -> bool:
    """Match a single segment pattern against a segment."""
    return _match_chars(pattern, segment, 0, 0)


def _match_chars(pattern: str, segment: str, p_idx: int, s_idx: int) -> bool:
    """Recursively match pattern characters against segment characters."""

    if p_idx >= len(pattern) and s_idx >= len(segment):
        return True

    if p_idx >= len(pattern):
        return False

    if pattern[p_idx] == '\\' and p_idx + 1 < len(pattern):
        # Escaped character
        if s_idx >= len(segment) or segment[s_idx] != pattern[p_idx + 1]:
            return False
        return _match_chars(pattern, segment, p_idx + 2, s_idx + 1)

    if pattern[p_idx] == '*':
        # * matches zero or more characters (but not /)
        # Try matching zero characters
        if _match_chars(pattern, segment, p_idx + 1, s_idx):
            return True
        # Try matching one or more characters
        if s_idx < len(segment):
            return _match_chars(pattern, segment, p_idx, s_idx + 1)
        return False

    if pattern[p_idx] == '?':
        # ? matches exactly one character (but not /)
        if s_idx >= len(segment):
            return False
        return _match_chars(pattern, segment, p_idx + 1, s_idx + 1)

    if pattern[p_idx] == '[':
        # Character class
        close_idx = pattern.find(']', p_idx + 1)

        if close_idx == -1:
            # No closing bracket, treat [ as literal
            if s_idx >= len(segment) or segment[s_idx] != '[':
                return False
            return _match_chars(pattern, segment, p_idx + 1, s_idx + 1)

        class_start = p_idx + 1
        negate = False

        if class_start < close_idx and pattern[class_start] == '!':
            negate = True
            class_start += 1

        if class_start == close_idx or (negate and class_start == close_idx):
            # Empty class or [!], treat [ as literal
            if s_idx >= len(segment) or segment[s_idx] != '[':
                return False
            return _match_chars(pattern, segment, p_idx + 1, s_idx + 1)

        if s_idx >= len(segment):
            return False

        char_class = pattern[class_start:close_idx]
        if _char_in_class(segment[s_idx], char_class, negate):
            return _match_chars(pattern, segment, close_idx + 1, s_idx + 1)

        return False

    # Literal character
    if s_idx >= len(segment) or segment[s_idx] != pattern[p_idx]:
        return False

    return _match_chars(pattern, segment, p_idx + 1, s_idx + 1)


def _char_in_class(char: str, char_class: str, negate: bool) -> bool:
    """Check if character is in the character class."""
    i = 0
    matched = False

    while i < len(char_class):
        if i == 0 and char_class[i] == ']':
            # ] at start is literal
            if char == ']':
                matched = True
            i += 1
        elif i == 0 and char_class[i] == '-':
            # - at start is literal
            if char == '-':
                matched = True
            i += 1
        elif i + 2 < len(char_class) and char_class[i + 1] == '-' and char_class[i + 2] != ']':
            # Range (but not if - is last)
            if char_class[i] <= char <= char_class[i + 2]:
                matched = True
            i += 3
        elif i == len(char_class) - 1 and char_class[i] == '-':
            # - at end is literal
            if char == '-':
                matched = True
            i += 1
        else:
            if char == char_class[i]:
                matched = True
            i += 1

    return matched if not negate else not matched

def glob_match(pattern: str, path: str) -> bool:
    """
    Match a slash-separated path against a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A path string to match against

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with an unpaired backslash
    """

    # Validate pattern - check for unpaired backslash at end
    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into tokens
    def parse_pattern(pat: str) -> list:
        """Parse pattern into tokens, handling escapes and special sequences."""
        tokens = []
        i = 0
        while i < len(pat):
            if pat[i] == '\\' and i + 1 < len(pat):
                # Escaped character
                tokens.append(('literal', pat[i + 1]))
                i += 2
            elif pat[i] == '[':
                # Character class
                j = i + 1
                if j < len(pat) and pat[j] == '!':
                    j += 1
                if j < len(pat) and pat[j] == ']':
                    j += 1
                # Find closing bracket
                while j < len(pat) and pat[j] != ']':
                    j += 1
                if j < len(pat):
                    # Found closing bracket
                    tokens.append(('charset', pat[i:j+1]))
                    i = j + 1
                else:
                    # No closing bracket, treat [ as literal
                    tokens.append(('literal', '['))
                    i += 1
            elif pat[i] == '*':
                if i + 1 < len(pat) and pat[i + 1] == '*':
                    tokens.append(('doublestar', None))
                    i += 2
                else:
                    tokens.append(('star', None))
                    i += 1
            elif pat[i] == '?':
                tokens.append(('question', None))
                i += 1
            else:
                tokens.append(('literal', pat[i]))
                i += 1
        return tokens

    def parse_charset(charset_str: str) -> callable:
        """Parse a character class and return a matching function."""
        content = charset_str[1:-1]  # Remove [ and ]
        negated = False
        if content.startswith('!'):
            negated = True
            content = content[1:]

        # Parse ranges and characters
        chars = set()
        i = 0
        while i < len(content):
            if i + 2 < len(content) and content[i + 1] == '-':
                # Range
                start = ord(content[i])
                end = ord(content[i + 2])
                for c in range(start, end + 1):
                    chars.add(chr(c))
                i += 3
            else:
                chars.add(content[i])
                i += 1

        def match_char(c: str) -> bool:
            result = c in chars
            return (not result) if negated else result

        return match_char

    def segment_match(pattern_tokens: list, segment: str) -> bool:
        """Match a single path segment against pattern tokens."""
        seg_idx = 0
        tok_idx = 0

        # Try to match segment character by character
        def try_match(si: int, ti: int) -> bool:
            while ti < len(pattern_tokens):
                tok_type, tok_val = pattern_tokens[ti]

                if tok_type == 'literal':
                    if si >= len(segment) or segment[si] != tok_val:
                        return False
                    si += 1
                    ti += 1
                elif tok_type == 'question':
                    if si >= len(segment):
                        return False
                    si += 1
                    ti += 1
                elif tok_type == 'star':
                    # Star can match empty or any sequence (non-greedy matching)
                    # Try matching rest of pattern with longer segment prefix
                    for next_si in range(si, len(segment) + 1):
                        if try_match(next_si, ti + 1):
                            return True
                    return False
                elif tok_type == 'charset':
                    if si >= len(segment):
                        return False
                    match_func = parse_charset(tok_val)
                    if not match_func(segment[si]):
                        return False
                    si += 1
                    ti += 1
                elif tok_type == 'doublestar':
                    # Should not appear in segment matching
                    ti += 1

            return si == len(segment)

        return try_match(0, 0)

    # Split path into segments
    path_segments = path.split('/')
    pattern_segments = pattern.split('/')

    # Parse each non-doublestar pattern segment into tokens
    parsed_segments = []
    for seg in pattern_segments:
        tokens = parse_pattern(seg)
        # Check if this segment is a pure ** token
        if len(tokens) == 1 and tokens[0][0] == 'doublestar':
            parsed_segments.append(('doublestar', None))
        else:
            parsed_segments.append(('normal', tokens))

    # Match using dynamic programming / recursion
    def match_segments(path_idx: int, pattern_idx: int) -> bool:
        # Base case: both exhausted
        if path_idx == len(path_segments) and pattern_idx == len(parsed_segments):
            return True

        # Pattern exhausted but path remains
        if pattern_idx == len(parsed_segments):
            return path_idx == len(path_segments)

        # Path exhausted but pattern remains
        if path_idx == len(path_segments):
            # All remaining patterns must be ** to match empty path
            for i in range(pattern_idx, len(parsed_segments)):
                if parsed_segments[i][0] != 'doublestar':
                    return False
            return True

        pattern_type, pattern_val = parsed_segments[pattern_idx]

        if pattern_type == 'doublestar':
            # ** matches zero or more path segments
            # Try matching zero segments
            if match_segments(path_idx, pattern_idx + 1):
                return True
            # Try matching one or more segments
            if match_segments(path_idx + 1, pattern_idx):
                return True
            return False
        else:
            # Normal segment pattern
            tokens = pattern_val
            if segment_match(tokens, path_segments[path_idx]):
                return match_segments(path_idx + 1, pattern_idx + 1)
            return False

    return match_segments(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path to match

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with an unpaired backslash
    """

    # Validate pattern - check for unpaired backslash at end
    if pattern.endswith('\\') and (len(pattern) == 1 or pattern[-2] != '\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into tokens
    tokens = _parse_pattern(pattern)

    # Try to match path against tokens
    return _match_tokens(tokens, path, 0, 0)


def _parse_pattern(pattern: str) -> list:
    """Parse a glob pattern into tokens."""
    tokens = []
    i = 0

    while i < len(pattern):
        if pattern[i] == '\\':
            # Escaped character
            i += 1
            if i < len(pattern):
                tokens.append(('literal', pattern[i]))
                i += 1
        elif pattern[i] == '*':
            # Check for ** (but only if it's a whole segment)
            if i + 1 < len(pattern) and pattern[i + 1] == '*':
                # This is ** - will determine if it's a segment in matching
                tokens.append(('doublestar',))
                i += 2
            else:
                tokens.append(('star',))
                i += 1
        elif pattern[i] == '?':
            tokens.append(('question',))
            i += 1
        elif pattern[i] == '[':
            # Character class
            bracket_content = _parse_bracket(pattern, i)
            if bracket_content is None:
                # No closing bracket - treat [ as literal
                tokens.append(('literal', '['))
                i += 1
            else:
                char_set, end_pos = bracket_content
                tokens.append(('charset', char_set))
                i = end_pos
        elif pattern[i] == '/':
            tokens.append(('slash',))
            i += 1
        else:
            tokens.append(('literal', pattern[i]))
            i += 1

    return tokens


def _parse_bracket(pattern: str, start: int) -> tuple | None:
    """Parse a character class [...]. Returns (char_set, end_pos) or None."""
    i = start + 1
    if i >= len(pattern):
        return None

    negated = False
    if pattern[i] == '!':
        negated = True
        i += 1

    # Check for ] right after [ or [!
    chars = set()
    if i < len(pattern) and pattern[i] == ']':
        chars.add(']')
        i += 1

    while i < len(pattern):
        if pattern[i] == ']':
            return (('negated', chars) if negated else ('normal', chars), i + 1)
        elif pattern[i] == '-' and i > start + 1 and chars and i + 1 < len(pattern) and pattern[i + 1] != ']':
            # Range operator
            last_char = next(iter(chars)) if len(chars) == 1 else None
            if last_char is None:
                # Get the last added char - this is a simplification
                chars.add('-')
                i += 1
            else:
                chars.discard(last_char)
                end_char = pattern[i + 1]
                for c in range(ord(last_char), ord(end_char) + 1):
                    chars.add(chr(c))
                i += 2
        else:
            chars.add(pattern[i])
            i += 1

    return None


def _match_tokens(tokens: list, path: str, token_idx: int, path_idx: int) -> bool:
    """Recursively match tokens against path."""

    # If we've consumed all tokens, we must have consumed all path
    if token_idx >= len(tokens):
        return path_idx >= len(path)

    token = tokens[token_idx]

    if token[0] == 'literal':
        if path_idx >= len(path) or path[path_idx] != token[1]:
            return False
        return _match_tokens(tokens, path, token_idx + 1, path_idx + 1)

    elif token[0] == 'question':
        if path_idx >= len(path) or path[path_idx] == '/':
            return False
        return _match_tokens(tokens, path, token_idx + 1, path_idx + 1)

    elif token[0] == 'star':
        # * matches any sequence except /
        # Try matching 0 characters, then 1, then 2, etc.
        for i in range(path_idx, len(path) + 1):
            if i < len(path) and path[i] == '/':
                break
            if _match_tokens(tokens, path, token_idx + 1, i):
                return True
        return False

    elif token[0] == 'doublestar':
        # ** is special only as a whole segment
        # Check if it's a whole segment
        is_whole_segment = _is_doublestar_segment(tokens, token_idx)

        if not is_whole_segment:
            # Treat ** as *
            for i in range(path_idx, len(path) + 1):
                if i < len(path) and path[i] == '/':
                    break
                if _match_tokens(tokens, path, token_idx + 1, i):
                    return True
            return False
        else:
            # ** matches zero or more path segments
            # Try 0 segments, 1 segment, 2 segments, etc.
            for i in range(path_idx, len(path) + 1):
                if i > path_idx and (i > len(path) or path[i] != '/'):
                    continue
                if _match_tokens(tokens, path, token_idx + 1, i):
                    return True
                if i < len(path):
                    # Skip to next /
                    while i < len(path) and path[i] != '/':
                        i += 1
                    if i < len(path):
                        i += 1
                    else:
                        break
                else:
                    break
            return False

    elif token[0] == 'slash':
        if path_idx >= len(path) or path[path_idx] != '/':
            return False
        return _match_tokens(tokens, path, token_idx + 1, path_idx + 1)

    elif token[0] == 'charset':
        if path_idx >= len(path) or path[path_idx] == '/':
            return False
        char_type, chars = token[1]
        matched = path[path_idx] in chars
        if char_type == 'negated':
            matched = not matched
        if not matched:
            return False
        return _match_tokens(tokens, path, token_idx + 1, path_idx + 1)

    return False


def _is_doublestar_segment(tokens: list, idx: int) -> bool:
    """Check if ** at idx is a whole path segment."""
    # ** is a whole segment if:
    # - it's the whole pattern, or
    # - it's at start followed by /, or
    # - it's between two /, or
    # - it's at end after /

    if idx == 0:
        # At start
        if idx + 1 >= len(tokens):
            return True  # whole pattern
        if idx + 1 < len(tokens) and tokens[idx + 1][0] == 'slash':
            return True  # followed by /

    if idx > 0 and tokens[idx - 1][0] == 'slash':
        # After /
        if idx + 1 >= len(tokens):
            return True  # at end
        if idx + 1 < len(tokens) and tokens[idx + 1][0] == 'slash':
            return True  # between /

    return False

def glob_match(pattern: str, path: str) -> bool:
    """
    Match a slash-separated path against a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with an unpaired backslash
    """

    # Validate pattern doesn't end with unpaired backslash
    if pattern.endswith('\\') and not pattern.endswith('\\\\'):
        # Count trailing backslashes
        i = len(pattern) - 1
        while i >= 0 and pattern[i] == '\\':
            i -= 1
        # If odd number of trailing backslashes, the last one is unpaired
        if (len(pattern) - 1 - i) % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    def parse_pattern(pat: str) -> list:
        """Parse pattern into segments separated by /"""
        segments = []
        i = 0
        current = []

        while i < len(pat):
            if pat[i] == '/':
                segments.append(''.join(current))
                current = []
                i += 1
            elif pat[i] == '\\':
                if i + 1 < len(pat):
                    current.append('\\')
                    current.append(pat[i + 1])
                    i += 2
                else:
                    raise ValueError("Pattern ends with unpaired backslash")
            else:
                current.append(pat[i])
                i += 1

        segments.append(''.join(current))
        return segments

    def is_double_star_segment(seg: str) -> bool:
        """Check if a segment is exactly ** (the special glob syntax)"""
        return seg == '**'

    def match_segment(seg: str, text: str) -> bool:
        """Match a single path segment against a pattern segment"""
        si = 0  # segment index
        ti = 0  # text index

        while si < len(seg):
            if seg[si] == '\\' and si + 1 < len(seg):
                # Escaped character
                if ti >= len(text) or seg[si + 1] != text[ti]:
                    return False
                si += 2
                ti += 1
            elif seg[si] == '?':
                # Match exactly one character (not /)
                if ti >= len(text):
                    return False
                ti += 1
                si += 1
            elif seg[si] == '*':
                # Match zero or more characters (not /)
                # Greedy matching: try to match as much as possible
                si += 1
                # If * is at the end, match rest of text
                if si >= len(seg):
                    return True
                # Otherwise, try matching rest of pattern from each position
                for tj in range(ti, len(text) + 1):
                    if match_segment(seg[si:], text[tj:]):
                        return True
                return False
            elif seg[si] == '[':
                # Character class
                if ti >= len(text):
                    return False
                si, matched = match_character_class(seg, si, text[ti])
                if not matched:
                    return False
                ti += 1
            else:
                # Literal character
                if ti >= len(text) or seg[si] != text[ti]:
                    return False
                si += 1
                ti += 1

        return ti == len(text)

    def match_character_class(seg: str, start: int, char: str) -> tuple:
        """
        Match a character class [...]
        Returns: (end_index, matched)
        """
        si = start + 1  # Skip the [

        if si >= len(seg):
            # [ with no closing ], treat as literal
            return (start + 1, char == '[')

        negate = False
        if seg[si] == '!':
            negate = True
            si += 1

        # Check for ] right after [ or [!
        if si < len(seg) and seg[si] == ']':
            # This ] is literal, not the closing bracket
            si += 1

        # Find the closing ]
        matched = False
        while si < len(seg):
            if seg[si] == '\\' and si + 1 < len(seg):
                # Escaped character in bracket
                if seg[si + 1] == char:
                    matched = True
                si += 2
            elif seg[si] == ']':
                # Found closing bracket
                if negate:
                    return (si + 1, not matched)
                else:
                    return (si + 1, matched)
            elif seg[si] == '-' and si > start + 1 and si + 1 < len(seg) and seg[si + 1] != ']':
                # This is a range
                start_char = seg[si - 1]
                si += 1
                end_char = seg[si]
                if start_char <= char <= end_char:
                    matched = True
                si += 1
            else:
                if seg[si] == char:
                    matched = True
                si += 1

        # No closing ], treat opening [ as literal
        if negate:
            return (start + 1, char == '[')
        else:
            return (start + 1, char == '[')

    pattern_segments = parse_pattern(pattern)
    path_segments = path.split('/')

    # Match segments
    pi = 0  # pattern index
    ti = 0  # path index

    while pi < len(pattern_segments):
        if is_double_star_segment(pattern_segments[pi]):
            # ** matches zero or more segments
            pi += 1

            if pi >= len(pattern_segments):
                # ** at the end matches everything
                return True

            # Try matching rest of pattern from each position
            for tj in range(ti, len(path_segments) + 1):
                if match_path_segments(pattern_segments[pi:], path_segments[tj:]):
                    return True
            return False
        else:
            # Regular segment, must match exactly one path segment
            if ti >= len(path_segments):
                return False
            if not match_segment(pattern_segments[pi], path_segments[ti]):
                return False
            pi += 1
            ti += 1

    return ti == len(path_segments)


def match_path_segments(pattern_segs: list, path_segs: list) -> bool:
    """Helper function to match remaining path segments against remaining pattern segments"""
    pi = 0
    ti = 0

    while pi < len(pattern_segs):
        if pattern_segs[pi] == '**':
            pi += 1
            if pi >= len(pattern_segs):
                return True
            for tj in range(ti, len(path_segs) + 1):
                if match_path_segments(pattern_segs[pi:], path_segs[tj:]):
                    return True
            return False
        else:
            if ti >= len(path_segs):
                return False
            if not match_segment(pattern_segs[pi], path_segs[ti]):
                return False
            pi += 1
            ti += 1

    return ti == len(path_segs)


def match_segment(seg: str, text: str) -> bool:
    """Match a single path segment against a pattern segment"""
    si = 0
    ti = 0

    while si < len(seg):
        if seg[si] == '\\' and si + 1 < len(seg):
            if ti >= len(text) or seg[si + 1] != text[ti]:
                return False
            si += 2
            ti += 1
        elif seg[si] == '?':
            if ti >= len(text):
                return False
            ti += 1
            si += 1
        elif seg[si] == '*':
            si += 1
            if si >= len(seg):
                return True
            for tj in range(ti, len(text) + 1):
                if match_segment(seg[si:], text[tj:]):
                    return True
            return False
        elif seg[si] == '[':
            if ti >= len(text):
                return False
            si, matched = match_character_class(seg, si, text[ti])
            if not matched:
                return False
            ti += 1
        else:
            if ti >= len(text) or seg[si] != text[ti]:
                return False
            si += 1
            ti += 1

    return ti == len(text)


def match_character_class(seg: str, start: int, char: str) -> tuple:
    """Match a character class [...]"""
    si = start + 1

    if si >= len(seg):
        return (start + 1, char == '[')

    negate = False
    if seg[si] == '!':
        negate = True
        si += 1

    if si < len(seg) and seg[si] == ']':
        si += 1

    matched = False
    while si < len(seg):
        if seg[si] == '\\' and si + 1 < len(seg):
            if seg[si + 1] == char:
                matched = True
            si += 2
        elif seg[si] == ']':
            if negate:
                return (si + 1, not matched)
            else:
                return (si + 1, matched)
        elif seg[si] == '-' and si > start + 1 and si + 1 < len(seg) and seg[si + 1] != ']':
            start_char = seg[si - 1]
            si += 1
            end_char = seg[si]
            if start_char <= char <= end_char:
                matched = True
            si += 1
        else:
            if seg[si] == char:
                matched = True
            si += 1

    if negate:
        return (start + 1, char == '[')
    else:
        return (start + 1, char == '[')

def glob_match(pattern: str, path: str) -> bool:
    """
    Reports whether a slash-separated path matches a glob pattern.
    The pattern must match the whole path. Matching is case-sensitive.
    """

    # Validate pattern: check for unpaired backslash at end
    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into segments
    pattern_segments = _parse_pattern(pattern)
    path_segments = path.split('/')

    return _match_segments(pattern_segments, path_segments)


def _parse_pattern(pattern: str) -> list:
    """Parse pattern string into segments, handling ** specially."""
    segments = []
    current = []
    i = 0

    while i < len(pattern):
        if pattern[i] == '\\':
            if i + 1 < len(pattern):
                current.append(('literal', pattern[i + 1]))
                i += 2
            else:
                raise ValueError("Pattern ends with unpaired backslash")
        elif pattern[i] == '/':
            if current:
                segments.append(_compile_segment(current))
                current = []
            segments.append('/')
            i += 1
        else:
            current.append(('char', pattern[i]))
            i += 1

    if current:
        segments.append(_compile_segment(current))

    return segments


def _compile_segment(chars: list) -> tuple:
    """Compile a single segment (between slashes) into a matcher."""
    # Check if this is ** (double star as whole segment)
    if len(chars) == 2 and chars[0] == ('char', '*') and chars[1] == ('char', '*'):
        return ('**',)

    # Build regex-like pattern for the segment
    pattern_parts = []
    i = 0

    while i < len(chars):
        typ, val = chars[i]

        if typ == 'literal':
            pattern_parts.append(('literal', val))
            i += 1
        elif typ == 'char':
            if val == '*':
                pattern_parts.append(('*',))
                i += 1
            elif val == '?':
                pattern_parts.append(('?',))
                i += 1
            elif val == '[':
                # Handle character class
                j = i + 1
                negated = False
                if j < len(chars) and chars[j] == ('char', '!'):
                    negated = True
                    j += 1

                # Find closing bracket
                char_set = []
                first = True
                while j < len(chars):
                    t, v = chars[j]
                    if t == 'char' and v == ']' and not first:
                        # Found closing bracket
                        pattern_parts.append(('class', char_set, negated))
                        i = j + 1
                        break
                    else:
                        char_set.append(v if t == 'char' else v)
                        first = False
                        j += 1
                else:
                    # No closing bracket found, treat [ as literal
                    pattern_parts.append(('literal', '['))
                    i += 1
            else:
                pattern_parts.append(('literal', val))
                i += 1
        else:
            i += 1

    return ('segment', pattern_parts)


def _match_segments(pattern_segs: list, path_segs: list) -> bool:
    """Match pattern segments against path segments."""
    p_idx = 0  # pattern index
    ps_idx = 0  # path segment index

    while p_idx < len(pattern_segs):
        elem = pattern_segs[p_idx]

        if elem == '/':
            p_idx += 1
            continue

        if elem[0] == '**':
            # ** matches zero or more path segments
            # Look ahead to find what comes after **
            p_idx += 1

            # Skip any following /
            while p_idx < len(pattern_segs) and pattern_segs[p_idx] == '/':
                p_idx += 1

            if p_idx >= len(pattern_segs):
                # ** at end matches rest of path
                return True

            # Try matching from ps_idx onwards, greedy approach
            for try_ps_idx in range(ps_idx, len(path_segs) + 1):
                if _match_segments(pattern_segs[p_idx:], path_segs[try_ps_idx:]):
                    return True
            return False

        elif elem[0] == 'segment':
            if ps_idx >= len(path_segs):
                return False

            if not _match_segment(elem[1], path_segs[ps_idx]):
                return False

            ps_idx += 1
            p_idx += 1

    return ps_idx == len(path_segs)


def _match_segment(pattern: list, segment: str) -> bool:
    """Match a single pattern segment against a path segment."""
    s_idx = 0
    p_idx = 0

    while p_idx < len(pattern):
        elem = pattern[p_idx]
        typ = elem[0]

        if typ == 'literal':
            if s_idx >= len(segment) or segment[s_idx] != elem[1]:
                return False
            s_idx += 1
            p_idx += 1

        elif typ == '?':
            if s_idx >= len(segment):
                return False
            s_idx += 1
            p_idx += 1

        elif typ == '*':
            # * matches zero or more characters (greedy)
            # Look ahead to see what's next
            p_idx += 1

            if p_idx >= len(pattern):
                # * at end matches rest of segment
                return True

            # Try matching from s_idx onwards
            for try_s_idx in range(s_idx, len(segment) + 1):
                if _match_segment(pattern[p_idx:], segment[try_s_idx:]):
                    return True
            return False

        elif typ == 'class':
            if s_idx >= len(segment):
                return False
            char = segment[s_idx]
            char_set = elem[1]
            negated = elem[2]

            in_set = _char_in_set(char, char_set)
            if negated:
                in_set = not in_set

            if not in_set:
                return False

            s_idx += 1
            p_idx += 1

    return s_idx == len(segment)


def _char_in_set(char: str, char_set: list) -> bool:
    """Check if character is in the character set."""
    i = 0
    while i < len(char_set):
        elem = char_set[i]

        if i + 2 < len(char_set) and char_set[i + 1] == '-':
            # Range like a-z
            start = elem
            end = char_set[i + 2]
            if start <= char <= end:
                return True
            i += 3
        else:
            if elem == char:
                return True
            i += 1

    return False

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with an unpaired backslash
    """

    # Check for invalid pattern (ends with single unpaired backslash)
    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into tokens
    pattern_parts = _parse_pattern(pattern)
    path_parts = path.split('/')

    # Match pattern parts against path parts
    return _match_parts(pattern_parts, path_parts, 0, 0)


def _parse_pattern(pattern: str) -> list:
    """Parse pattern into a list of tokens."""
    parts = []
    i = 0
    current = ""

    while i < len(pattern):
        if pattern[i] == '\\':
            if i + 1 < len(pattern):
                current += pattern[i + 1]
                i += 2
            else:
                raise ValueError("Pattern ends with unpaired backslash")
        elif pattern[i] == '/':
            if current:
                parts.append(('literal', current))
                current = ""
            parts.append(('sep', '/'))
            i += 1
        else:
            current += pattern[i]
            i += 1

    if current:
        parts.append(('literal', current))

    return parts


def _tokenize_segment(segment: str) -> list:
    """Tokenize a pattern segment (between slashes) into tokens."""
    tokens = []
    i = 0

    while i < len(segment):
        if segment[i] == '*':
            if i + 1 < len(segment) and segment[i + 1] == '*':
                tokens.append(('doublestar', '**'))
                i += 2
            else:
                tokens.append(('star', '*'))
                i += 1
        elif segment[i] == '?':
            tokens.append(('question', '?'))
            i += 1
        elif segment[i] == '[':
            # Parse character class
            j = i + 1
            negated = False
            if j < len(segment) and segment[j] == '!':
                negated = True
                j += 1
            # Handle ] right after [ or [!
            if j < len(segment) and segment[j] == ']':
                j += 1
            # Find closing ]
            while j < len(segment) and segment[j] != ']':
                j += 1
            if j < len(segment):
                char_class = segment[i+1:j]
                if negated:
                    char_class = char_class[1:]  # Remove the !
                tokens.append(('charclass', (negated, char_class)))
                i = j + 1
            else:
                # No closing ], treat [ as literal
                tokens.append(('char', '['))
                i += 1
        elif segment[i] == '\\':
            if i + 1 < len(segment):
                tokens.append(('char', segment[i + 1]))
                i += 2
            else:
                raise ValueError("Pattern ends with unpaired backslash")
        else:
            tokens.append(('char', segment[i]))
            i += 1

    return tokens


def _match_parts(pattern_parts: list, path_parts: list, p_idx: int, path_idx: int) -> bool:
    """Recursively match pattern parts against path parts."""

    # Convert pattern to segments
    pattern_segments = []
    current_segment = []

    for part_type, part_val in pattern_parts:
        if part_type == 'sep':
            pattern_segments.append(current_segment)
            current_segment = []
        else:
            current_segment.append((part_type, part_val))
    if current_segment:
        pattern_segments.append(current_segment)

    # Match segments
    return _match_segments(pattern_segments, path_parts, 0, 0)


def _match_segments(pattern_segments: list, path_parts: list, seg_idx: int, path_idx: int) -> bool:
    """Match pattern segments against path parts."""

    # Both exhausted
    if seg_idx >= len(pattern_segments) and path_idx >= len(path_parts):
        return True

    # Pattern exhausted but path remains
    if seg_idx >= len(pattern_segments):
        return False

    segment = pattern_segments[seg_idx]

    # Check if this segment is a bare ** (double star as only element)
    if len(segment) == 1 and segment[0][0] == 'doublestar':
        # ** matches zero or more segments
        # Try matching rest of pattern starting from next segment
        if seg_idx + 1 >= len(pattern_segments):
            # ** at end matches everything remaining
            return True

        # Try all possibilities: match 0, 1, 2, ... remaining path parts
        for skip in range(len(path_parts) - path_idx + 1):
            if _match_segments(pattern_segments, path_parts, seg_idx + 1, path_idx + skip):
                return True
        return False

    # Regular segment matching
    if path_idx >= len(path_parts):
        return False

    path_part = path_parts[path_idx]

    if _match_segment(segment, path_part):
        return _match_segments(pattern_segments, path_parts, seg_idx + 1, path_idx + 1)

    return False


def _match_segment(segment: list, path_part: str) -> bool:
    """Match a single pattern segment against a path part."""
    return _match_segment_recursive(segment, path_part, 0, 0)


def _match_segment_recursive(segment: list, path_part: str, seg_pos: int, path_pos: int) -> bool:
    """Recursively match segment tokens against path part."""

    # Both exhausted
    if seg_pos >= len(segment) and path_pos >= len(path_part):
        return True

    # Segment exhausted but path remains
    if seg_pos >= len(segment):
        return False

    token_type, token_val = segment[seg_pos]

    if token_type == 'char':
        if path_pos >= len(path_part) or path_part[path_pos] != token_val:
            return False
        return _match_segment_recursive(segment, path_part, seg_pos + 1, path_pos + 1)

    elif token_type == 'question':
        if path_pos >= len(path_part):
            return False
        return _match_segment_recursive(segment, path_part, seg_pos + 1, path_pos + 1)

    elif token_type == 'star':
        # * matches zero or more characters
        # Try all possibilities
        for skip in range(len(path_part) - path_pos + 1):
            if _match_segment_recursive(segment, path_part, seg_pos + 1, path_pos + skip):
                return True
        return False

    elif token_type == 'charclass':
        if path_pos >= len(path_part):
            return False
        negated, char_set = token_val
        char = path_part[path_pos]
        matches = _char_in_set(char, char_set)
        if negated:
            matches = not matches
        if not matches:
            return False
        return _match_segment_recursive(segment, path_part, seg_pos + 1, path_pos + 1)

    elif token_type == 'doublestar':
        # This shouldn't happen in segment context
        return False

    elif token_type == 'literal':
        # Match literal string
        literal = token_val
        if path_part[path_pos:path_pos + len(literal)] == literal:
            return _match_segment_recursive(segment, path_part, seg_pos + 1, path_pos + len(literal))
        return False

    return False


def _char_in_set(char: str, char_set: str) -> bool:
    """Check if character is in character set."""
    i = 0
    while i < len(char_set):
        if i + 2 < len(char_set) and char_set[i + 1] == '-':
            # Range
            start = char_set[i]
            end = char_set[i + 2]
            if start <= char <= end:
                return True
            i += 3
        else:
            if char == char_set[i]:
                return True
            i += 1
    return False

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a slash-separated path matches a glob pattern.
    The pattern must match the whole path.
    """

    # Validate pattern - must not end with single unpaired backslash
    if pattern.endswith('\\') and not pattern.endswith('\\\\'):
        # Check if it's truly unpaired
        num_backslashes = 0
        for i in range(len(pattern) - 1, -1, -1):
            if pattern[i] == '\\':
                num_backslashes += 1
            else:
                break
        if num_backslashes % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    return _match_recursive(pattern, path, 0, 0)


def _match_recursive(pattern: str, path: str, p_idx: int, path_idx: int) -> bool:
    """
    Recursively match pattern against path.
    p_idx: current position in pattern
    path_idx: current position in path
    """

    # Both pattern and path consumed
    if p_idx == len(pattern) and path_idx == len(path):
        return True

    # Pattern consumed but path remains
    if p_idx == len(pattern):
        return False

    # Check for ** segment
    if p_idx + 1 < len(pattern) and pattern[p_idx:p_idx+2] == '**':
        # Check if ** is a whole segment
        is_whole_segment = False

        if p_idx == 0 and (p_idx + 2 == len(pattern) or pattern[p_idx + 2] == '/'):
            is_whole_segment = True
        elif p_idx > 0 and pattern[p_idx - 1] == '/' and (p_idx + 2 == len(pattern) or pattern[p_idx + 2] == '/'):
            is_whole_segment = True

        if is_whole_segment:
            # ** matches zero or more whole segments
            if p_idx + 2 == len(pattern):
                # ** at end matches everything remaining
                return True

            # ** followed by /
            next_idx = p_idx + 3  # skip ** and /

            # Try matching zero segments: skip ** and / in pattern
            if _match_recursive(pattern, path, next_idx, path_idx):
                return True

            # Try matching one or more segments
            # Find next / in path or end of path
            slash_pos = path.find('/', path_idx)
            if slash_pos == -1:
                slash_pos = len(path)

            # Try consuming characters up to next slash
            pos = path_idx
            while pos <= len(path):
                if _match_recursive(pattern, path, next_idx, pos):
                    return True
                if pos == len(path):
                    break
                # Move to next segment
                next_slash = path.find('/', pos + 1)
                if next_slash == -1:
                    pos = len(path)
                else:
                    pos = next_slash

            return False

    # Handle escape character
    if pattern[p_idx] == '\\':
        if p_idx + 1 >= len(pattern):
            raise ValueError("Pattern ends with unpaired backslash")
        # Match the next character literally
        if path_idx < len(path) and path[path_idx] == pattern[p_idx + 1]:
            return _match_recursive(pattern, path, p_idx + 2, path_idx + 1)
        return False

    # Handle character class [...]
    if pattern[p_idx] == '[':
        bracket_end = _find_closing_bracket(pattern, p_idx)
        if bracket_end == -1:
            # No closing bracket, treat [ as literal
            if path_idx < len(path) and path[path_idx] == '[':
                return _match_recursive(pattern, path, p_idx + 1, path_idx + 1)
            return False

        if path_idx >= len(path) or path[path_idx] == '/':
            return False

        char_class = pattern[p_idx+1:bracket_end]
        if _char_matches_class(path[path_idx], char_class):
            return _match_recursive(pattern, path, bracket_end + 1, path_idx + 1)
        return False

    # Handle * (not part of **)
    if pattern[p_idx] == '*':
        # * matches any sequence except /
        # Try matching zero characters
        if _match_recursive(pattern, path, p_idx + 1, path_idx):
            return True
        # Try matching one or more characters until /
        pos = path_idx
        while pos < len(path) and path[pos] != '/':
            pos += 1
            if _match_recursive(pattern, path, p_idx + 1, pos):
                return True
        return False

    # Handle ? - matches exactly one char except /
    if pattern[p_idx] == '?':
        if path_idx >= len(path) or path[path_idx] == '/':
            return False
        return _match_recursive(pattern, path, p_idx + 1, path_idx + 1)

    # Regular character - must match
    if path_idx >= len(path) or pattern[p_idx] != path[path_idx]:
        return False

    return _match_recursive(pattern, path, p_idx + 1, path_idx + 1)


def _find_closing_bracket(pattern: str, start: int) -> int:
    """Find the closing bracket for a character class, or -1 if not found."""
    i = start + 1

    # Special case: ] right after [ or [!
    if i < len(pattern) and pattern[i] == ']':
        i += 1
    elif i < len(pattern) and pattern[i] == '!' and i + 1 < len(pattern) and pattern[i + 1] == ']':
        i += 2

    while i < len(pattern):
        if pattern[i] == ']':
            return i
        i += 1

    return -1


def _char_matches_class(char: str, char_class: str) -> bool:
    """Check if char matches the character class."""
    if not char_class:
        return False

    # Check for negation
    negated = False
    start_idx = 0
    if char_class[0] == '!':
        negated = True
        start_idx = 1

    matched = False
    i = start_idx

    while i < len(char_class):
        # Check for range a-z
        if i + 2 < len(char_class) and char_class[i + 1] == '-':
            # This is a range
            start_char = char_class[i]
            end_char = char_class[i + 2]
            if start_char <= char <= end_char:
                matched = True
                break
            i += 3
        else:
            if char_class[i] == char:
                matched = True
                break
            i += 1

    return matched if not negated else not matched

def glob_match(pattern: str, path: str) -> bool:
    """Match a path against a glob pattern."""

    def match_segment(pat: str, seg: str, pat_pos: int = 0, seg_pos: int = 0) -> bool:
        """Match a single path segment (no /) against a pattern segment."""
        while pat_pos < len(pat) or seg_pos < len(seg):
            if pat_pos >= len(pat):
                return seg_pos >= len(seg)

            if pat[pat_pos] == '\\':
                if pat_pos + 1 >= len(pat):
                    raise ValueError("Pattern ends with unpaired backslash")
                pat_pos += 1
                if seg_pos >= len(seg) or pat[pat_pos] != seg[seg_pos]:
                    return False
                pat_pos += 1
                seg_pos += 1
            elif pat[pat_pos] == '?':
                if seg_pos >= len(seg):
                    return False
                pat_pos += 1
                seg_pos += 1
            elif pat[pat_pos] == '*':
                # Try matching 0+ characters
                pat_pos += 1
                for i in range(seg_pos, len(seg) + 1):
                    if match_segment(pat, seg, pat_pos, i):
                        return True
                return False
            elif pat[pat_pos] == '[':
                if seg_pos >= len(seg):
                    return False
                matched, new_pat_pos = match_bracket(pat, pat_pos, seg[seg_pos])
                if not matched:
                    return False
                pat_pos = new_pat_pos
                seg_pos += 1
            else:
                if seg_pos >= len(seg) or pat[pat_pos] != seg[seg_pos]:
                    return False
                pat_pos += 1
                seg_pos += 1

        return True

    def match_bracket(pat: str, idx: int, char: str) -> tuple:
        """Match character class at pat[idx]. Returns (matched, next_idx)."""
        idx += 1
        if idx >= len(pat):
            return False, len(pat)

        negated = pat[idx] == '!'
        if negated:
            idx += 1

        if idx < len(pat) and pat[idx] == ']':
            if char == ']':
                return not negated, idx + 1
            idx += 1

        matched = False
        while idx < len(pat) and pat[idx] != ']':
            if pat[idx] == '-' and idx + 1 < len(pat) and pat[idx + 1] != ']':
                # Could be range or literal -
                if idx == 0 or pat[idx - 1] == '[' or (idx > 0 and pat[idx - 1] == '!'):
                    # Literal -
                    if char == '-':
                        matched = True
                    idx += 1
                else:
                    # Range
                    start = pat[idx - 1]
                    end = pat[idx + 1]
                    if start <= char <= end:
                        matched = True
                    idx += 2
            else:
                if pat[idx] == char:
                    matched = True
                idx += 1

        if idx >= len(pat):
            return False, len(pat)

        if negated:
            matched = not matched
        return matched, idx + 1

    def match_path(pat: str, pth: str) -> bool:
        """Match entire path with ** support."""
        pat_parts = pat.split('/')
        path_parts = pth.split('/')

        return match_parts(pat_parts, path_parts, 0, 0)

    def match_parts(pat_parts: list, path_parts: list, pi: int, pathi: int) -> bool:
        """Match pattern parts against path parts."""
        if pi >= len(pat_parts):
            return pathi >= len(path_parts)
        if pathi >= len(path_parts):
            # Check if remaining are all **
            while pi < len(pat_parts):
                if pat_parts[pi] != '**':
                    return False
                pi += 1
            return True

        pat_part = pat_parts[pi]

        if pat_part == '**':
            # ** matches 0+ path segments
            # Try each possibility
            for skip in range(len(path_parts) - pathi + 1):
                if match_parts(pat_parts, path_parts, pi + 1, pathi + skip):
                    return True
            return False
        else:
            # Match single segment
            if match_segment(pat_part, path_parts[pathi]):
                return match_parts(pat_parts, path_parts, pi + 1, pathi + 1)
            return False

    return match_path(pattern, path)

def glob_match(pattern: str, path: str) -> bool:
    """
    Reports whether a slash-separated path matches a glob pattern.
    The pattern must match the whole path. Matching is case-sensitive.
    """

    # Validate pattern - check for unpaired backslash at end
    if pattern.endswith('\\') and not pattern.endswith('\\\\'):
        # Count trailing backslashes
        count = 0
        for i in range(len(pattern) - 1, -1, -1):
            if pattern[i] == '\\':
                count += 1
            else:
                break
        if count % 2 == 1:  # Odd number means unpaired at end
            raise ValueError("Pattern ends with unpaired backslash")

    # Split pattern and path into segments
    pattern_segments = pattern.split('/')
    path_segments = path.split('/')

    def match_segment(pattern_seg: str, path_seg: str) -> bool:
        """Match a single segment (no slashes allowed in pattern)"""
        pi = 0  # pattern index
        si = 0  # string index

        while pi < len(pattern_seg):
            if pattern_seg[pi] == '\\':
                if pi + 1 >= len(pattern_seg):
                    raise ValueError("Pattern ends with unpaired backslash")
                # Next character is literal
                pi += 1
                if si >= len(path_seg) or path_seg[si] != pattern_seg[pi]:
                    return False
                pi += 1
                si += 1
            elif pattern_seg[pi] == '?':
                if si >= len(path_seg):
                    return False
                pi += 1
                si += 1
            elif pattern_seg[pi] == '*':
                # Match any sequence of characters (greedy)
                pi += 1
                if pi >= len(pattern_seg):
                    # * at end matches rest of segment
                    return True
                # Try to match rest of pattern at each position
                for i in range(si, len(path_seg) + 1):
                    if match_segment(pattern_seg[pi:], path_seg[i:]):
                        return True
                return False
            elif pattern_seg[pi] == '[':
                # Character class
                pi += 1
                if pi >= len(pattern_seg):
                    # Unclosed bracket is literal
                    if si >= len(path_seg) or path_seg[si] != '[':
                        return False
                    si += 1
                    pi = len(pattern_seg) - 1  # Adjust since we'll increment at loop end
                else:
                    negate = False
                    if pattern_seg[pi] == '!':
                        negate = True
                        pi += 1

                    # Find closing bracket
                    char_set = []
                    if pi < len(pattern_seg) and pattern_seg[pi] == ']':
                        char_set.append(']')
                        pi += 1

                    while pi < len(pattern_seg) and pattern_seg[pi] != ']':
                        if pattern_seg[pi] == '-' and char_set and pi + 1 < len(pattern_seg) and pattern_seg[pi + 1] != ']':
                            # Range
                            start = ord(char_set[-1])
                            pi += 1
                            end = ord(pattern_seg[pi])
                            char_set.pop()
                            for c in range(start, end + 1):
                                char_set.append(chr(c))
                        else:
                            char_set.append(pattern_seg[pi])
                        pi += 1

                    if pi >= len(pattern_seg):
                        # No closing bracket - treat [ as literal
                        if si >= len(path_seg) or path_seg[si] != '[':
                            return False
                        si += 1
                        pi = len(pattern_seg)  # Move to end
                    else:
                        # Found closing bracket
                        if si >= len(path_seg):
                            return False
                        char = path_seg[si]
                        matched = char in char_set
                        if negate:
                            matched = not matched
                        if not matched:
                            return False
                        si += 1
                        pi += 1  # Skip the ]
            else:
                # Literal character
                if si >= len(path_seg) or path_seg[si] != pattern_seg[pi]:
                    return False
                pi += 1
                si += 1

        return si == len(path_seg)

    def match_segments(p_idx: int, s_idx: int) -> bool:
        """Match pattern segments against path segments, handling **"""
        # If we've consumed both, we match
        if p_idx >= len(pattern_segments) and s_idx >= len(path_segments):
            return True

        # If we've consumed pattern but not path, fail (unless last was **)
        if p_idx >= len(pattern_segments):
            return False

        # If we've consumed path but not pattern
        if s_idx >= len(path_segments):
            # Remaining pattern segments must all be ** to match
            for i in range(p_idx, len(pattern_segments)):
                if pattern_segments[i] != '**':
                    return False
            return True

        curr_pattern = pattern_segments[p_idx]

        if curr_pattern == '**':
            # ** matches zero or more segments
            # Try matching zero segments
            if match_segments(p_idx + 1, s_idx):
                return True
            # Try matching one or more segments
            if match_segments(p_idx, s_idx + 1):
                return True
            return False
        else:
            # Regular segment - must match current path segment
            if match_segment(curr_pattern, path_segments[s_idx]):
                return match_segments(p_idx + 1, s_idx + 1)
            return False

    return match_segments(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with an unpaired backslash
    """

    # Check for invalid pattern ending with unpaired backslash
    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        raise ValueError("Pattern cannot end with an unpaired backslash")

    # Parse pattern into tokens
    tokens = _parse_pattern(pattern)

    # Split path into segments
    path_segments = path.split('/')

    # Match tokens against path segments
    return _match_tokens(tokens, path_segments, 0, 0)


def _parse_pattern(pattern: str) -> list:
    """Parse pattern into tokens for easier matching."""
    tokens = []
    i = 0
    current_segment = []

    while i < len(pattern):
        if pattern[i] == '\\':
            if i + 1 < len(pattern):
                current_segment.append(('literal', pattern[i + 1]))
                i += 2
            else:
                raise ValueError("Pattern cannot end with an unpaired backslash")
        elif pattern[i] == '/':
            if current_segment:
                tokens.append(('segment', current_segment))
            current_segment = []
            i += 1
        else:
            current_segment.append(('char', pattern[i]))
            i += 1

    if current_segment:
        tokens.append(('segment', current_segment))

    # Post-process to identify ** segments
    processed_tokens = []
    for token_type, content in tokens:
        if token_type == 'segment':
            if len(content) == 1 and content[0] == ('char', '*') and len(content[0][1]) == 1:
                # Check if this is actually **
                segment_str = ''.join(c for _, c in content)
                if segment_str == '**':
                    processed_tokens.append(('doublestar', None))
                else:
                    processed_tokens.append(('segment', content))
            elif (len(content) == 2 and 
                  content[0] == ('char', '*') and 
                  content[1] == ('char', '*')):
                processed_tokens.append(('doublestar', None))
            else:
                processed_tokens.append(('segment', content))
        else:
            processed_tokens.append((token_type, content))

    return processed_tokens


def _parse_pattern(pattern: str) -> list:
    """Parse pattern into tokens for easier matching."""
    tokens = []
    i = 0

    while i < len(pattern):
        if pattern[i] == '\\':
            if i + 1 < len(pattern):
                tokens.append(('literal', pattern[i + 1]))
                i += 2
            else:
                raise ValueError("Pattern cannot end with an unpaired backslash")
        elif pattern[i:i+2] == '**':
            # Check if this is a whole segment
            before_ok = (i == 0 or pattern[i-1] == '/')
            after_ok = (i + 2 == len(pattern) or pattern[i+2] == '/')
            if before_ok and after_ok:
                tokens.append(('doublestar',))
                i += 2
            else:
                # ** not a whole segment, treat as literal *
                tokens.append(('star',))
                i += 1
        elif pattern[i] == '*':
            tokens.append(('star',))
            i += 1
        elif pattern[i] == '?':
            tokens.append(('question',))
            i += 1
        elif pattern[i] == '/':
            tokens.append(('slash',))
            i += 1
        elif pattern[i] == '[':
            # Parse character class
            end = _find_bracket_close(pattern, i)
            if end == -1:
                tokens.append(('literal', '['))
                i += 1
            else:
                bracket_content = pattern[i+1:end]
                negate = bracket_content.startswith('!')
                if negate:
                    bracket_content = bracket_content[1:]
                tokens.append(('bracket', (negate, bracket_content)))
                i = end + 1
        else:
            tokens.append(('literal', pattern[i]))
            i += 1

    return tokens


def _find_bracket_close(pattern: str, start: int) -> int:
    """Find the closing bracket for a character class, or -1 if not found."""
    i = start + 1
    if i < len(pattern) and pattern[i] == '!':
        i += 1
    if i < len(pattern) and pattern[i] == ']':
        i += 1

    while i < len(pattern):
        if pattern[i] == ']':
            return i
        i += 1

    return -1


def _match_bracket(content: str, char: str) -> bool:
    """Check if a character matches a bracket expression."""
    negate, chars = content
    matched = _bracket_matches(chars, char)
    return (not matched) if negate else matched


def _bracket_matches(chars: str, char: str) -> bool:
    """Check if char matches the bracket content."""
    i = 0
    while i < len(chars):
        if chars[i] == '-' and i + 1 < len(chars) and i > 0:
            # This is a range
            start = chars[i-1]
            end = chars[i+1]
            if start <= char <= end:
                return True
            i += 2
        elif chars[i] == char:
            return True
        else:
            i += 1
    return False


def _match_tokens(tokens: list, segments: list, token_idx: int, seg_idx: int) -> bool:
    """Recursively match tokens against path segments."""
    if token_idx == len(tokens):
        return seg_idx == len(segments)

    token = tokens[token_idx]

    if token[0] == 'doublestar':
        # ** matches zero or more segments
        # Try matching zero segments
        if _match_tokens(tokens, segments, token_idx + 1, seg_idx):
            return True
        # Try matching one or more segments
        if seg_idx < len(segments):
            if _match_tokens(tokens, segments, token_idx + 1, seg_idx + 1):
                return True
            if _match_tokens(tokens, segments, token_idx, seg_idx + 1):
                return True
        return False

    elif token[0] == 'slash':
        # Slash token (shouldn't happen if we parse correctly)
        return _match_tokens(tokens, segments, token_idx + 1, seg_idx)

    else:
        # Regular segment pattern
        if seg_idx >= len(segments):
            return False

        segment_pattern = token[1] if len(token) > 1 else []
        segment_text = segments[seg_idx]

        if _match_segment(segment_pattern, segment_text):
            return _match_tokens(tokens, segments, token_idx + 1, seg_idx + 1)
        return False


def _parse_pattern(pattern: str) -> list:
    """Parse pattern into segment tokens."""
    tokens = []
    i = 0

    while i < len(pattern):
        if pattern[i] == '\\':
            if i + 1 < len(pattern):
                if not tokens or tokens[-1][0] != 'segment':
                    tokens.append(('segment', []))
                tokens[-1][1].append(('literal', pattern[i+1]))
                i += 2
            else:
                raise ValueError("Pattern cannot end with an unpaired backslash")
        elif pattern[i:i+2] == '**':
            before_ok = (i == 0 or pattern[i-1] == '/')
            after_ok = (i + 2 == len(pattern) or pattern[i+2] == '/')
            if before_ok and after_ok:
                tokens.append(('doublestar',))
                i += 2
            else:
                if not tokens or tokens[-1][0] != 'segment':
                    tokens.append(('segment', []))
                tokens[-1][1].append(('star',))
                i += 1
        elif pattern[i] == '/':
            tokens.append(('slash',))
            i += 1
        elif pattern[i] == '*':
            if not tokens or tokens[-1][0] != 'segment':
                tokens.append(('segment', []))
            tokens[-1][1].append(('star',))
            i += 1
        elif pattern[i] == '?':
            if not tokens or tokens[-1][0] != 'segment':
                tokens.append(('segment', []))
            tokens[-1][1].append(('question',))
            i += 1
        elif pattern[i] == '[':
            end = _find_bracket_close(pattern, i)
            if end == -1:
                if not tokens or tokens[-1][0] != 'segment':
                    tokens.append(('segment', []))
                tokens[-1][1].append(('literal', '['))
                i += 1
            else:
                bracket_content = pattern[i+1:end]
                negate = bracket_content.startswith('!')
                if negate:
                    bracket_content = bracket_content[1:]
                if not tokens or tokens[-1][0] != 'segment':
                    tokens.append(('segment', []))
                tokens[-1][1].append(('bracket', (negate, bracket_content)))
                i = end + 1
        else:
            if not tokens or tokens[-1][0] != 'segment':
                tokens.append(('segment', []))
            tokens[-1][1].append(('literal', pattern[i]))
            i += 1

    return tokens


def _match_tokens(tokens: list, segments: list, token_idx: int, seg_idx: int) -> bool:
    """Recursively match tokens against path segments."""
    if token_idx == len(tokens):
        return seg_idx == len(segments)

    token = tokens[token_idx]

    if token[0] == 'doublestar':
        # ** matches zero or more segments
        if _match_tokens(tokens, segments, token_idx + 1, seg_idx):
            return True
        if seg_idx < len(segments):
            if _match_tokens(tokens, segments, token_idx, seg_idx + 1):
                return True
        return False

    elif token[0] == 'slash':
        return _match_tokens(tokens, segments, token_idx + 1, seg_idx)

    elif token[0] == 'segment':
        if seg_idx >= len(segments):
            return False
        if _match_segment(token[1], segments[seg_idx]):
            return _match_tokens(tokens, segments, token_idx + 1, seg_idx + 1)
        return False

    return _match_tokens(tokens, segments, token_idx + 1, seg_idx)


def _match_segment(pattern_parts: list, segment: str) -> bool:
    """Match a single path segment against pattern parts."""
    return _match_segment_recursive(pattern_parts, segment, 0, 0)


def _match_segment_recursive(pattern_parts: list, segment: str, p_idx: int, s_idx: int) -> bool:
    """Recursively match pattern parts against segment characters."""
    if p_idx == len(pattern_parts):
        return s_idx == len(segment)

    part = pattern_parts[p_idx]
    part_type = part[0]

    if part_type == 'literal':
        if s_idx >= len(segment) or segment[s_idx] != part[1]:
            return False
        return _match_segment_recursive(pattern_parts, segment, p_idx + 1, s_idx + 1)

    elif part_type == 'question':
        if s_idx >= len(segment):
            return False
        return _match_segment_recursive(pattern_parts, segment, p_idx + 1, s_idx + 1)

    elif part_type == 'star':
        # * matches zero or more characters
        if _match_segment_recursive(pattern_parts, segment, p_idx + 1, s_idx):
            return True
        if s_idx < len(segment):
            if _match_segment_recursive(pattern_parts, segment, p_idx, s_idx + 1):
                return True
        return False

    elif part_type == 'bracket':
        if s_idx >= len(segment):
            return False
        negate, chars = part[1]
        matched = _bracket_matches(chars, segment[s_idx])
        if (not matched) if negate else matched:
            return _match_segment_recursive(pattern_parts, segment, p_idx + 1, s_idx + 1)
        return False

    return _match_segment_recursive(pattern_parts, segment, p_idx + 1, s_idx)


def _bracket_matches(chars: str, char: str) -> bool:
    """Check if char matches the bracket content."""
    i = 0
    while i < len(chars):
        if i + 2 < len(chars) and chars[i+1] == '-':
            # Range
            if chars[i] <= char <= chars[i+2]:
                return True
            i += 3
        else:
            if chars[i] == char:
                return True
            i += 1
    return False

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with a single unpaired backslash
    """

    # Validate pattern - check for trailing single backslash
    if pattern.endswith('\\') and not pattern.endswith('\\\\'):
        # Count consecutive backslashes at the end
        count = 0
        for i in range(len(pattern) - 1, -1, -1):
            if pattern[i] == '\\':
                count += 1
            else:
                break
        if count % 2 == 1:  # Odd number of backslashes means unpaired
            raise ValueError("Pattern ends with unpaired backslash")

    def parse_pattern(p: str) -> list:
        """Parse pattern into segments, handling escape sequences."""
        segments = []
        i = 0
        current_segment = ""

        while i < len(p):
            if p[i] == '\\' and i + 1 < len(p):
                # Escape sequence
                current_segment += p[i + 1]
                i += 2
            elif p[i] == '/':
                # Segment boundary
                segments.append(current_segment)
                current_segment = ""
                i += 1
            else:
                current_segment += p[i]
                i += 1

        segments.append(current_segment)
        return segments

    def segment_matches(pattern_seg: str, path_seg: str) -> bool:
        """Check if a single path segment matches a pattern segment."""
        p_idx = 0
        s_idx = 0

        while p_idx < len(pattern_seg):
            if pattern_seg[p_idx] == '?':
                if s_idx >= len(path_seg):
                    return False
                p_idx += 1
                s_idx += 1
            elif pattern_seg[p_idx] == '*':
                # Find the next non-* character in pattern
                p_idx += 1

                # Handle consecutive *
                while p_idx < len(pattern_seg) and pattern_seg[p_idx] == '*':
                    p_idx += 1

                if p_idx >= len(pattern_seg):
                    # * at end matches rest of segment
                    return True

                # Try to match rest of pattern at different positions
                rest_pattern = pattern_seg[p_idx:]
                for i in range(s_idx, len(path_seg) + 1):
                    if segment_matches(rest_pattern, path_seg[i:]):
                        return True
                return False
            elif pattern_seg[p_idx] == '[':
                # Character class
                if s_idx >= len(path_seg):
                    return False

                char = path_seg[s_idx]
                p_idx += 1
                negate = False

                if p_idx < len(pattern_seg) and pattern_seg[p_idx] == '!':
                    negate = True
                    p_idx += 1

                # Handle ] right after [ or [!
                if p_idx < len(pattern_seg) and pattern_seg[p_idx] == ']':
                    chars = {']'}
                    p_idx += 1
                else:
                    chars = set()

                # Parse character class
                while p_idx < len(pattern_seg) and pattern_seg[p_idx] != ']':
                    if pattern_seg[p_idx] == '-' and len(chars) > 0 and p_idx + 1 < len(pattern_seg) and pattern_seg[p_idx + 1] != ']':
                        # Range
                        p_idx += 1
                        start = list(chars)[-1]
                        chars.discard(start)
                        end = pattern_seg[p_idx]
                        for c_code in range(ord(start), ord(end) + 1):
                            chars.add(chr(c_code))
                        p_idx += 1
                    else:
                        chars.add(pattern_seg[p_idx])
                        p_idx += 1

                if p_idx < len(pattern_seg):
                    p_idx += 1  # Skip closing ]

                matched = char in chars
                if negate:
                    matched = not matched

                if not matched:
                    return False

                s_idx += 1
            else:
                # Literal character
                if s_idx >= len(path_seg) or path_seg[s_idx] != pattern_seg[p_idx]:
                    return False
                p_idx += 1
                s_idx += 1

        return s_idx == len(path_seg)

    # Parse pattern into segments
    pattern_segments = parse_pattern(pattern)
    path_segments = path.split('/')

    # Check for ** segments
    def matches_recursive(pat_idx: int, path_idx: int) -> bool:
        """Recursively match pattern segments against path segments."""
        if pat_idx >= len(pattern_segments):
            return path_idx >= len(path_segments)

        pat_seg = pattern_segments[pat_idx]

        # Check if this is a ** segment
        if pat_seg == "**":
            # ** matches zero or more segments
            # Try matching from current position
            if matches_recursive(pat_idx + 1, path_idx):
                return True
            # Try skipping one path segment
            if path_idx < len(path_segments):
                return matches_recursive(pat_idx, path_idx + 1)
            return False
        else:
            # Regular segment - must match exactly one path segment
            if path_idx >= len(path_segments):
                return False
            if segment_matches(pat_seg, path_segments[path_idx]):
                return matches_recursive(pat_idx + 1, path_idx + 1)
            return False

    return matches_recursive(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    """
    Matches a slash-separated path against a glob pattern.

    Pattern syntax:
    - ? matches exactly one character other than /
    - * matches any sequence of characters other than /
    - ** as a whole segment matches zero or more path segments
    - [...] matches one character from the set (with ranges and negation support)
    - \ escapes the next character
    """

    # Validate pattern - no unpaired backslash at the end
    if pattern.endswith('\\') and not pattern.endswith('\\\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into segments
    pattern_segments = _parse_pattern_segments(pattern)
    path_segments = path.split('/')

    return _match_segments(pattern_segments, path_segments, 0, 0)


def _parse_pattern_segments(pattern: str) -> list:
    """Parse pattern into list of (is_glob_star, segment_pattern) tuples."""
    segments = []
    current = ""
    i = 0

    while i < len(pattern):
        if pattern[i] == '\\':
            if i + 1 >= len(pattern):
                raise ValueError("Pattern ends with unpaired backslash")
            current += pattern[i + 1]
            i += 2
        elif pattern[i] == '/':
            if current or not segments:  # Don't skip empty segments at boundaries
                segments.append((False, current))
            current = ""
            i += 1
        else:
            current += pattern[i]
            i += 1

    if current or not segments:
        segments.append((False, current))

    # Post-process to identify ** segments
    result = []
    for _, seg in segments:
        if seg == '**':
            result.append((True, '**'))
        else:
            result.append((False, seg))

    return result


def _match_segments(pattern_segs: list, path_segs: list, p_idx: int, s_idx: int) -> bool:
    """Recursively match pattern segments against path segments."""

    # Both exhausted - match
    if p_idx >= len(pattern_segs) and s_idx >= len(path_segs):
        return True

    # Pattern exhausted but path remains - no match
    if p_idx >= len(pattern_segs):
        return False

    is_glob_star, pattern_seg = pattern_segs[p_idx]

    # Handle ** segment
    if is_glob_star:
        # ** matches zero or more segments
        # Try matching zero segments (skip the **)
        if _match_segments(pattern_segs, path_segs, p_idx + 1, s_idx):
            return True

        # Try matching one or more segments
        if s_idx < len(path_segs):
            if _match_segments(pattern_segs, path_segs, p_idx, s_idx + 1):
                return True

        return False

    # Handle regular pattern segment
    if s_idx >= len(path_segs):
        return False

    path_seg = path_segs[s_idx]

    # Match current segment
    if _match_segment(pattern_seg, path_seg):
        return _match_segments(pattern_segs, path_segs, p_idx + 1, s_idx + 1)

    return False


def _match_segment(pattern: str, text: str) -> bool:
    """Match a single pattern segment against a path segment."""
    p_idx = 0
    t_idx = 0

    while p_idx < len(pattern):
        if pattern[p_idx] == '\\':
            # Escaped character
            p_idx += 1
            if p_idx >= len(pattern):
                return False
            if t_idx >= len(text) or text[t_idx] != pattern[p_idx]:
                return False
            p_idx += 1
            t_idx += 1
        elif pattern[p_idx] == '?':
            # Match exactly one character
            if t_idx >= len(text):
                return False
            p_idx += 1
            t_idx += 1
        elif pattern[p_idx] == '*':
            # Match zero or more characters
            # Use greedy matching with backtracking
            p_idx += 1
            # Find the extent of * (could be part of a longer pattern)
            return _match_star(pattern, p_idx, text, t_idx)
        elif pattern[p_idx] == '[':
            # Character class
            p_idx, matched = _match_bracket(pattern, p_idx, text, t_idx)
            if not matched:
                return False
            t_idx += 1
        else:
            # Literal character
            if t_idx >= len(text) or text[t_idx] != pattern[p_idx]:
                return False
            p_idx += 1
            t_idx += 1

    return t_idx == len(text)


def _match_star(pattern: str, p_idx: int, text: str, t_idx: int) -> bool:
    """Match * in pattern against remaining text."""
    # Try matching from longest to shortest
    for end_pos in range(len(text), t_idx - 1, -1):
        if _match_segment(pattern[p_idx:], text[end_pos:]):
            return True
    return False


def _match_bracket(pattern: str, p_idx: int, text: str, t_idx: int) -> tuple:
    """Match [...] bracket expression. Returns (new_p_idx, matched)."""
    if t_idx >= len(text):
        return (p_idx, False)

    p_idx += 1  # Skip '['
    negate = False

    if p_idx < len(pattern) and pattern[p_idx] == '!':
        negate = True
        p_idx += 1

    # Handle ] as literal if right after [ or [!
    matched = False
    if p_idx < len(pattern) and pattern[p_idx] == ']':
        matched = (text[t_idx] == ']')
        p_idx += 1

    # Collect characters/ranges
    while p_idx < len(pattern) and pattern[p_idx] != ']':
        if pattern[p_idx] == '-' and p_idx + 1 < len(pattern) and pattern[p_idx + 1] != ']':
            # This might be a range, but only if not at start/end
            # Back up to get the start character
            if p_idx > (2 if negate else 1):  # Not at start of character set
                start_char = pattern[p_idx - 1]
                p_idx += 1
                end_char = pattern[p_idx]
                if start_char <= text[t_idx] <= end_char:
                    matched = True
                p_idx += 1
            else:
                # Literal dash
                if text[t_idx] == '-':
                    matched = True
                p_idx += 1
        else:
            if text[t_idx] == pattern[p_idx]:
                matched = True
            p_idx += 1

    if negate:
        matched = not matched

    # Skip to the closing ]
    if p_idx < len(pattern) and pattern[p_idx] == ']':
        p_idx += 1
    # else: no closing ], [ is literal - but we already processed it

    return (p_idx, matched)

import re

def glob_match(pattern: str, path: str) -> bool:
    """
    Reports whether a slash-separated path matches a glob pattern.
    The pattern must match the whole path. Matching is case-sensitive.
    """
    # Validate pattern - check for unpaired backslash at end
    if pattern.endswith('\\'):
        num_backslashes = 0
        for i in range(len(pattern) - 1, -1, -1):
            if pattern[i] == '\\':
                num_backslashes += 1
            else:
                break
        if num_backslashes % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    # Convert glob pattern to regex
    regex_pattern = _glob_to_regex(pattern)

    try:
        return bool(re.fullmatch(regex_pattern, path))
    except re.error:
        return False


def _glob_to_regex(pattern: str) -> str:
    """Convert a glob pattern to a regex pattern."""
    regex = []
    i = 0

    while i < len(pattern):
        char = pattern[i]

        if char == '\\':
            # Escape next character
            if i + 1 < len(pattern):
                next_char = pattern[i + 1]
                regex.append(re.escape(next_char))
                i += 2
            else:
                raise ValueError("Pattern ends with unpaired backslash")

        elif char == '*':
            # Check if it's ** (special case)
            if i + 1 < len(pattern) and pattern[i + 1] == '*':
                # Check if this ** is a special whole-segment match
                before_ok = (i == 0) or (pattern[i - 1] == '/')
                after_ok = (i + 2 == len(pattern)) or (pattern[i + 2] == '/')

                if before_ok and after_ok:
                    # This is a special ** segment
                    if i == 0 and i + 2 == len(pattern):
                        # ** is the whole pattern
                        regex.append('.*')
                        i += 2
                    elif i == 0 and pattern[i + 2] == '/':
                        # **/ at start - matches zero or more segments
                        regex.append('(?:.*/)?')
                        i += 3  # Skip '**/'
                    elif pattern[i - 1] == '/' and i + 2 == len(pattern):
                        # /** at end - matches zero or more segments
                        regex.append('(?:/.*)?' )
                        i += 2
                    elif pattern[i - 1] == '/' and pattern[i + 2] == '/':
                        # /**/ in middle - match zero or more segments
                        regex.append('(?:/[^/]+)*')
                        i += 3  # Skip '**/'
                    else:
                        regex.append('[^/]*')
                        i += 1
                else:
                    # Not special, treat as single *
                    regex.append('[^/]*')
                    i += 1
            else:
                # Single * matches any sequence except /
                regex.append('[^/]*')
                i += 1

        elif char == '?':
            # Matches exactly one character other than /
            regex.append('[^/]')
            i += 1

        elif char == '[':
            # Character class
            closing = _find_closing_bracket(pattern, i)
            if closing == -1:
                # No closing bracket, treat [ as literal
                regex.append(r'\[')
                i += 1
            else:
                # Extract the character class content
                class_content = pattern[i + 1:closing]
                regex_class = _parse_character_class(class_content)
                regex.append(regex_class)
                i = closing + 1

        elif char in '.+(){}^$|':
            # Regex special characters - escape them
            regex.append('\\' + char)
            i += 1

        else:
            # Regular character
            regex.append(re.escape(char))
            i += 1

    return ''.join(regex)


def _find_closing_bracket(pattern: str, start: int) -> int:
    """Find the closing bracket for a character class, or -1 if not found."""
    i = start + 1

    # Special case: ] right after [ or [!
    if i < len(pattern) and pattern[i] == ']':
        i += 1
    elif i < len(pattern) and pattern[i] == '!' and i + 1 < len(pattern) and pattern[i + 1] == ']':
        i += 2

    while i < len(pattern):
        if pattern[i] == ']':
            return i
        i += 1

    return -1


def _parse_character_class(content: str) -> str:
    """Parse a character class content and return regex pattern."""
    if not content:
        return r'[^/]'

    negated = False
    start = 0

    if content[0] == '!':
        negated = True
        start = 1

    # Build character ranges and literals
    parts = []
    i = start

    while i < len(content):
        if i + 2 < len(content) and content[i + 1] == '-' and content[i] != '-' and content[i + 2] != '-':
            # This looks like a range a-z
            parts.append(f'{re.escape(content[i])}-{re.escape(content[i + 2])}')
            i += 3
        elif content[i] == '-' and (i == start or i == len(content) - 1):
            # Leading or trailing dash is literal
            parts.append('-')
            i += 1
        else:
            parts.append(re.escape(content[i]))
            i += 1

    class_content = ''.join(parts)

    if negated:
        return f'[^/{class_content}]'
    else:
        return f'[{class_content}]'

def glob_match(pattern: str, path: str) -> bool:
    """
    Reports whether a slash-separated path matches a glob pattern.
    The pattern must match the whole path.
    """

    def parse_pattern(pattern: str) -> list:
        """Parse pattern into tokens, handling escapes and special sequences."""
        tokens = []
        i = 0
        while i < len(pattern):
            if pattern[i] == '\\':
                if i + 1 >= len(pattern):
                    raise ValueError("Pattern ends with unpaired backslash")
                tokens.append(('literal', pattern[i + 1]))
                i += 2
            elif pattern[i] == '*':
                if i + 1 < len(pattern) and pattern[i + 1] == '*':
                    tokens.append(('doublestar', '**'))
                    i += 2
                else:
                    tokens.append(('star', '*'))
                    i += 1
            elif pattern[i] == '?':
                tokens.append(('question', '?'))
                i += 1
            elif pattern[i] == '[':
                # Parse character class
                j = i + 1
                if j < len(pattern) and pattern[j] == '!':
                    j += 1
                if j < len(pattern) and pattern[j] == ']':
                    j += 1
                while j < len(pattern) and pattern[j] != ']':
                    j += 1
                if j >= len(pattern):
                    # No closing bracket, treat [ as literal
                    tokens.append(('literal', '['))
                    i += 1
                else:
                    tokens.append(('bracket', pattern[i:j+1]))
                    i = j + 1
            else:
                tokens.append(('literal', pattern[i]))
                i += 1
        return tokens

    def match_bracket(bracket_expr: str, char: str) -> bool:
        """Check if char matches a bracket expression like [abc] or [!abc] or [a-z]."""
        content = bracket_expr[1:-1]  # Remove [ and ]
        negate = False
        if content.startswith('!'):
            negate = True
            content = content[1:]

        # Parse ranges and literals
        matched = False
        i = 0
        while i < len(content):
            if i + 2 < len(content) and content[i + 1] == '-':
                # Range like a-z
                start_char = content[i]
                end_char = content[i + 2]
                if start_char <= char <= end_char:
                    matched = True
                    break
                i += 3
            else:
                # Single character
                if content[i] == char:
                    matched = True
                    break
                i += 1

        if negate:
            matched = not matched
        return matched

    def is_doublestar_segment(tokens: list, start: int) -> bool:
        """Check if token at start is a whole-segment ** (not part of other tokens)."""
        if start >= len(tokens) or tokens[start][0] != 'doublestar':
            return False

        # Check if it's a whole segment (not combined with other tokens in same segment)
        # ** is whole segment if it's alone or separated by /
        is_alone = True

        # Check before
        if start > 0 and tokens[start - 1][0] != 'slash':
            is_alone = False

        # Check after
        if start + 1 < len(tokens) and tokens[start + 1][0] != 'slash':
            is_alone = False

        return is_alone

    # Add slashes as tokens for easier segment parsing
    def tokenize_with_slashes(pattern: str) -> list:
        tokens = parse_pattern(pattern)
        result = []
        for token in tokens:
            if token[0] == 'literal' and token[1] == '/':
                result.append(('slash', '/'))
            else:
                result.append(token)
        return result

    tokens = tokenize_with_slashes(pattern)

    # Convert to segments
    segments = []
    current_segment = []
    for token in tokens:
        if token[0] == 'slash':
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            current_segment.append(token)
    if current_segment:
        segments.append(current_segment)

    path_segments = path.split('/')

    def match_segments(seg_idx: int, path_idx: int) -> bool:
        """Recursively match pattern segments against path segments."""
        # Base cases
        if seg_idx >= len(segments):
            return path_idx >= len(path_segments)

        if path_idx > len(path_segments):
            return False

        current_seg = segments[seg_idx]

        # Check if this segment is a whole ** segment
        if len(current_seg) == 1 and current_seg[0][0] == 'doublestar':
            # ** matches zero or more path segments
            # Try matching rest of pattern at each possible position
            for next_path_idx in range(path_idx, len(path_segments) + 1):
                if match_segments(seg_idx + 1, next_path_idx):
                    return True
            return False

        # Regular segment matching
        if path_idx >= len(path_segments):
            return False

        path_segment = path_segments[path_idx]

        # Match current segment against current path segment
        if match_segment_string(current_seg, path_segment):
            return match_segments(seg_idx + 1, path_idx + 1)

        return False

    def match_segment_string(seg_tokens: list, s: str) -> bool:
        """Match a single path segment against tokens."""
        return match_tokens(seg_tokens, s, 0, 0)

    def match_tokens(tokens: list, s: str, t_idx: int, s_idx: int) -> bool:
        """Match tokens against string s."""
        if t_idx >= len(tokens):
            return s_idx >= len(s)

        if s_idx > len(s):
            return False

        token_type, token_val = tokens[t_idx]

        if token_type == 'literal':
            if s_idx < len(s) and s[s_idx] == token_val:
                return match_tokens(tokens, s, t_idx + 1, s_idx + 1)
            return False

        elif token_type == 'question':
            if s_idx < len(s):
                return match_tokens(tokens, s, t_idx + 1, s_idx + 1)
            return False

        elif token_type == 'star':
            # Try matching zero or more characters
            for next_s_idx in range(s_idx, len(s) + 1):
                if match_tokens(tokens, s, t_idx + 1, next_s_idx):
                    return True
            return False

        elif token_type == 'bracket':
            if s_idx < len(s) and match_bracket(token_val, s[s_idx]):
                return match_tokens(tokens, s, t_idx + 1, s_idx + 1)
            return False

        return False

    return match_segments(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with an unpaired backslash
    """

    # Validate pattern - no ending backslash
    if pattern.endswith('\\') and not pattern.endswith('\\\\'):
        # Check if it's actually unpaired
        num_backslashes = 0
        for i in range(len(pattern) - 1, -1, -1):
            if pattern[i] == '\\':
                num_backslashes += 1
            else:
                break
        if num_backslashes % 2 == 1:
            raise ValueError("Pattern ends with unpaired backslash")

    def parse_pattern(p: str):
        """Parse pattern into tokens"""
        tokens = []
        i = 0
        while i < len(p):
            if p[i] == '\\' and i + 1 < len(p):
                # Escaped character
                tokens.append(('literal', p[i + 1]))
                i += 2
            elif p[i] == '*':
                if i + 1 < len(p) and p[i + 1] == '*':
                    tokens.append(('doublestar', '**'))
                    i += 2
                else:
                    tokens.append(('star', '*'))
                    i += 1
            elif p[i] == '?':
                tokens.append(('question', '?'))
                i += 1
            elif p[i] == '[':
                # Character class
                j = i + 1
                negate = False
                if j < len(p) and p[j] == '!':
                    negate = True
                    j += 1
                # Find closing bracket
                if j < len(p) and p[j] == ']':
                    j += 1
                while j < len(p) and p[j] != ']':
                    j += 1
                if j < len(p):
                    # Found closing bracket
                    char_class = p[i+1:j]
                    if char_class.startswith('!'):
                        char_class = char_class[1:]
                        negate = True
                    tokens.append(('charclass', (char_class, negate)))
                    i = j + 1
                else:
                    # No closing bracket, treat [ as literal
                    tokens.append(('literal', '['))
                    i += 1
            else:
                tokens.append(('literal', p[i]))
                i += 1
        return tokens

    def char_in_class(ch: str, char_class: str, negate: bool) -> bool:
        """Check if character matches character class"""
        i = 0
        matched = False
        while i < len(char_class):
            if i + 2 < len(char_class) and char_class[i + 1] == '-':
                # Range
                start = char_class[i]
                end = char_class[i + 2]
                if start <= ch <= end:
                    matched = True
                    break
                i += 3
            else:
                if char_class[i] == ch:
                    matched = True
                    break
                i += 1
        return matched != negate

    def match_tokens(tokens, segments, seg_idx, tok_idx):
        """Recursively match tokens against path segments"""
        if tok_idx == len(tokens) and seg_idx == len(segments):
            return True

        if tok_idx == len(tokens):
            return False

        token_type, token_val = tokens[tok_idx]

        if token_type == 'doublestar':
            # ** matches zero or more segments
            # Try matching zero segments
            if match_tokens(tokens, segments, seg_idx, tok_idx + 1):
                return True
            # Try matching one or more segments
            if seg_idx < len(segments):
                return match_tokens(tokens, segments, seg_idx + 1, tok_idx)
            return False

        if seg_idx == len(segments):
            return False

        # Need to match current segment with patterns up to next /
        segment = segments[seg_idx]

        # Collect tokens for this segment (until doublestar or end)
        seg_tokens = []
        i = tok_idx
        while i < len(tokens) and tokens[i][0] != 'doublestar':
            seg_tokens.append(tokens[i])
            i += 1

        if match_segment(seg_tokens, segment):
            return match_tokens(tokens, segments, seg_idx + 1, i)

        return False

    def match_segment(seg_tokens, segment: str) -> bool:
        """Match a single path segment against segment tokens"""
        return match_segment_helper(seg_tokens, segment, 0, 0)

    def match_segment_helper(tokens, text: str, tok_idx: int, text_idx: int) -> bool:
        """Helper for matching segment"""
        if tok_idx == len(tokens):
            return text_idx == len(text)

        token_type, token_val = tokens[tok_idx]

        if token_type == 'literal':
            if text_idx < len(text) and text[text_idx] == token_val:
                return match_segment_helper(tokens, text, tok_idx + 1, text_idx + 1)
            return False

        elif token_type == 'question':
            if text_idx < len(text):
                return match_segment_helper(tokens, text, tok_idx + 1, text_idx + 1)
            return False

        elif token_type == 'star':
            # * matches any sequence (greedy)
            for i in range(text_idx, len(text) + 1):
                if match_segment_helper(tokens, text, tok_idx + 1, i):
                    return True
            return False

        elif token_type == 'charclass':
            char_class, negate = token_val
            if text_idx < len(text) and char_in_class(text[text_idx], char_class, negate):
                return match_segment_helper(tokens, text, tok_idx + 1, text_idx + 1)
            return False

        return False

    # Parse pattern into segments
    pattern_segments = pattern.split('/')
    path_segments = path.split('/')

    # Parse tokens for each segment
    parsed_segments = [parse_pattern(seg) for seg in pattern_segments]

    # Match
    def match_recursive(pat_seg_idx: int, path_seg_idx: int) -> bool:
        if pat_seg_idx == len(parsed_segments) and path_seg_idx == len(path_segments):
            return True

        if pat_seg_idx == len(parsed_segments):
            return False

        if path_seg_idx == len(path_segments):
            # Check if remaining pattern segments are all empty or **
            for i in range(pat_seg_idx, len(parsed_segments)):
                if not (len(parsed_segments[i]) == 1 and parsed_segments[i][0][0] == 'doublestar'):
                    return False
            return True

        pat_tokens = parsed_segments[pat_seg_idx]

        # Check if this is a ** pattern
        if len(pat_tokens) == 1 and pat_tokens[0][0] == 'doublestar':
            # ** matches zero or more segments
            # Try matching zero segments
            if match_recursive(pat_seg_idx + 1, path_seg_idx):
                return True
            # Try matching one or more segments
            return match_recursive(pat_seg_idx, path_seg_idx + 1)

        # Normal segment matching
        if match_segment(pat_tokens, path_segments[path_seg_idx]):
            return match_recursive(pat_seg_idx + 1, path_seg_idx + 1)

        return False

    return match_recursive(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    """
    Check if a path matches a glob pattern.

    Args:
        pattern: A glob pattern string
        path: A slash-separated path string

    Returns:
        True if the path matches the pattern, False otherwise

    Raises:
        ValueError: If the pattern ends with an unpaired backslash
    """

    # Validate pattern - check for trailing unpaired backslash
    if pattern.endswith('\\') and (len(pattern) < 2 or pattern[-2] != '\\'):
        raise ValueError("Pattern ends with unpaired backslash")

    # Parse pattern into tokens
    tokens = _parse_pattern(pattern)

    # Split path into segments
    path_segments = path.split('/')

    # Match pattern tokens against path segments
    return _match_tokens(tokens, path_segments, 0, 0)


def _parse_pattern(pattern: str) -> list:
    """Parse pattern string into tokens."""
    tokens = []
    i = 0
    current_segment = []

    while i < len(pattern):
        if pattern[i] == '\\':
            # Escape next character
            if i + 1 < len(pattern):
                current_segment.append(('literal', pattern[i + 1]))
                i += 2
            else:
                raise ValueError("Pattern ends with unpaired backslash")
        elif pattern[i] == '/':
            # End of segment
            if current_segment:
                tokens.append(('segment', current_segment))
            current_segment = []
            i += 1
        else:
            current_segment.append(('char', pattern[i]))
            i += 1

    # Add final segment
    if current_segment:
        tokens.append(('segment', current_segment))

    # Convert segments to pattern objects
    result = []
    for seg_type, seg_content in tokens:
        pattern_obj = _parse_segment(seg_content)
        result.append(pattern_obj)

    return result


def _parse_segment(segment: list) -> dict:
    """Parse a single path segment into a pattern object."""
    # Check if this is a ** segment
    if len(segment) == 1 and segment[0] == ('char', '*'):
        # Just one *, check if it should be **
        return {'type': 'wildcard'}

    if len(segment) == 2 and segment[0] == ('char', '*') and segment[1] == ('char', '*'):
        return {'type': 'doublestar'}

    # Parse segment into pattern parts
    parts = []
    i = 0
    while i < len(segment):
        seg_type, char = segment[i]

        if seg_type == 'literal':
            parts.append(('literal', char))
        elif char == '*':
            parts.append(('star',))
        elif char == '?':
            parts.append(('question',))
        elif char == '[':
            # Parse character class
            j = i + 1
            negate = False
            if j < len(segment) and segment[j] == ('char', '!'):
                negate = True
                j += 1

            # Find closing bracket
            char_set = []
            while j < len(segment):
                s_type, s_char = segment[j]
                if s_type == 'literal':
                    char_set.append(s_char)
                    j += 1
                elif s_char == ']':
                    if not char_set and not negate:
                        # First char is ], it's literal
                        char_set.append(']')
                        j += 1
                    else:
                        # End of character class
                        break
                elif s_char == '-':
                    # Could be range or literal dash
                    if not char_set or j + 1 >= len(segment):
                        # Literal dash
                        char_set.append('-')
                        j += 1
                    else:
                        # Check if next is ]
                        if j + 1 < len(segment) and segment[j + 1] == ('char', ']'):
                            # Literal dash at end
                            char_set.append('-')
                            j += 1
                        else:
                            # This is a range
                            j += 1
                            if j < len(segment):
                                _, end_char = segment[j]
                                start_char = char_set.pop() if char_set else '-'
                                for c in range(ord(start_char), ord(end_char) + 1):
                                    char_set.append(chr(c))
                                j += 1
                else:
                    char_set.append(s_char)
                    j += 1

            if j < len(segment) and segment[j] == ('char', ']'):
                parts.append(('bracket', char_set, negate))
                i = j + 1
            else:
                # No closing bracket, treat [ as literal
                parts.append(('literal', '['))
                i += 1
        else:
            parts.append(('literal', char))

        i += 1

    return {'type': 'pattern', 'parts': parts}


def _match_tokens(tokens: list, path_segments: list, token_idx: int, segment_idx: int) -> bool:
    """Recursively match pattern tokens against path segments."""

    # Base case: both exhausted
    if token_idx == len(tokens) and segment_idx == len(path_segments):
        return True

    # Pattern exhausted but path remains
    if token_idx == len(tokens):
        return False

    # Path exhausted but pattern remains
    if segment_idx == len(path_segments):
        # Remaining tokens must all be doublestar
        for i in range(token_idx, len(tokens)):
            if tokens[i]['type'] != 'doublestar':
                return False
        return True

    token = tokens[token_idx]

    if token['type'] == 'doublestar':
        # ** matches zero or more segments
        # Try matching zero segments
        if _match_tokens(tokens, path_segments, token_idx + 1, segment_idx):
            return True
        # Try matching one or more segments
        if _match_tokens(tokens, path_segments, token_idx, segment_idx + 1):
            return True
        return False

    # Try to match current segment
    if _match_segment(token, path_segments[segment_idx]):
        return _match_tokens(tokens, path_segments, token_idx + 1, segment_idx + 1)

    return False


def _match_segment(pattern_obj: dict, segment: str) -> bool:
    """Match a pattern object against a path segment."""
    if pattern_obj['type'] == 'wildcard':
        # * matches any sequence except /
        return True

    if pattern_obj['type'] == 'doublestar':
        # Should not happen in _match_segment
        return False

    parts = pattern_obj['parts']

    # Match segment against pattern parts
    return _match_pattern_parts(parts, segment, 0, 0)


def _match_pattern_parts(parts: list, text: str, part_idx: int, text_idx: int) -> bool:
    """Recursively match pattern parts against text."""

    # Both exhausted
    if part_idx == len(parts) and text_idx == len(text):
        return True

    # Pattern exhausted but text remains
    if part_idx == len(parts):
        return False

    part = parts[part_idx]

    if part[0] == 'literal':
        # Must match exactly one character
        if text_idx >= len(text) or text[text_idx] != part[1]:
            return False
        return _match_pattern_parts(parts, text, part_idx + 1, text_idx + 1)

    elif part[0] == 'question':
        # Match exactly one character
        if text_idx >= len(text):
            return False
        return _match_pattern_parts(parts, text, part_idx + 1, text_idx + 1)

    elif part[0] == 'star':
        # Match zero or more characters
        # Try matching zero characters
        if _match_pattern_parts(parts, text, part_idx + 1, text_idx):
            return True
        # Try matching one or more characters
        if text_idx < len(text):
            return _match_pattern_parts(parts, text, part_idx, text_idx + 1)
        return False

    elif part[0] == 'bracket':
        # Match one character from set
        if text_idx >= len(text):
            return False
        char = text[text_idx]
        char_set = part[1]
        negate = part[2]

        in_set = char in char_set
        if negate:
            in_set = not in_set

        if not in_set:
            return False

        return _match_pattern_parts(parts, text, part_idx + 1, text_idx + 1)

    return False

def glob_match(pattern: str, path: str) -> bool:
    """
    Reports whether a slash-separated path matches a glob pattern.
    The pattern must match the whole path. Matching is case-sensitive.
    """

    def char_in_set(ch: str, char_set: str) -> bool:
        """Check if character is in character set, handling ranges."""
        i = 0
        while i < len(char_set):
            if char_set[i] == '\\' and i + 1 < len(char_set):
                if char_set[i + 1] == ch:
                    return True
                i += 2
            elif i + 2 < len(char_set) and char_set[i + 1] == '-':
                # Check if this is a range (not when - is first or last)
                if char_set[i] != '-' and char_set[i + 2] != '-':
                    if ord(char_set[i]) <= ord(ch) <= ord(char_set[i + 2]):
                        return True
                    i += 3
                else:
                    if char_set[i] == ch:
                        return True
                    i += 1
            else:
                if char_set[i] == ch:
                    return True
                i += 1
        return False

    def match_recursive(pat_idx: int, path_idx: int) -> bool:
        """Recursively match pattern against path."""
        pat_len = len(pattern)
        path_len = len(path)

        while pat_idx < pat_len and path_idx < path_len:
            # Handle backslash escaping
            if pattern[pat_idx] == '\\':
                if pat_idx + 1 >= pat_len:
                    raise ValueError("Pattern ends with unpaired backslash")
                if path[path_idx] != pattern[pat_idx + 1]:
                    return False
                pat_idx += 2
                path_idx += 1
            # Handle ** (glob star - whole segment only)
            elif pat_idx + 1 < pat_len and pattern[pat_idx:pat_idx+2] == '**':
                before_ok = (pat_idx == 0 or pattern[pat_idx - 1] == '/')
                after_ok = (pat_idx + 2 >= pat_len or pattern[pat_idx + 2] == '/')

                if before_ok and after_ok:
                    # ** is a whole segment - matches zero or more path segments
                    pat_idx += 2
                    if pat_idx < pat_len and pattern[pat_idx] == '/':
                        pat_idx += 1

                    # Try matching zero segments (skip to next pattern part)
                    if match_recursive(pat_idx, path_idx):
                        return True

                    # Try matching one or more segments
                    while path_idx < path_len:
                        if path[path_idx] == '/':
                            path_idx += 1
                            if match_recursive(pat_idx, path_idx):
                                return True
                        else:
                            path_idx += 1
                    return False
                else:
                    # ** not a whole segment, treat as *
                    pat_idx += 1
                    while path_idx < path_len and path[path_idx] != '/':
                        if match_recursive(pat_idx, path_idx):
                            return True
                        path_idx += 1
                    return match_recursive(pat_idx, path_idx)
            # Handle single * (matches chars except /)
            elif pattern[pat_idx] == '*':
                pat_idx += 1
                while path_idx < path_len and path[path_idx] != '/':
                    if match_recursive(pat_idx, path_idx):
                        return True
                    path_idx += 1
                return match_recursive(pat_idx, path_idx)
            # Handle ? (matches exactly one char except /)
            elif pattern[pat_idx] == '?':
                if path[path_idx] == '/':
                    return False
                pat_idx += 1
                path_idx += 1
            # Handle character class [...]
            elif pattern[pat_idx] == '[':
                j = pat_idx + 1
                negate = False

                if j < pat_len and pattern[j] == '!':
                    negate = True
                    j += 1

                # Handle ] right after [ or [!
                if j < pat_len and pattern[j] == ']':
                    j += 1

                # Find closing bracket
                while j < pat_len and pattern[j] != ']':
                    j += 1

                if j >= pat_len:
                    # No closing bracket, treat [ as literal
                    if pattern[pat_idx] != path[path_idx]:
                        return False
                    pat_idx += 1
                    path_idx += 1
                else:
                    # Found closing bracket
                    char_set = pattern[pat_idx+1:j]
                    if char_set.startswith('!'):
                        char_set = char_set[1:]
                        negate = True

                    if path[path_idx] == '/':
                        return False

                    matched = char_in_set(path[path_idx], char_set)
                    if negate:
                        matched = not matched

                    if not matched:
                        return False

                    pat_idx = j + 1
                    path_idx += 1
            # Handle regular characters
            else:
                if pattern[pat_idx] != path[path_idx]:
                    return False
                pat_idx += 1
                path_idx += 1

        # Both pattern and path must be fully consumed
        return pat_idx == pat_len and path_idx == path_len

    return match_recursive(0, 0)

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Times are in the form YYYY-MM-DDTHH:MM with no seconds and no timezone.
    Cron expression has 5 fields: minute, hour, day of month, month, day of week.
    """

    # Parse the input time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Cron expression must have 5 fields, got {len(fields)}")

    minute_field, hour_field, day_field, month_field, dow_field = fields

    # Parse each field
    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    days = parse_field(day_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    dows = parse_field(dow_field, 0, 7)

    # Normalize day of week (0 and 7 both mean Sunday)
    dows = {0 if d == 7 else d for d in dows}

    # Check if we need special day matching logic
    day_field_starts_with_star = day_field.startswith('*')
    dow_field_starts_with_star = dow_field.startswith('*')

    # Start from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Search for up to 8 years
    end_time = after_dt + timedelta(days=365*8)

    while current <= end_time:
        minute = current.minute
        hour = current.hour
        day = current.day
        month = current.month
        dow = current.weekday()
        dow = (dow + 1) % 7  # Convert Python's Monday=0 to cron's Sunday=0

        # Check minute and hour
        if minute not in minutes or hour not in hours or month not in months:
            current += timedelta(minutes=1)
            continue

        # Day matching logic
        day_matches = day in days
        dow_matches = dow in dows

        if not day_field_starts_with_star and not dow_field_starts_with_star:
            # Both day and dow are restricted (don't start with *)
            # Match if either matches
            if not (day_matches or dow_matches):
                current += timedelta(minutes=1)
                continue
        else:
            # At least one starts with *, so both must match their restrictions
            if not day_matches or not dow_matches:
                current += timedelta(minutes=1)
                continue

        # Found a match
        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError(f"No matching time found within 8 years after {after}")


def parse_field(field: str, min_val: int, max_val: int) -> set:
    """
    Parse a single cron field and return the set of matching values.
    """
    values = set()

    items = field.split(',')
    for item in items:
        if '/' in item:
            # Handle step values
            if item.startswith('*/'):
                # */S format
                try:
                    step = int(item[2:])
                except ValueError:
                    raise ValueError(f"Invalid step in field: {item}")

                if step <= 0:
                    raise ValueError(f"Step must be >= 1, got {step}")

                for v in range(min_val, max_val + 1, step):
                    values.add(v)
            else:
                # A-B/S format
                try:
                    range_part, step_str = item.rsplit('/', 1)
                    step = int(step_str)
                except (ValueError, IndexError):
                    raise ValueError(f"Invalid step in field: {item}")

                if step <= 0:
                    raise ValueError(f"Step must be >= 1, got {step}")

                if '-' not in range_part:
                    raise ValueError(f"Invalid range in field: {item}")

                try:
                    start, end = range_part.split('-')
                    start = int(start)
                    end = int(end)
                except ValueError:
                    raise ValueError(f"Invalid range in field: {item}")

                if start > end:
                    raise ValueError(f"Invalid range: {start} > {end}")
                if start < min_val or end > max_val:
                    raise ValueError(f"Range {start}-{end} out of bounds [{min_val}, {max_val}]")

                for v in range(start, end + 1, step):
                    values.add(v)
        elif '-' in item:
            # Handle ranges
            try:
                start, end = item.split('-')
                start = int(start)
                end = int(end)
            except ValueError:
                raise ValueError(f"Invalid range in field: {item}")

            if start > end:
                raise ValueError(f"Invalid range: {start} > {end}")
            if start < min_val or end > max_val:
                raise ValueError(f"Range {start}-{end} out of bounds [{min_val}, {max_val}]")

            for v in range(start, end + 1):
                values.add(v)
        elif item == '*':
            # Match all values
            for v in range(min_val, max_val + 1):
                values.add(v)
        else:
            # Single value
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value in field: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of bounds [{min_val}, {max_val}]")

            values.add(val)

    return values

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Times are in format YYYY-MM-DDTHH:MM with no seconds or timezone.
    Cron expression has 5 fields: minute, hour, day-of-month, month, day-of-week.
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_expr, hour_expr, dom_expr, month_expr, dow_expr = fields

    # Parse each field
    minute_vals = parse_field(minute_expr, 0, 59)
    hour_vals = parse_field(hour_expr, 0, 23)
    dom_vals = parse_field(dom_expr, 1, 31)
    month_vals = parse_field(month_expr, 1, 12)
    dow_vals = parse_field(dow_expr, 0, 7)

    # Normalize day of week (both 0 and 7 mean Sunday)
    if 7 in dow_vals:
        dow_vals.remove(7)
        dow_vals.add(0)

    # Parse the after time
    after_dt = datetime.fromisoformat(after)

    # Start searching from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Search for up to 8 years
    max_iterations = 8 * 365 * 24 * 60 + 1000  # Add buffer for leap years
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        minute = current.minute
        hour = current.hour
        day = current.day
        month = current.month
        dow = current.weekday()
        if dow == 6:  # Convert Python's Sunday (6) to cron's Sunday (0)
            dow = 0
        else:
            dow += 1  # Python uses 0=Monday, cron uses 1=Monday

        # Check if this time matches
        if minute not in minute_vals or hour not in hour_vals or month not in month_vals:
            current += timedelta(minutes=1)
            continue

        # Handle day matching
        dom_unrestricted = dom_expr.startswith('*')
        dow_unrestricted = dow_expr.startswith('*')

        day_matches = False
        if dom_unrestricted and dow_unrestricted:
            # Both unrestricted: must match both
            day_matches = day in dom_vals and dow in dow_vals
        elif dom_unrestricted or dow_unrestricted:
            # One unrestricted: either matches
            day_matches = (day in dom_vals) or (dow in dow_vals)
        else:
            # Both restricted: either matches
            day_matches = (day in dom_vals) or (dow in dow_vals)

        if day_matches:
            return current.strftime('%Y-%m-%dT%H:%M')

        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 8 years")


def parse_field(field: str, min_val: int, max_val: int) -> set:
    """
    Parse a cron field and return the set of matching values.
    """
    values = set()

    # Handle comma-separated items
    items = field.split(',')

    for item in items:
        if item == '*':
            # Every value in range
            values.update(range(min_val, max_val + 1))
        elif '/' in item:
            # Step values
            if item.startswith('*/'):
                # */S format
                try:
                    step = int(item[2:])
                except ValueError:
                    raise ValueError(f"Invalid step in '{item}'")
                if step <= 0:
                    raise ValueError(f"Step must be >= 1, got {step}")
                values.update(range(min_val, max_val + 1, step))
            elif '-' in item:
                # A-B/S format
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError(f"Invalid range/step in '{item}'")
                range_part = parts[0]
                try:
                    step = int(parts[1])
                except ValueError:
                    raise ValueError(f"Invalid step in '{item}'")
                if step <= 0:
                    raise ValueError(f"Step must be >= 1, got {step}")

                range_vals = range_part.split('-')
                if len(range_vals) != 2:
                    raise ValueError(f"Invalid range in '{item}'")
                try:
                    start = int(range_vals[0])
                    end = int(range_vals[1])
                except ValueError:
                    raise ValueError(f"Invalid range in '{item}'")

                if start < min_val or end > max_val:
                    raise ValueError(f"Range {start}-{end} out of bounds [{min_val}, {max_val}]")
                if start > end:
                    raise ValueError(f"Invalid range {start}-{end}: start > end")

                values.update(range(start, end + 1, step))
            else:
                raise ValueError(f"Invalid step format in '{item}'")
        elif '-' in item:
            # Range A-B
            parts = item.split('-')
            if len(parts) != 2:
                raise ValueError(f"Invalid range in '{item}'")
            try:
                start = int(parts[0])
                end = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range in '{item}'")

            if start < min_val or end > max_val:
                raise ValueError(f"Range {start}-{end} out of bounds [{min_val}, {max_val}]")
            if start > end:
                raise ValueError(f"Invalid range {start}-{end}: start > end")

            values.update(range(start, end + 1))
        else:
            # Single value
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value '{item}'")

            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of bounds [{min_val}, {max_val}]")

            values.add(val)

    return values

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.
    Times are in format YYYY-MM-DDTHH:MM with no seconds and no timezone.
    """

    # Parse the input time
    try:
        after_dt = datetime.fromisoformat(after)
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Cron expression must have exactly 5 fields, got {len(fields)}")

    minute_spec, hour_spec, dom_spec, month_spec, dow_spec = fields

    # Parse each field
    try:
        minute_vals = parse_field(minute_spec, 0, 59)
        hour_vals = parse_field(hour_spec, 0, 23)
        dom_vals = parse_field(dom_spec, 1, 31)
        month_vals = parse_field(month_spec, 1, 12)
        dow_vals = parse_field(dow_spec, 0, 7)
    except ValueError as e:
        raise ValueError(f"Invalid cron field: {e}")

    # Normalize day of week (both 0 and 7 mean Sunday)
    dow_vals = {7 if v == 0 else v for v in dow_vals}

    # Check if both dom and dow are restricted (don't start with *)
    dom_restricted = not dom_spec.startswith("*")
    dow_restricted = not dow_spec.startswith("*")

    # Start checking from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Search for up to 8 years
    max_iterations = 8 * 365 * 24 * 60 + 1000  # Add buffer for leap years
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        # Check all fields
        if (current.minute in minute_vals and
            current.hour in hour_vals and
            current.month in month_vals):

            # Day matching logic
            day_matches = False

            if dom_restricted and dow_restricted:
                # Both restricted: match if either matches
                dom_match = current.day in dom_vals
                dow_match = current.weekday() in {d % 7 for d in dow_vals}
                day_matches = dom_match or dow_match
            else:
                # At least one is unrestricted: both must match
                dom_match = current.day in dom_vals
                dow_match = current.weekday() in {d % 7 for d in dow_vals}
                day_matches = dom_match and dow_match

            if day_matches:
                return current.isoformat(timespec='minutes')

        current += timedelta(minutes=1)

    raise ValueError(f"No matching time found within 8 years after {after}")


def parse_field(field: str, min_val: int, max_val: int) -> set:
    """
    Parse a single cron field and return a set of valid values.
    """
    values = set()

    for item in field.split(","):
        item = item.strip()

        if item == "*":
            # Every value in range
            values.update(range(min_val, max_val + 1))
        elif "/" in item:
            # Step values
            if item.startswith("*/"):
                # */S format
                try:
                    step = int(item[2:])
                except ValueError:
                    raise ValueError(f"Invalid step: {item}")

                if step < 1:
                    raise ValueError(f"Step must be >= 1, got {step}")

                values.update(range(min_val, max_val + 1, step))
            else:
                # A-B/S format
                if "-" not in item:
                    raise ValueError(f"Invalid range: {item}")

                parts = item.split("/")
                if len(parts) != 2:
                    raise ValueError(f"Invalid step format: {item}")

                range_part, step_part = parts
                try:
                    step = int(step_part)
                except ValueError:
                    raise ValueError(f"Invalid step: {step_part}")

                if step < 1:
                    raise ValueError(f"Step must be >= 1, got {step}")

                range_parts = range_part.split("-")
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid range: {range_part}")

                try:
                    start = int(range_parts[0])
                    end = int(range_parts[1])
                except ValueError:
                    raise ValueError(f"Invalid range: {range_part}")

                if start > end:
                    raise ValueError(f"Start {start} > end {end}")

                if start < min_val or end > max_val:
                    raise ValueError(f"Range {start}-{end} out of bounds [{min_val}-{max_val}]")

                values.update(range(start, end + 1, step))
        elif "-" in item:
            # Range A-B
            parts = item.split("-")
            if len(parts) != 2:
                raise ValueError(f"Invalid range: {item}")

            try:
                start = int(parts[0])
                end = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range: {item}")

            if start > end:
                raise ValueError(f"Start {start} > end {end}")

            if start < min_val or end > max_val:
                raise ValueError(f"Range {start}-{end} out of bounds [{min_val}-{max_val}]")

            values.update(range(start, end + 1))
        else:
            # Single value
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of bounds [{min_val}-{max_val}]")

            values.add(val)

    return values

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Find the first time strictly after `after` that matches the cron expression `expr`.

    Args:
        expr: Cron expression with 5 fields (minute, hour, day, month, day_of_week)
        after: Time string in format YYYY-MM-DDTHH:MM

    Returns:
        Time string in format YYYY-MM-DDTHH:MM matching the cron expression

    Raises:
        ValueError: If expression is malformed or no match found within 8 years
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_field, hour_field, day_field, month_field, dow_field = fields

    # Parse each field
    minutes = parse_field(minute_field, 0, 59, "minute")
    hours = parse_field(hour_field, 0, 23, "hour")
    days = parse_field(day_field, 1, 31, "day")
    months = parse_field(month_field, 1, 12, "month")
    dows = parse_field(dow_field, 0, 7, "day_of_week")

    # Normalize day of week (both 0 and 7 are Sunday)
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    # Parse the starting time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Start searching from the next minute
    current = after_dt + timedelta(minutes=1)

    # Search for up to 8 years
    max_iterations = 8 * 365 * 24 * 60 + 1000  # Add buffer for leap years
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        # Check if current time matches the cron expression
        if matches_cron(current, minutes, hours, days, months, dows, day_field, dow_field):
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 8 years")


def parse_field(field: str, min_val: int, max_val: int, field_name: str) -> set:
    """Parse a single cron field and return the set of matching values."""

    if field == "*":
        return set(range(min_val, max_val + 1))

    values = set()

    for item in field.split(","):
        item = item.strip()

        # Handle step values
        if "/" in item:
            range_part, step_part = item.split("/", 1)
            try:
                step = int(step_part)
            except ValueError:
                raise ValueError(f"Invalid step in {field_name}: {step_part}")

            if step <= 0:
                raise ValueError(f"Step must be positive in {field_name}")

            if range_part == "*":
                range_start, range_end = min_val, max_val
            elif "-" in range_part:
                try:
                    range_start, range_end = map(int, range_part.split("-", 1))
                except ValueError:
                    raise ValueError(f"Invalid range in {field_name}: {range_part}")
                if range_start > range_end:
                    raise ValueError(f"Invalid range in {field_name}: {range_start} > {range_end}")
            else:
                try:
                    range_start = int(range_part)
                    range_end = range_start
                except ValueError:
                    raise ValueError(f"Invalid value in {field_name}: {range_part}")

            if range_start < min_val or range_end > max_val:
                raise ValueError(f"Value out of range in {field_name}")

            for val in range(range_start, range_end + 1, step):
                values.add(val)

        # Handle ranges
        elif "-" in item:
            try:
                range_start, range_end = map(int, item.split("-", 1))
            except ValueError:
                raise ValueError(f"Invalid range in {field_name}: {item}")

            if range_start > range_end:
                raise ValueError(f"Invalid range in {field_name}: {range_start} > {range_end}")

            if range_start < min_val or range_end > max_val:
                raise ValueError(f"Value out of range in {field_name}")

            for val in range(range_start, range_end + 1):
                values.add(val)

        # Handle single values
        else:
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value in {field_name}: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value out of range in {field_name}: {val}")

            values.add(val)

    return values


def matches_cron(dt: datetime, minutes: set, hours: set, days: set, months: set, 
                 dows: set, day_field: str, dow_field: str) -> bool:
    """Check if a datetime matches the cron expression."""

    # Check minute, hour, month
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Day matching follows classic cron rules
    day_matches = dt.day in days
    dow_matches = dt.weekday() in dows or (dt.weekday() + 1) % 7 in dows

    # If both day and dow fields start with *, both must match
    day_field_all = day_field.startswith("*")
    dow_field_all = dow_field.startswith("*")

    if day_field_all and dow_field_all:
        # Both are unrestricted, both must match
        return day_matches and dow_matches
    elif day_field_all:
        # Day is unrestricted, only dow matters
        return dow_matches
    elif dow_field_all:
        # Dow is unrestricted, only day matters
        return day_matches
    else:
        # Neither starts with *, either can match
        return day_matches or dow_matches

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Args:
        expr: Cron expression with 5 fields (minute hour day month day_of_week)
        after: Time string in format "YYYY-MM-DDTHH:MM"

    Returns:
        Time string in format "YYYY-MM-DDTHH:MM" matching the cron expression

    Raises:
        ValueError: If the expression is malformed or no match found within 8 years
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_field, hour_field, day_field, month_field, dow_field = fields

    # Parse each field
    try:
        minutes = parse_field(minute_field, 0, 59)
        hours = parse_field(hour_field, 0, 23)
        days = parse_field(day_field, 1, 31)
        months = parse_field(month_field, 1, 12)
        dows = parse_field(dow_field, 0, 7)
    except ValueError as e:
        raise ValueError(f"Invalid cron expression: {e}")

    # Normalize day of week (both 0 and 7 mean Sunday)
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    # Parse the after time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Start searching from the next minute
    current = after_dt + timedelta(minutes=1)
    end = after_dt + timedelta(days=365*8)

    day_field_restricted = not day_field.startswith('*')
    dow_field_restricted = not dow_field.startswith('*')

    while current <= end:
        minute = current.minute
        hour = current.hour
        day = current.day
        month = current.month
        dow = current.weekday()
        # Convert Python's weekday (0=Monday) to cron's (0=Sunday, 1=Monday)
        dow = (dow + 1) % 7

        # Check if minute and hour match
        if minute not in minutes or hour not in hours:
            current += timedelta(minutes=1)
            continue

        # Check if month matches
        if month not in months:
            current += timedelta(minutes=1)
            continue

        # Check day matching logic
        day_matches = day in days
        dow_matches = dow in dows

        if day_field_restricted and dow_field_restricted:
            # Both restricted: match if either matches
            if not (day_matches or dow_matches):
                current += timedelta(minutes=1)
                continue
        else:
            # At least one starts with *: match if both match
            if not (day_matches and dow_matches):
                current += timedelta(minutes=1)
                continue

        # Found a match
        return current.strftime("%Y-%m-%dT%H:%M")

    raise ValueError(f"No matching time found within 8 years after {after}")


def parse_field(field: str, min_val: int, max_val: int) -> set:
    """
    Parse a single cron field and return the set of matching values.

    Args:
        field: A single cron field (e.g., "*/15", "1-5", "1,3,5")
        min_val: Minimum valid value for this field
        max_val: Maximum valid value for this field

    Returns:
        Set of integers matching this field
    """
    if not field:
        raise ValueError("Empty field")

    values = set()

    # Handle comma-separated items
    items = field.split(',')

    for item in items:
        if '/' in item:
            # Handle step values: */S or A-B/S
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError(f"Invalid step syntax: {item}")

            range_part = parts[0]
            try:
                step = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid step value: {parts[1]}")

            if step <= 0:
                raise ValueError(f"Step must be >= 1, got {step}")

            if range_part == '*':
                start, end = min_val, max_val
            elif '-' in range_part:
                try:
                    start, end = map(int, range_part.split('-'))
                except ValueError:
                    raise ValueError(f"Invalid range: {range_part}")
                if start < min_val or end > max_val or start > end:
                    raise ValueError(f"Range out of bounds or invalid: {range_part}")
            else:
                raise ValueError(f"Invalid range syntax: {range_part}")

            for v in range(start, end + 1, step):
                values.add(v)

        elif '-' in item:
            # Handle ranges: A-B
            try:
                start, end = map(int, item.split('-'))
            except ValueError:
                raise ValueError(f"Invalid range: {item}")

            if start < min_val or end > max_val or start > end:
                raise ValueError(f"Range out of bounds or invalid: {item}")

            for v in range(start, end + 1):
                values.add(v)

        elif item == '*':
            # Match all values
            for v in range(min_val, max_val + 1):
                values.add(v)

        else:
            # Single value
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of range [{min_val}, {max_val}]")

            values.add(val)

    if not values:
        raise ValueError(f"Field {field} matches no values")

    return values

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Times are in format YYYY-MM-DDTHH:MM with no seconds or timezone.
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_spec, hour_spec, day_spec, month_spec, dow_spec = fields

    # Parse each field
    minute_vals = parse_field(minute_spec, 0, 59, "minute")
    hour_vals = parse_field(hour_spec, 0, 23, "hour")
    day_vals = parse_field(day_spec, 1, 31, "day")
    month_vals = parse_field(month_spec, 1, 12, "month")
    dow_vals = parse_field(dow_spec, 0, 7, "day of week")

    # Normalize Sunday in dow_vals (both 0 and 7 mean Sunday)
    if 7 in dow_vals:
        dow_vals = (dow_vals - {7}) | {0}

    # Parse the after time
    try:
        after_dt = datetime.fromisoformat(after)
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Start checking from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Search for up to 8 years
    end_time = after_dt + timedelta(days=365*8)

    while current <= end_time:
        if matches_cron(current, minute_vals, hour_vals, day_vals, month_vals, dow_vals, day_spec, dow_spec):
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 8 years")


def parse_field(field: str, min_val: int, max_val: int, field_name: str) -> set:
    """Parse a single cron field and return the set of matching values."""

    values = set()

    for item in field.split(","):
        item = item.strip()

        if item == "*":
            # All values
            values.update(range(min_val, max_val + 1))
        elif "/" in item:
            # Handle step values
            if item.startswith("*/"):
                # */S format
                try:
                    step = int(item[2:])
                except ValueError:
                    raise ValueError(f"Invalid step in {field_name}: {item}")

                if step <= 0:
                    raise ValueError(f"Step must be >= 1 in {field_name}: {item}")

                values.update(range(min_val, max_val + 1, step))
            else:
                # A-B/S format
                parts = item.split("/")
                if len(parts) != 2:
                    raise ValueError(f"Invalid range with step in {field_name}: {item}")

                try:
                    step = int(parts[1])
                except ValueError:
                    raise ValueError(f"Invalid step in {field_name}: {item}")

                if step <= 0:
                    raise ValueError(f"Step must be >= 1 in {field_name}: {item}")

                # Parse the range part
                range_part = parts[0]
                if "-" in range_part:
                    range_parts = range_part.split("-")
                    if len(range_parts) != 2:
                        raise ValueError(f"Invalid range in {field_name}: {item}")
                    try:
                        a, b = int(range_parts[0]), int(range_parts[1])
                    except ValueError:
                        raise ValueError(f"Invalid range in {field_name}: {item}")
                else:
                    raise ValueError(f"Invalid range with step in {field_name}: {item}")

                if a > b:
                    raise ValueError(f"Invalid range A > B in {field_name}: {item}")
                if a < min_val or b > max_val:
                    raise ValueError(f"Value out of range in {field_name}: {item}")

                values.update(range(a, b + 1, step))
        elif "-" in item:
            # Range A-B
            parts = item.split("-")
            if len(parts) != 2:
                raise ValueError(f"Invalid range in {field_name}: {item}")

            try:
                a, b = int(parts[0]), int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range in {field_name}: {item}")

            if a > b:
                raise ValueError(f"Invalid range A > B in {field_name}: {item}")
            if a < min_val or b > max_val:
                raise ValueError(f"Value out of range in {field_name}: {item}")

            values.update(range(a, b + 1))
        else:
            # Single value
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value in {field_name}: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value out of range in {field_name}: {item}")

            values.add(val)

    return values


def matches_cron(dt: datetime, minute_vals: set, hour_vals: set, day_vals: set, 
                 month_vals: set, dow_vals: set, day_spec: str, dow_spec: str) -> bool:
    """Check if a datetime matches the cron expression."""

    # Check minute and hour
    if dt.minute not in minute_vals or dt.hour not in hour_vals:
        return False

    # Check month
    if dt.month not in month_vals:
        return False

    # Day matching: if both day and dow fields don't start with *, then either can match
    # Otherwise both must match
    day_starts_with_star = day_spec.startswith("*")
    dow_starts_with_star = dow_spec.startswith("*")

    day_matches = dt.day in day_vals
    dow_matches = dt.weekday() == (dt.isoweekday() % 7) and (dt.isoweekday() % 7) in dow_vals

    # Get the actual day of week (0=Sunday, 1=Monday, ..., 6=Saturday)
    dow = (dt.weekday() + 1) % 7  # Convert from Python's Monday=0 to cron's Sunday=0
    dow_matches = dow in dow_vals

    # If both fields don't start with *, then it's OR logic
    if not day_starts_with_star and not dow_starts_with_star:
        return day_matches or dow_matches
    else:
        # At least one starts with *, so use AND logic
        return day_matches and dow_matches

