    dows_normalized = set()
    for dow in dows:
        if dow == 7:
            dows_normalized.add(0)
        else:
            dows_normalized.add(dow)
    dows = dows_normalized

    # Parse the `after` timestamp
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid timestamp format: {after}")

    # Start checking from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Check up to 8 years in the future
    max_iterations = 8 * 365 * 24 * 60 + 1000  # Some buffer for leap years
    iterations = 0

    while iterations < max_iterations:
        # Check if current time matches the cron expression
        if matches_cron(current, minutes, hours, days, months, dows, day_field, dow_field):
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)
        iterations += 1

    raise ValueError("No matching time found within 8 years")

