            else:
                # Single value with step (unusual but valid)
                try:
                    start = int(range_part)
                except ValueError:
                    raise ValueError(f"Invalid value: {range_part}")

                if start < min_val or start > max_val:
                    raise ValueError(f"Value {start} out of bounds [{min_val}, {max_val}]")

                values.add(start)
        elif '-' in item:
            # Handle ranges: A-B
            parts = item.split('-')
            if len(parts) != 2:
                raise ValueError(f"Invalid range: {item}")
            try:
                start = int(parts[0])
                end = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range bounds: {item}")

            if start > end:
                raise ValueError(f"Invalid range: {start} > {end}")
            if start < min_val or end > max_val:
                raise ValueError(f"Range {start}-{end} out of bounds [{min_val}, {max_val}]")

            for v in range(start, end + 1):
                values.add(v)
        elif item == '*':
            # Handle wildcard
            for v in range(min_val, max_val + 1):
                values.add(v)
        else:
            # Handle single values
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value {val} out of bounds [{min_val}, {max_val}]")

            values.add(val)

    return values

def matches_cron(dt: datetime, minutes: set, hours: set, days: set, months: set, 
                 dows: set, day_field: str, dow_field: str) -> bool:
    """Check if a datetime matches the cron expression."""
    # Check minute, hour, month
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Handle day matching with special cron logic
    day_of_month = dt.day
    day_of_week = dt.weekday()
    day_of_week = (day_of_week + 1) % 7  # Convert Python's Monday=0 to cron's Sunday=0

    day_field_unrestricted = day_field.startswith('*')
    dow_field_unrestricted = dow_field.startswith('*')

    if day_field_unrestricted and dow_field_unrestricted:
        # Both unrestricted: both must match
        return day_of_month in days and day_of_week in dows
    elif day_field_unrestricted or dow_field_unrestricted:
        # One unrestricted: either can match
        if day_field_unrestricted:
            return day_of_week in dows and day_of_month in days
        else:
            return day_of_month in days and day_of_week in dows
    else:
        # Both restricted: either can match
        return day_of_month in days or day_of_week in dows

