    """Parse a single cron field and return a set of valid values."""

    if spec == "*":
        return set(range(min_val, max_val + 1))

    values = set()

    for item in spec.split(","):
        item = item.strip()

        if "/" in item:
            # Handle */S or A-B/S format
            range_part, step_str = item.rsplit("/", 1)

            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value in {field_name}: {step_str}")

            if step < 1:
                raise ValueError(f"Step must be >= 1 in {field_name}: {step}")

            if range_part == "*":
                start, end = min_val, max_val
            elif "-" in range_part:
                parts = range_part.split("-")
                if len(parts) != 2:
                    raise ValueError(f"Invalid range in {field_name}: {range_part}")
                try:
                    start, end = int(parts[0]), int(parts[1])
                except ValueError:
                    raise ValueError(f"Invalid range values in {field_name}: {range_part}")
                if start > end:
                    raise ValueError(f"Invalid range in {field_name}: {start} > {end}")
            else:
                try:
                    start = int(range_part)
                    end = start
                except ValueError:
                    raise ValueError(f"Invalid value in {field_name}: {range_part}")

            if start < min_val or end > max_val:
                raise ValueError(f"Value out of range for {field_name}: {start}-{end}")

            for v in range(start, end + 1, step):
                values.add(v)

        elif "-" in item:
            # Handle A-B format
            parts = item.split("-")
            if len(parts) != 2:
                raise ValueError(f"Invalid range in {field_name}: {item}")
            try:
                start, end = int(parts[0]), int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range values in {field_name}: {item}")
            if start > end:
                raise ValueError(f"Invalid range in {field_name}: {start} > {end}")
            if start < min_val or end > max_val:
                raise ValueError(f"Value out of range for {field_name}: {start}-{end}")

            for v in range(start, end + 1):
                values.add(v)

        else:
            # Handle single value
            try:
                v = int(item)
            except ValueError:
                raise ValueError(f"Invalid value in {field_name}: {item}")
            if v < min_val or v > max_val:
                raise ValueError(f"Value out of range for {field_name}: {v}")
            values.add(v)

    return values


def matches_cron(dt: datetime, minutes: set, hours: set, days: set, months: set, 
                 dows: set, day_spec: str, dow_spec: str) -> bool:
    """Check if a datetime matches the cron expression."""

    # Check minute, hour, month
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Get the day of week (0 = Monday in Python, but 0 = Sunday in cron)
    python_dow = dt.weekday()  # 0 = Monday
    cron_dow = (python_dow + 1) % 7  # Convert to cron format (0 = Sunday)

    # Day matching: classic cron behavior
    day_matches = dt.day in days
    dow_matches = cron_dow in dows

    # If both day-of-month and day-of-week don't start with *, either can match
    # Otherwise, both must match
    day_spec_is_star = day_spec.startswith("*")
    dow_spec_is_star = dow_spec.startswith("*")

    if not day_spec_is_star and not dow_spec_is_star:
        # Both are restricted: either matches
        return day_matches or dow_matches
    else:
        # At least one is unrestricted: both must match
        return day_matches and dow_matches

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Times are in the form YYYY-MM-DDTHH:MM with no seconds and no time zone.
    """
    # Parse the cron expression
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_expr, hour_expr, day_expr, month_expr, dow_expr = parts

    # Parse each field
    minutes = parse_field(minute_expr, 0, 59)
    hours = parse_field(hour_expr, 0, 23)
    days = parse_field(day_expr, 1, 31)
    months = parse_field(month_expr, 1, 12)
    dows = parse_field(dow_expr, 0, 7)

    # Normalize day of week (both 0 and 7 mean Sunday)
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    # Parse the after time
    after_dt = datetime.fromisoformat(after)

    # Start searching from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Search for up to 8 years
    end_search = after_dt + timedelta(days=8*365+2)  # Account for leap years

    day_of_month_restricted = not day_expr.startswith('*')
    dow_restricted = not dow_expr.startswith('*')

    while current <= end_search:
        # Check if current time matches the cron expression
        if matches_cron(current, minutes, hours, days, months, dows, 
                       day_of_month_restricted, dow_restricted):
            return current.strftime('%Y-%m-%dT%H:%M')

        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 8 years")

def parse_field(field: str, min_val: int, max_val: int) -> set:
    """Parse a single cron field and return the set of matching values."""
    values = set()

    # Handle comma-separated items
    items = field.split(',')
    for item in items:
        if '/' in item:
            # Handle step values
            range_part, step_part = item.rsplit('/', 1)
            try:
                step = int(step_part)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_part}")

            if step <= 0:
                raise ValueError(f"Step must be positive: {step}")

            if range_part == '*':
                # */step
                for v in range(min_val, max_val + 1, step):
                    values.add(v)
            elif '-' in range_part:
                # start-end/step
                try:
                    start, end = range_part.split('-', 1)
                    start = int(start)
                    end = int(end)
                except ValueError:
                    raise ValueError(f"Invalid range: {range_part}")

                if start < min_val or start > max_val or end < min_val or end > max_val:
                    raise ValueError(f"Value out of range [{min_val}, {max_val}]: {range_part}")
                if start > end:
                    raise ValueError(f"Invalid range: {start} > {end}")

                for v in range(start, end + 1, step):
                    values.add(v)
            else:
                raise ValueError(f"Invalid step expression: {item}")
        elif '-' in item:
            # Handle ranges
            try:
                start, end = item.split('-', 1)
                start = int(start)
                end = int(end)
            except ValueError:
                raise ValueError(f"Invalid range: {item}")

            if start < min_val or start > max_val or end < min_val or end > max_val:
                raise ValueError(f"Value out of range [{min_val}, {max_val}]: {item}")
            if start > end:
                raise ValueError(f"Invalid range: {start} > {end}")

            for v in range(start, end + 1):
                values.add(v)
        elif item == '*':
            # Match all values
            for v in range(min_val, max_val + 1):
                values.add(v)
        else:
            # Single value
            try:
                v = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if v < min_val or v > max_val:
                raise ValueError(f"Value out of range [{min_val}, {max_val}]: {v}")
            values.add(v)

    return values

def matches_cron(dt: datetime, minutes: set, hours: set, days: set, months: set, dows: set,
                 day_of_month_restricted: bool, dow_restricted: bool) -> bool:
    """Check if a datetime matches the cron expression."""
    # Check minute, hour, and month (always restricted)
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Handle day matching with the special cron rule
    day_of_month_matches = dt.day in days
    day_of_week_matches = dt.weekday() in dows or (dt.weekday() == 6 and 0 in dows)  # Monday=0, Sunday=6

    # Convert Python's weekday (Monday=0, Sunday=6) to cron's (Sunday=0, Monday=1)
    cron_dow = (dt.weekday() + 1) % 7  # Convert: Mon=0 -> 1, Sun=6 -> 0
    day_of_week_matches = cron_dow in dows

    if day_of_month_restricted and dow_restricted:
        # Both restricted: match if either matches
        return day_of_month_matches or day_of_week_matches
    else:
        # At least one is unrestricted: both must match
        return day_of_month_matches and day_of_week_matches

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Times are strings in the form YYYY-MM-DDTHH:MM.
    expr has five fields: minute, hour, day of month, month, day of week.
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_expr, hour_expr, day_expr, month_expr, dow_expr = fields

    # Parse each field
    try:
        minutes = parse_field(minute_expr, 0, 59)
        hours = parse_field(hour_expr, 0, 23)
        days = parse_field(day_expr, 1, 31)
        months = parse_field(month_expr, 1, 12)
        dows = parse_field(dow_expr, 0, 7)
    except (ValueError, IndexError) as e:
        raise ValueError(f"Invalid cron expression: {e}")

    # Normalize day of week (both 0 and 7 mean Sunday)
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    # Parse the after time
    try:
        after_dt = datetime.fromisoformat(after)
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Start searching from the next minute
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Search for up to 8 years
    end_time = after_dt + timedelta(days=8*365.25)

    while current <= end_time:
        if matches_cron(current, minutes, hours, days, months, dows, 
                       day_expr, dow_expr):
            return current.strftime("%Y-%m-%dT%H:%M")
        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 8 years")


def parse_field(field: str, min_val: int, max_val: int) -> set:
    """Parse a single cron field and return a set of matching values."""
    values = set()

    # Handle comma-separated items
    items = field.split(',')

    for item in items:
        if '/' in item:
            # Handle step values
            if item.startswith('*/'):
                # */S format
                step_str = item[2:]
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError(f"Invalid step value: {step_str}")
                if step < 1:
                    raise ValueError(f"Step must be >= 1, got {step}")
                for v in range(min_val, max_val + 1, step):
                    values.add(v)
            else:
                # A-B/S format
                range_part, step_str = item.rsplit('/', 1)
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError(f"Invalid step value: {step_str}")
                if step < 1:
                    raise ValueError(f"Step must be >= 1, got {step}")

                if '-' not in range_part:
                    raise ValueError(f"Invalid range format: {item}")

                start_str, end_str = range_part.split('-', 1)
                try:
                    start = int(start_str)
                    end = int(end_str)
                except ValueError:
                    raise ValueError(f"Invalid range values: {range_part}")

                if start < min_val or end > max_val:
                    raise ValueError(f"Range out of bounds: {start}-{end}")
                if start > end:
                    raise ValueError(f"Invalid range: {start} > {end}")

                for v in range(start, end + 1, step):
                    values.add(v)
        elif '-' in item:
            # Handle range A-B
            parts = item.split('-')
            if len(parts) != 2:
                raise ValueError(f"Invalid range format: {item}")
            try:
                start = int(parts[0])
                end = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range values: {item}")

            if start < min_val or end > max_val:
                raise ValueError(f"Range out of bounds: {start}-{end}")
            if start > end:
                raise ValueError(f"Invalid range: {start} > {end}")

            for v in range(start, end + 1):
                values.add(v)
        elif item == '*':
            # Match all values
            for v in range(min_val, max_val + 1):
                values.add(v)
        else:
            # Single value
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")
            if val < min_val or val > max_val:
                raise ValueError(f"Value out of range: {val}")
            values.add(val)

    return values


def matches_cron(dt: datetime, minutes: set, hours: set, days: set, months: set,
                dows: set, day_expr: str, dow_expr: str) -> bool:
    """Check if a datetime matches the cron expression."""

    # Check minute, hour, and month
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Day matching logic
    # If both day and dow don't start with *, both must match
    # If either starts with *, special handling
    day_unrestricted = day_expr.startswith('*')
    dow_unrestricted = dow_expr.startswith('*')

    day_matches = dt.day in days
    # Python's weekday: Monday=0, Sunday=6
    # Cron's dow: Sunday=0, Monday=1, ..., Saturday=6
    cron_dow = (dt.weekday() + 1) % 7
    dow_matches = cron_dow in dows

    if day_unrestricted and dow_unrestricted:
        # Both unrestricted, both must match
        return day_matches and dow_matches
    elif day_unrestricted:
        # Day is unrestricted (starts with *), only dow matters
        return dow_matches
    elif dow_unrestricted:
        # Dow is unrestricted (starts with *), only day matters
        return day_matches
    else:
        # Both restricted, either can match
        return day_matches or dow_matches

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Time format: YYYY-MM-DDTHH:MM
    Cron fields: minute hour day month day_of_week
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_field, hour_field, day_field, month_field, dow_field = fields

    # Parse each field into a set of valid values
    minute_values = parse_field(minute_field, 0, 59, "minute")
    hour_values = parse_field(hour_field, 0, 23, "hour")
    day_values = parse_field(day_field, 1, 31, "day")
    month_values = parse_field(month_field, 1, 12, "month")
    dow_values = parse_field(dow_field, 0, 7, "day_of_week")

    # Normalize dow_values (both 0 and 7 mean Sunday)
    if 7 in dow_values:
        dow_values.discard(7)
        dow_values.add(0)

    # Check if day fields are restricted or use the full range
    day_field_restricted = not day_field.startswith("*")
    dow_field_restricted = not dow_field.startswith("*")

    # Parse the after timestamp
    try:
        current = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid timestamp format: {after}")

    # Move to the next minute
    current += timedelta(minutes=1)

    # Search for up to 8 years
    max_iterations = 8 * 365 * 24 * 60 + 1000  # Add buffer for leap years
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        # Check if current time matches the cron expression
        if matches_cron(current, minute_values, hour_values, day_values, month_values, dow_values, day_field_restricted, dow_field_restricted):
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 8 years")

def parse_field(field: str, min_val: int, max_val: int, field_name: str) -> set:
    """Parse a single cron field and return a set of valid values."""
    values = set()

    # Split by comma for multiple items
    items = field.split(",")

    for item in items:
        if "/" in item:
            # Handle step values: */S or A-B/S
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError(f"Invalid step syntax in {field_name}: {item}")

            try:
                step = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid step value in {field_name}: {parts[1]}")

            if step <= 0:
                raise ValueError(f"Step must be >= 1 in {field_name}: {step}")

            if parts[0] == "*":
                # */S: every S-th value starting from min_val
                for v in range(min_val, max_val + 1, step):
                    values.add(v)
            else:
                # A-B/S: every S-th value in range A-B
                if "-" not in parts[0]:
                    raise ValueError(f"Invalid range syntax in {field_name}: {parts[0]}")

                range_parts = parts[0].split("-")
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid range syntax in {field_name}: {parts[0]}")

                try:
                    start = int(range_parts[0])
                    end = int(range_parts[1])
                except ValueError:
                    raise ValueError(f"Invalid range values in {field_name}: {parts[0]}")

                if start < min_val or end > max_val or start > end:
                    raise ValueError(f"Range out of bounds or invalid in {field_name}: {parts[0]}")

                for v in range(start, end + 1, step):
                    values.add(v)

        elif "-" in item:
            # Handle range: A-B
            range_parts = item.split("-")
            if len(range_parts) != 2:
                raise ValueError(f"Invalid range syntax in {field_name}: {item}")

            try:
                start = int(range_parts[0])
                end = int(range_parts[1])
            except ValueError:
                raise ValueError(f"Invalid range values in {field_name}: {item}")

            if start < min_val or end > max_val or start > end:
                raise ValueError(f"Range out of bounds or invalid in {field_name}: {item}")

            for v in range(start, end + 1):
                values.add(v)

        elif item == "*":
            # Every value
            for v in range(min_val, max_val + 1):
                values.add(v)

        else:
            # Single value
            try:
                v = int(item)
            except ValueError:
                raise ValueError(f"Invalid value in {field_name}: {item}")

            if v < min_val or v > max_val:
                raise ValueError(f"Value out of range in {field_name}: {v}")

            values.add(v)

    return values

def matches_cron(dt: datetime, minutes: set, hours: set, days: set, months: set, dows: set, day_field_restricted: bool, dow_field_restricted: bool) -> bool:
    """Check if a datetime matches the cron expression."""

    # Check minute, hour, month
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Convert Python weekday (0-6, Monday-Sunday) to cron weekday (0-6, Sunday-Saturday)
    # Python: Monday=0, Tuesday=1, ..., Sunday=6
    # Cron: Sunday=0, Monday=1, ..., Saturday=6
    python_weekday = dt.weekday()
    cron_weekday = (python_weekday + 1) % 7

    day_matches = dt.day in days
    dow_matches = cron_weekday in dows

    # If both day and dow fields are restricted, use OR logic
    if day_field_restricted and dow_field_restricted:
        return day_matches or dow_matches
    # If only day field is restricted, check day only
    elif day_field_restricted:
        return day_matches
    # If only dow field is restricted, check dow only
    elif dow_field_restricted:
        return dow_matches
    # If neither is restricted (both are *), both must match (which they always do for *)
    else:
        return True

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Args:
        expr: Cron expression with 5 fields (minute, hour, day, month, day_of_week)
        after: Time string in format "YYYY-MM-DDTHH:MM"

    Returns:
        Time string in format "YYYY-MM-DDTHH:MM" matching the cron expression

    Raises:
        ValueError: If expression is malformed or no match found within 8 years
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_expr, hour_expr, day_expr, month_expr, dow_expr = fields

    # Parse each field
    def parse_field(field_str, min_val, max_val):
        """Parse a cron field and return set of matching values"""
        values = set()

        for item in field_str.split(','):
            item = item.strip()

            if item == '*':
                values.update(range(min_val, max_val + 1))
            elif '/' in item:
                # Handle */S or A-B/S
                parts = item.split('/')
                if len(parts) != 2:
                    raise ValueError(f"Invalid step syntax: {item}")

                try:
                    step = int(parts[1])
                except ValueError:
                    raise ValueError(f"Step must be integer: {parts[1]}")

                if step < 1:
                    raise ValueError(f"Step must be >= 1, got {step}")

                if parts[0] == '*':
                    values.update(range(min_val, max_val + 1, step))
                elif '-' in parts[0]:
                    range_parts = parts[0].split('-')
                    if len(range_parts) != 2:
                        raise ValueError(f"Invalid range: {parts[0]}")
                    try:
                        start, end = int(range_parts[0]), int(range_parts[1])
                    except ValueError:
                        raise ValueError(f"Range bounds must be integers: {parts[0]}")
                    if start < min_val or end > max_val or start > end:
                        raise ValueError(f"Range out of bounds or invalid: {parts[0]}")
                    values.update(range(start, end + 1, step))
                else:
                    try:
                        start = int(parts[0])
                    except ValueError:
                        raise ValueError(f"Invalid value: {parts[0]}")
                    if start < min_val or start > max_val:
                        raise ValueError(f"Value out of range: {start}")
                    values.update(range(start, max_val + 1, step))
            elif '-' in item:
                # Handle A-B
                range_parts = item.split('-')
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid range: {item}")
                try:
                    start, end = int(range_parts[0]), int(range_parts[1])
                except ValueError:
                    raise ValueError(f"Range bounds must be integers: {item}")
                if start < min_val or end > max_val or start > end:
                    raise ValueError(f"Range out of bounds or invalid: {item}")
                values.update(range(start, end + 1))
            else:
                # Handle single value
                try:
                    val = int(item)
                except ValueError:
                    raise ValueError(f"Invalid value: {item}")
                if val < min_val or val > max_val:
                    raise ValueError(f"Value out of range: {val}")
                values.add(val)

        return values

    minutes = parse_field(minute_expr, 0, 59)
    hours = parse_field(hour_expr, 0, 23)
    days = parse_field(day_expr, 1, 31)
    months = parse_field(month_expr, 1, 12)

    # Special handling for day of week (0 and 7 both mean Sunday)
    dow_values = parse_field(dow_expr, 0, 7)
    dows = set()
    for v in dow_values:
        if v == 7:
            dows.add(0)
        else:
            dows.add(v)

    # Check if day matching should use both fields or either field
    day_expr_starts_with_star = day_expr.startswith('*')
    dow_expr_starts_with_star = dow_expr.startswith('*')

    # Parse the starting time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Start searching from the next minute
    current = after_dt + timedelta(minutes=1)

    # Search for up to 8 years
    end_search = after_dt + timedelta(days=8*365 + 2)  # Account for leap years

    while current <= end_search:
        # Check if current time matches the cron expression
        minute = current.minute
        hour = current.hour
        day = current.day
        month = current.month
        dow = current.weekday()
        dow = (dow + 1) % 7  # Convert Python weekday (0=Monday) to cron (0=Sunday)

        # Check minute, hour, month
        if minute not in minutes or hour not in hours or month not in months:
