        # Check day matching
        day_of_month_matches = day in days
        day_of_week_matches = dow in dows

        if day_expr_starts_with_star and dow_expr_starts_with_star:
            # Both start with *, both must match
            day_matches = day_of_month_matches and day_of_week_matches
        elif day_expr_starts_with_star:
            # Only day-of-month starts with *, so day-of-week is the actual restriction
            day_matches = day_of_week_matches
        elif dow_expr_starts_with_star:
            # Only day-of-week starts with *, so day-of-month is the actual restriction
            day_matches = day_of_month_matches
        else:
            # Neither starts with *, either can match
            day_matches = day_of_month_matches or day_of_week_matches

        if day_matches:
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)

    raise ValueError(f"No matching time found within 8 years after {after}")

from datetime import datetime, timedelta
from typing import Set

def next_cron(expr: str, after: str) -> str:
    """
    Find the first time strictly after `after` that matches the cron expression `expr`.

    Args:
        expr: Cron expression with 5 fields (minute, hour, day, month, day_of_week)
        after: Time string in format "YYYY-MM-DDTHH:MM"

    Returns:
        First matching time in format "YYYY-MM-DDTHH:MM"

    Raises:
        ValueError: If expression is malformed or no match within 8 years
    """

    # Parse cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_field, hour_field, day_field, month_field, dow_field = fields

    # Parse each field
    minutes = parse_field(minute_field, 0, 59)
    hours = parse_field(hour_field, 0, 23)
    days = parse_field(day_field, 1, 31)
    months = parse_field(month_field, 1, 12)
    dows = parse_field(dow_field, 0, 7)

    # Normalize day of week (both 0 and 7 mean Sunday)
    if 7 in dows:
        dows.discard(7)
        dows.add(0)

    # Parse the starting time
    try:
        after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Start checking from the next minute
    current = after_dt + timedelta(minutes=1)
    end_time = after_dt + timedelta(days=int(8*365.25))

    # Determine day matching logic based on spec
    day_field_starts_with_star = day_field.startswith("*")
    dow_field_starts_with_star = dow_field.startswith("*")

    while current <= end_time:
        # Check if current time matches
        if current.minute in minutes and current.hour in hours and current.month in months:

            # Day matching logic per spec
            day_matches = current.day in days
            dow_matches = (current.weekday() + 1) % 7 in dows  # Convert Python weekday to cron

            # If both day and dow fields start with *, both must match
            if day_field_starts_with_star and dow_field_starts_with_star:
                if day_matches and dow_matches:
                    return current.strftime("%Y-%m-%dT%H:%M")
            # If neither starts with *, either can match (OR logic)
            elif not day_field_starts_with_star and not dow_field_starts_with_star:
                if day_matches or dow_matches:
                    return current.strftime("%Y-%m-%dT%H:%M")
            # If only day starts with *, day must match (and dow restricts)
            elif day_field_starts_with_star:
                if day_matches and dow_matches:
                    return current.strftime("%Y-%m-%dT%H:%M")
            # If only dow starts with *, dow must match (and day restricts)
            else:
                if day_matches and dow_matches:
                    return current.strftime("%Y-%m-%dT%H:%M")

        # Move to next minute, handling invalid dates gracefully
        try:
            current += timedelta(minutes=1)
        except (ValueError, OverflowError):
            break

    raise ValueError("No matching time found within 8 years")


def parse_field(field: str, min_val: int, max_val: int) -> Set[int]:
    """
    Parse a single cron field and return the set of matching values.

    Args:
        field: The field string (e.g., "*/15", "1-5", "0,30")
        min_val: Minimum value for this field
        max_val: Maximum value for this field

    Returns:
        Set of integers that match this field

    Raises:
        ValueError: If the field is malformed
    """

    result = set()

    # Handle comma-separated items
    items = field.split(",")

    for item in items:
        if "/" in item:
            # Range with step: "*/5", "10-20/2", etc.
            range_part, step_part = item.split("/", 1)

            try:
                step = int(step_part)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_part}")

            if step <= 0:
                raise ValueError(f"Step must be >= 1, got {step}")

            if range_part == "*":
                # */S means every S-th value starting from min_val
                for v in range(min_val, max_val + 1, step):
                    result.add(v)
            elif "-" in range_part:
                # A-B/S
                try:
                    start, end = range_part.split("-", 1)
                    start_val = int(start)
                    end_val = int(end)
                except ValueError:
                    raise ValueError(f"Invalid range: {range_part}")

                if start_val > end_val:
                    raise ValueError(f"Invalid range: {start_val} > {end_val}")
                if start_val < min_val or end_val > max_val:
                    raise ValueError(f"Value out of range [{min_val}, {max_val}]")

                for v in range(start_val, end_val + 1, step):
                    result.add(v)
            else:
                raise ValueError(f"Invalid range/step format: {item}")

        elif "-" in item:
            # Range: "1-5"
            try:
                start, end = item.split("-", 1)
                start_val = int(start)
                end_val = int(end)
            except ValueError:
                raise ValueError(f"Invalid range: {item}")

            if start_val > end_val:
                raise ValueError(f"Invalid range: {start_val} > {end_val}")
            if start_val < min_val or end_val > max_val:
                raise ValueError(f"Value out of range [{min_val}, {max_val}]")

            for v in range(start_val, end_val + 1):
                result.add(v)

        elif item == "*":
            # All values
            for v in range(min_val, max_val + 1):
                result.add(v)

        else:
            # Single value
            try:
                val = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if val < min_val or val > max_val:
                raise ValueError(f"Value out of range [{min_val}, {max_val}]: {val}")

            result.add(val)

    return result

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Times are in format YYYY-MM-DDTHH:MM with no seconds or timezone.
    Cron expression has 5 fields: minute hour day month day_of_week
    """

    # Parse the input time
    try:
        current = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError(f"Invalid time format: {after}")

    # Parse cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_expr, hour_expr, day_expr, month_expr, dow_expr = fields

    # Parse each field
    minutes = parse_cron_field(minute_expr, 0, 59)
    hours = parse_cron_field(hour_expr, 0, 23)
    days = parse_cron_field(day_expr, 1, 31)
    months = parse_cron_field(month_expr, 1, 12)
    dow_values = parse_cron_field(dow_expr, 0, 7)

    # Normalize day of week (both 0 and 7 mean Sunday)
    dows = set()
    for d in dow_values:
        dows.add(d if d != 7 else 0)

    # Check if we need special day matching logic
    day_expr_unrestricted = day_expr.startswith("*")
    dow_expr_unrestricted = dow_expr.startswith("*")

    # Search for next matching time
    # Start from the next minute
    current = current + timedelta(minutes=1)

    # Search up to 8 years in the future
    max_iterations = 8 * 365 * 24 * 60 + 1000  # Add buffer for leap years

    for _ in range(max_iterations):
        minute = current.minute
        hour = current.hour
        day = current.day
        month = current.month
        year = current.year
        dow = current.weekday()  # Monday = 0, Sunday = 6
        dow = (dow + 1) % 7  # Convert to cron format (Sunday = 0)

        # Check minute and hour
        if minute not in minutes or hour not in hours:
            current += timedelta(minutes=1)
            continue

        # Check month
        if month not in months:
            current += timedelta(minutes=1)
            continue

        # Check day matching
        day_matches = False
        dow_matches = dow in dows
        day_of_month_matches = day in days

        if day_expr_unrestricted and dow_expr_unrestricted:
            # Both unrestricted: both must match
            day_matches = day_of_month_matches and dow_matches
        elif day_expr_unrestricted or dow_expr_unrestricted:
            # One unrestricted: both must match (unrestricted field still filters by its values)
            day_matches = day_of_month_matches and dow_matches
        else:
            # Both restricted: either can match
            day_matches = day_of_month_matches or dow_matches

        if day_matches:
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)

    raise ValueError(f"No matching time found within 8 years after {after}")


def parse_cron_field(field: str, min_val: int, max_val: int) -> set:
    """
    Parse a single cron field and return the set of matching values.
    """
    values = set()

    # Handle comma-separated items
    items = field.split(",")

    for item in items:
        if "/" in item:
            # Step value: */S or A-B/S
            base, step = item.split("/")
            try:
                step = int(step)
            except ValueError:
                raise ValueError(f"Invalid step value: {step}")

            if step <= 0:
                raise ValueError(f"Step value must be >= 1, got {step}")

            if base == "*":
                # */S: every S-th value starting from min_val
                for v in range(min_val, max_val + 1, step):
                    values.add(v)
            else:
                # A-B/S: every S-th value in range
                if "-" not in base:
                    raise ValueError(f"Invalid range format: {base}")
                try:
                    a, b = base.split("-")
                    a = int(a)
                    b = int(b)
                except ValueError:
                    raise ValueError(f"Invalid range: {base}")

                if a > b:
                    raise ValueError(f"Invalid range: {a}-{b}")
                if a < min_val or b > max_val:
                    raise ValueError(f"Value out of range [{min_val}, {max_val}]: {base}")

                for v in range(a, b + 1, step):
                    values.add(v)
        elif "-" in item:
            # Range: A-B
            try:
                a, b = item.split("-")
                a = int(a)
                b = int(b)
            except ValueError:
                raise ValueError(f"Invalid range: {item}")

            if a > b:
                raise ValueError(f"Invalid range: {a}-{b}")
            if a < min_val or b > max_val:
                raise ValueError(f"Value out of range [{min_val}, {max_val}]: {item}")

            for v in range(a, b + 1):
                values.add(v)
        elif item == "*":
            # All values
            for v in range(min_val, max_val + 1):
                values.add(v)
        else:
            # Single value
            try:
                v = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if v < min_val or v > max_val:
                raise ValueError(f"Value out of range [{min_val}, {max_val}]: {v}")

            values.add(v)

    return values

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Returns the first time strictly after `after` that matches the cron expression `expr`.

    Times are in format YYYY-MM-DDTHH:MM with no seconds and no timezone.
    Cron expression has 5 fields: minute, hour, day of month, month, day of week.
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    minute_spec, hour_spec, dom_spec, month_spec, dow_spec = fields

    # Parse each field
    minutes = parse_field(minute_spec, 0, 59)
    hours = parse_field(hour_spec, 0, 23)
    days_of_month = parse_field(dom_spec, 1, 31)
    months = parse_field(month_spec, 1, 12)
    days_of_week = parse_field(dow_spec, 0, 7)

    # Normalize day of week (both 0 and 7 mean Sunday)
    if 7 in days_of_week:
        days_of_week.discard(7)
        days_of_week.add(0)

    # Parse the after time
    after_dt = datetime.fromisoformat(after)

    # Start searching from one minute after
    current = after_dt + timedelta(minutes=1)
    current = current.replace(second=0, microsecond=0)

    # Search for up to 8 years
    max_iterations = 8 * 365 * 24 * 60 + 1000  # ~8 years in minutes
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        if matches_cron(current, minutes, hours, days_of_month, months, days_of_week, dom_spec, dow_spec):
            return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)

    raise ValueError("No matching time found within 8 years")


def parse_field(spec: str, min_val: int, max_val: int) -> set:
    """Parse a single cron field and return a set of matching values."""

    if spec == "*":
        return set(range(min_val, max_val + 1))

    if spec.startswith("*/"):
        try:
            step = int(spec[2:])
            if step <= 0:
                raise ValueError(f"Step must be positive: {spec}")
            return set(range(min_val, max_val + 1, step))
        except (ValueError, IndexError) as e:
            raise ValueError(f"Invalid field: {spec}") from e

    result = set()

    for item in spec.split(","):
        item = item.strip()

        if "/" in item:
            # Range with step: A-B/S
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError(f"Invalid field: {spec}")

            try:
                step = int(parts[1])
                if step <= 0:
                    raise ValueError(f"Step must be positive: {spec}")
            except ValueError as e:
                raise ValueError(f"Invalid field: {spec}") from e

            if "-" in parts[0]:
                range_parts = parts[0].split("-")
                if len(range_parts) != 2:
                    raise ValueError(f"Invalid field: {spec}")
                try:
                    start = int(range_parts[0])
                    end = int(range_parts[1])
                except ValueError as e:
                    raise ValueError(f"Invalid field: {spec}") from e

                if start > end:
                    raise ValueError(f"Invalid range: {spec}")
                if start < min_val or end > max_val:
                    raise ValueError(f"Value out of range: {spec}")

                result.update(range(start, end + 1, step))
            else:
                # */S form
                try:
                    val = int(parts[0])
                    if val != min_val:
                        raise ValueError(f"Invalid field: {spec}")
                except ValueError as e:
                    raise ValueError(f"Invalid field: {spec}") from e

                result.update(range(min_val, max_val + 1, step))

        elif "-" in item:
            # Range: A-B
            range_parts = item.split("-")
            if len(range_parts) != 2:
                raise ValueError(f"Invalid field: {spec}")
            try:
                start = int(range_parts[0])
                end = int(range_parts[1])
            except ValueError as e:
                raise ValueError(f"Invalid field: {spec}") from e

            if start > end:
                raise ValueError(f"Invalid range: {spec}")
            if start < min_val or end > max_val:
                raise ValueError(f"Value out of range: {spec}")

            result.update(range(start, end + 1))

        else:
            # Single value
            try:
                val = int(item)
            except ValueError as e:
                raise ValueError(f"Invalid field: {spec}") from e

            if val < min_val or val > max_val:
                raise ValueError(f"Value out of range: {spec}")

            result.add(val)

    return result


def matches_cron(dt: datetime, minutes: set, hours: set, days_of_month: set, 
                 months: set, days_of_week: set, dom_spec: str, dow_spec: str) -> bool:
    """Check if a datetime matches the cron expression."""

    # Check minute, hour, month (always must match)
    if dt.minute not in minutes:
        return False
    if dt.hour not in hours:
        return False
    if dt.month not in months:
        return False

    # Day matching logic
    dom_is_restricted = not dom_spec.startswith("*")
    dow_is_restricted = not dow_spec.startswith("*")

    day_matches = dt.day in days_of_month
    dow_matches = dt.weekday() in {(d - 1) % 7 for d in days_of_week}  # Convert cron DOW to Python DOW

    # Classic cron logic
    if dom_is_restricted and dow_is_restricted:
        # Both restricted: match if either matches
        return day_matches or dow_matches
    else:
        # At least one is unrestricted (starts with *): both must match
        return day_matches and dow_matches

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
    """
    Find the next time after `after` that matches the cron expression `expr`.

    Args:
        expr: Cron expression with 5 fields (minute hour day month dayofweek)
        after: Time string in format YYYY-MM-DDTHH:MM

    Returns:
        Next matching time in format YYYY-MM-DDTHH:MM

    Raises:
        ValueError: If expression is malformed or no match found within 8 years
    """

    # Parse the cron expression
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_expr, hour_expr, day_expr, month_expr, dow_expr = fields

    # Parse each field
    minute_vals = parse_field(minute_expr, 0, 59)
    hour_vals = parse_field(hour_expr, 0, 23)
    day_vals = parse_field(day_expr, 1, 31)
    month_vals = parse_field(month_expr, 1, 12)
    dow_vals = parse_field(dow_expr, 0, 7)

    # Normalize dow_vals: convert 7 to 0 for Sunday
    dow_vals = {7 if v == 0 else v if v != 7 else 0 for v in dow_vals}
    dow_vals = {0 if v == 7 else v for v in dow_vals}

    # Parse the starting time
    after_dt = datetime.strptime(after, "%Y-%m-%dT%H:%M")

    # Determine if day matching is restricted
    day_expr_restricted = not day_expr.startswith("*")
    dow_expr_restricted = not dow_expr.startswith("*")

    # Start checking from the next minute
    current = after_dt + timedelta(minutes=1)

    # Search for up to 8 years
    max_iterations = 8 * 365 * 24 * 60  # Approximately 8 years in minutes
    iterations = 0

    while iterations < max_iterations:
        iterations += 1

        # Check if current matches all fields
        if current.minute in minute_vals and current.hour in hour_vals and current.month in month_vals:
            # Check day matching
            day_of_month = current.day
            day_of_week = current.weekday()
            day_of_week = (day_of_week + 1) % 7  # Convert Python's Monday=0 to cron's Monday=1

            day_matches = day_of_month in day_vals
            dow_matches = day_of_week in dow_vals

            # Apply day matching logic
            if day_expr_restricted and dow_expr_restricted:
                # Both restricted: match if either matches
                if day_matches or dow_matches:
                    return current.strftime("%Y-%m-%dT%H:%M")
            else:
                # At least one starts with *: match if both match
                if day_matches and dow_matches:
                    return current.strftime("%Y-%m-%dT%H:%M")

        current += timedelta(minutes=1)

    raise ValueError(f"No matching time found within 8 years after {after}")


def parse_field(field: str, min_val: int, max_val: int) -> set:
    """
    Parse a single cron field and return the set of matching values.

    Args:
        field: Single cron field (e.g., "*/15", "1-5", "0,30")
        min_val: Minimum valid value for this field
        max_val: Maximum valid value for this field

    Returns:
        Set of matching values

    Raises:
        ValueError: If field is malformed
    """
    values = set()

    # Handle comma-separated items
    items = field.split(",")

    for item in items:
        if "/" in item:
            # Handle step values: */S or A-B/S
            range_part, step_part = item.rsplit("/", 1)

            try:
                step = int(step_part)
            except ValueError:
                raise ValueError(f"Invalid step value: {step_part}")

            if step <= 0:
                raise ValueError(f"Step must be >= 1, got {step}")

            if range_part == "*":
                # */S: every S-th value from min to max
                for v in range(min_val, max_val + 1, step):
                    values.add(v)
            else:
                # A-B/S: every S-th value in range
                if "-" not in range_part:
                    raise ValueError(f"Invalid range: {range_part}")

                parts = range_part.split("-")
                if len(parts) != 2:
                    raise ValueError(f"Invalid range: {range_part}")

                try:
                    start = int(parts[0])
                    end = int(parts[1])
                except ValueError:
                    raise ValueError(f"Invalid range values: {range_part}")

                if start < min_val or start > max_val:
                    raise ValueError(f"Start value {start} out of range [{min_val}, {max_val}]")
                if end < min_val or end > max_val:
                    raise ValueError(f"End value {end} out of range [{min_val}, {max_val}]")
                if start > end:
                    raise ValueError(f"Invalid range: {start} > {end}")

                for v in range(start, end + 1, step):
                    values.add(v)

        elif "-" in item:
            # Handle ranges: A-B
            parts = item.split("-")
            if len(parts) != 2:
                raise ValueError(f"Invalid range: {item}")

            try:
                start = int(parts[0])
                end = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid range values: {item}")

            if start < min_val or start > max_val:
                raise ValueError(f"Start value {start} out of range [{min_val}, {max_val}]")
            if end < min_val or end > max_val:
                raise ValueError(f"End value {end} out of range [{min_val}, {max_val}]")
            if start > end:
                raise ValueError(f"Invalid range: {start} > {end}")

            for v in range(start, end + 1):
                values.add(v)

        elif item == "*":
            # All values
            for v in range(min_val, max_val + 1):
                values.add(v)

        else:
            # Single value
            try:
                v = int(item)
            except ValueError:
                raise ValueError(f"Invalid value: {item}")

            if v < min_val or v > max_val:
                raise ValueError(f"Value {v} out of range [{min_val}, {max_val}]")

            values.add(v)

    return values

from fractions import Fraction
from typing import Tuple

def evaluate(expr: str) -> str:
    """Evaluate an arithmetic expression exactly using rational numbers."""

    # Tokenize the expression
    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("Empty expression")

    # Parse and evaluate
    result, pos = parse_addition(tokens, 0)

    if pos != len(tokens):
        raise ValueError("Unexpected tokens after expression")

    # Format result
    if result.denominator == 1:
        return str(result.numerator)
    else:
        return f"{result.numerator}/{result.denominator}"


def tokenize(expr: str) -> list:
    """Convert expression string into tokens."""
    tokens = []
    i = 0
    while i < len(expr):
        if expr[i].isspace():
            i += 1
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif expr[i] in '+-*/^()':
            tokens.append((expr[i], expr[i]))
            i += 1
        else:
            raise ValueError(f"Invalid character: {expr[i]}")
    return tokens


def parse_addition(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse addition and subtraction (lowest precedence)."""
    left, pos = parse_multiplication(tokens, pos)

    while pos < len(tokens) and tokens[pos][0] in ('+', '-'):
        op = tokens[pos][0]
        pos += 1
        right, pos = parse_multiplication(tokens, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right

    return left, pos


def parse_multiplication(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse multiplication and division."""
    left, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos][0] in ('*', '/'):
        op = tokens[pos][0]
        pos += 1
        right, pos = parse_power(tokens, pos)
        if op == '*':
            left = left * right
        else:
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            left = left / right

    return left, pos


def parse_power(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse exponentiation (right-associative)."""
    base, pos = parse_unary(tokens, pos)

    if pos < len(tokens) and tokens[pos][0] == '^':
