class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        """Return the current token without consuming it."""
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        """Return the current token and advance."""
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, token_type):
        """Expect a specific token and consume it."""
        token = self.consume()
        if token != token_type:
            raise ValueError(f"Expected {token_type}, got {token}")
        return token

    def parse_expression(self):
        """Parse addition/subtraction (lowest precedence)."""
        left = self.parse_additive_term()

        while self.peek() in ['+', '-']:
            op = self.consume()
            right = self.parse_additive_term()
            if op == '+':
                left = left + right
            else:  # op == '-'
                left = left - right

        return left

    def parse_additive_term(self):
        """Parse multiplication/division."""
        left = self.parse_power()

        while self.peek() in ['*', '/']:
            op = self.consume()
            right = self.parse_power()
            if op == '*':
                left = left * right
            else:  # op == '/'
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right

        return left

    def parse_power(self):
        """Parse power (right-associative)."""
        base = self.parse_unary()

        if self.peek() == '^':
            self.consume()
            exponent = self.parse_power()  # Right-associative

            # Exponent must be an integer
            if exponent.denominator != 1:
                raise ValueError("Exponent must be an integer")

            exp_int = exponent.numerator

            # Handle special cases
            if base == 0:
                if exp_int < 0:
                    raise ZeroDivisionError("0 raised to negative power")
                if exp_int == 0:
                    return Fraction(1)
                return Fraction(0)

            # General case
            return Fraction(base ** exp_int)

        return base

    def parse_unary(self):
        """Parse unary +/- and primary expressions."""
        sign = 1

        while self.peek() in ['+', '-']:
            op = self.consume()
            if op == '-':
                sign *= -1

        primary = self.parse_primary()
        return sign * primary

    def parse_primary(self):
        """Parse numbers and parenthesized expressions."""
        token = self.peek()

        if isinstance(token, int):
            self.consume()
            return Fraction(token)
        elif token == '(':
            self.consume()
            result = self.parse_expression()
            self.expect(')')
            return result
        else:
            raise ValueError(f"Expected number or '(', got {token}")

