class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        """Look at current token without consuming it."""
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self):
        """Consume and return current token."""
        token = self.peek()
        self.pos += 1
        return token

    def parse_expression(self) -> Fraction:
        """Parse addition/subtraction (lowest precedence)."""
        left = self.parse_term()

        while self.peek() and self.peek()[0] in ['+', '-']:
            op = self.consume()[0]
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term(self) -> Fraction:
        """Parse multiplication/division."""
        left = self.parse_power()

        while self.peek() and self.peek()[0] in ['*', '/']:
            op = self.consume()[0]
            right = self.parse_power()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right

        return left

    def parse_power(self) -> Fraction:
        """Parse exponentiation (right-associative)."""
        left = self.parse_unary()

        if self.peek() and self.peek()[0] == '^':
            self.consume()
            right = self.parse_power()  # Right-associative

            # Convert exponent to integer
            if right.denominator != 1:
                raise ValueError("Exponent must be an integer")
            exp = right.numerator

            # Handle 0^0 = 1
            if left == 0 and exp == 0:
                return Fraction(1)

            # Handle negative exponents
            if exp < 0:
                if left == 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return Fraction(1) / (left ** (-exp))

            return left ** exp

        return left

    def parse_unary(self) -> Fraction:
        """Parse unary + and - operators."""
        signs = []

        while self.peek() and self.peek()[0] in ['+', '-']:
            signs.append(self.consume()[0])

        value = self.parse_primary()

        # Apply unary operators from right to left (they were collected left to right)
        for sign in reversed(signs):
            if sign == '-':
                value = -value

        return value

    def parse_primary(self) -> Fraction:
        """Parse primary values: numbers and parenthesized expressions."""
        token = self.peek()

        if not token:
            raise ValueError("Unexpected end of expression")

        # Number
        if token[0] == 'NUM':
            self.consume()
            return Fraction(token[1])

        # Parenthesized expression
        if token[0] == '(':
            self.consume()
            result = self.parse_expression()

            if not self.peek() or self.peek()[0] != ')':
                raise ValueError("Missing closing parenthesis")
            self.consume()
            return result

        raise ValueError(f"Unexpected token: {token}")

