def tokenize(expr: str) -> list:
    """Tokenize the expression into a list of tokens."""
    tokens = []
    i = 0

    while i < len(expr):
        # Skip whitespace
        if expr[i].isspace():
            i += 1
            continue

        # Operators and parentheses
        if expr[i] in "+-*/^()":
            tokens.append(expr[i])
            i += 1
        # Numbers
        elif expr[i].isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        else:
            raise ValueError(f"Invalid character: {expr[i]}")

    if not tokens:
        raise ValueError("Empty expression")

    return tokens


def parse_expression(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse an expression (handles + and - at lowest precedence)."""
    left, pos = parse_term(tokens, pos)

    while pos < len(tokens) and tokens[pos] in "+-":
        op = tokens[pos]
        pos += 1
        right, pos = parse_term(tokens, pos)
        if op == "+":
            left = left + right
        else:
            left = left - right

    return left, pos


def parse_term(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse a term (* and / operators, left-associative)."""
    left, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos] in "*/":
        op = tokens[pos]
        pos += 1
        right, pos = parse_power(tokens, pos)
        if op == "*":
            left = left * right
        else:
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            left = left / right

    return left, pos


def parse_power(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse a power expression (right-associative)."""
    base, pos = parse_unary(tokens, pos)

    if pos < len(tokens) and tokens[pos] == "^":
        pos += 1
        exponent, pos = parse_power(tokens, pos)  # Right-associative

        # Exponent must be an integer
        if exponent.denominator != 1:
            raise ValueError("Exponent must be an integer")

        exp_int = exponent.numerator

        # Handle special cases for 0^0
        if base == 0 and exp_int == 0:
            return Fraction(1), pos

        # Handle negative exponents
        if exp_int < 0:
            if base == 0:
                raise ZeroDivisionError("0 raised to negative power")
            base = Fraction(1) / base
            exp_int = -exp_int

        # Compute base^exp_int
        result = Fraction(1)
        for _ in range(exp_int):
            result = result * base

        return result, pos

    return base, pos


def parse_unary(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse unary operators and primary expressions."""
    # Handle unary + and -
    sign = 1
    while pos < len(tokens) and tokens[pos] in "+-":
        if tokens[pos] == "-":
            sign = -sign
        pos += 1

    # Parse primary (number or parenthesized expression)
    if pos >= len(tokens):
        raise ValueError("Missing operand")

    if tokens[pos] == "(":
        pos += 1
        result, pos = parse_expression(tokens, pos)
        if pos >= len(tokens) or tokens[pos] != ")":
            raise ValueError("Unbalanced parentheses")
        pos += 1
    elif isinstance(tokens[pos], int):
        result = Fraction(tokens[pos])
        pos += 1
    else:
        raise ValueError(f"Unexpected token: {tokens[pos]}")

    return sign * result, pos

