class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected=None):
        token = self.current_token()
        if expected and token != expected:
            raise ValueError(f"Expected '{expected}', got '{token}'")
        if token is None:
            raise ValueError("Unexpected end of expression")
        self.pos += 1
        return token

    def parse_expression(self) -> Fraction:
        """Parse addition/subtraction (lowest precedence)."""
        left = self.parse_term()

        while self.current_token() in ['+', '-']:
            op = self.consume()
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term(self) -> Fraction:
        """Parse multiplication/division."""
        left = self.parse_unary()

        while self.current_token() in ['*', '/']:
            op = self.consume()
            right = self.parse_unary()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right

        return left

    def parse_unary(self) -> Fraction:
        """Parse unary operators and power (higher precedence)."""
        # Handle unary + and -
        sign = 1
        while self.current_token() in ['+', '-']:
            op = self.consume()
            if op == '-':
                sign *= -1

        # Parse power expression
        value = self.parse_power()
        return sign * value

    def parse_power(self) -> Fraction:
        """Parse exponentiation (right-associative)."""
        left = self.parse_primary()

        if self.current_token() == '^':
            self.consume('^')
            # Right-associative: parse the exponent as a unary expression
            right = self.parse_unary()

            # Exponent must be an integer
            if right.denominator != 1:
                raise ValueError("Exponent must be an integer")

            exp = right.numerator

            # Handle special cases for 0^n
            if left == 0:
                if exp < 0:
                    raise ZeroDivisionError("0 raised to negative power")
                if exp == 0:
                    return Fraction(1)
                return Fraction(0)

            # Handle negative exponents
            if exp < 0:
                return Fraction(1) / (left ** (-exp))
            else:
                return left ** exp

        return left

    def parse_primary(self) -> Fraction:
        """Parse primary expressions: numbers and parenthesized expressions."""
        token = self.current_token()

        if token is None:
            raise ValueError("Unexpected end of expression")

        # Parenthesized expression
        if token == '(':
            self.consume('(')
            value = self.parse_expression()
            self.consume(')')
            return value

        # Number
        if token.isdigit() or (token[0].isdigit() if token else False):
            num_str = self.consume()
            return Fraction(int(num_str))

        raise ValueError(f"Expected number or '(', got '{token}'")

