class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def current_token(self):
        """Get the current token without advancing."""
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def peek_ahead(self, offset=1):
        """Peek ahead at a token."""
        pos = self.pos + offset
        if pos < len(self.tokens):
            return self.tokens[pos]
        return None

    def consume(self):
        """Consume and return the current token."""
        token = self.current_token()
        self.pos += 1
        return token

    def parse_expression(self) -> Fraction:
        """Parse addition and subtraction (lowest precedence)."""
        left = self.parse_term()

        while self.current_token() in ['+', '-']:
            op = self.consume()
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term(self) -> Fraction:
        """Parse multiplication and division."""
        left = self.parse_power()

        while self.current_token() in ['*', '/']:
            op = self.consume()
            right = self.parse_power()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right

        return left

    def parse_power(self) -> Fraction:
        """Parse exponentiation (right-associative)."""
        base = self.parse_unary()

        if self.current_token() == '^':
            self.consume()
            exponent = self.parse_power()  # Right-associative

            # Exponent must be an integer
            if exponent.denominator != 1:
                raise ValueError("Exponent must be an integer")

            exp_int = exponent.numerator

            # Handle special case 0^0 = 1
            if base == 0 and exp_int == 0:
                return Fraction(1)

            # Handle negative exponents
            if exp_int < 0:
                if base == 0:
                    raise ZeroDivisionError("0 raised to negative power")
                return Fraction(1) / (base ** (-exp_int))

            return base ** exp_int

        return base

    def parse_unary(self) -> Fraction:
        """Parse unary plus and minus."""
        sign = 1

        while self.current_token() in ['+', '-']:
            op = self.consume()
            if op == '-':
                sign *= -1

        result = self.parse_primary()
        return Fraction(sign) * result

    def parse_primary(self) -> Fraction:
        """Parse primary expressions (numbers and parenthesized expressions)."""
        token = self.current_token()

        if token is None:
            raise ValueError("Unexpected end of expression")

        # Number
        if isinstance(token, int):
            self.consume()
            return Fraction(token)

        # Parenthesized expression
        if token == '(':
            self.consume()
            result = self.parse_expression()
            if self.current_token() != ')':
                raise ValueError("Missing closing parenthesis")
            self.consume()
            return result

        # Invalid token
        raise ValueError(f"Unexpected token: {token}")

