class Parser:
    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consume(self, expected=None):
        token = self.current()
        if token is None:
            raise ValueError("Unexpected end of expression")
        if expected is not None and token[0] != expected:
            raise ValueError(f"Expected {expected}, got {token[0]}")
        self.pos += 1
        return token

    def parse_expression(self):
        """Parse addition and subtraction (lowest precedence)."""
        left = self.parse_term()

        while self.current() is not None and self.current()[0] in ('+', '-'):
            op = self.consume()[0]
            right = self.parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def parse_term(self):
        """Parse multiplication and division."""
        left = self.parse_power()

        while self.current() is not None and self.current()[0] in ('*', '/'):
            op = self.consume()[0]
            right = self.parse_power()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left = left / right

        return left

    def parse_power(self):
        """Parse exponentiation (right-associative)."""
        base = self.parse_unary()

        if self.current() is not None and self.current()[0] == '^':
            self.consume('^')
            exp = self.parse_power()  # Right-associative recursion

            # Exponent must be an integer
            if exp.denominator != 1:
                raise ValueError("Exponent must be an integer")

            exp_int = exp.numerator

            # Handle 0^0 = 1 and division by zero
            if base == 0:
                if exp_int < 0:
                    raise ZeroDivisionError("0 raised to negative power")
                if exp_int == 0:
                    return Fraction(1)
                return Fraction(0)

            # For negative bases with non-integer exponents (already checked above)
            return base ** exp_int

        return base

    def parse_unary(self):
        """Parse unary +/- and primary expressions."""
        sign = 1

        while self.current() is not None and self.current()[0] in ('+', '-'):
            op = self.consume()[0]
            if op == '-':
                sign *= -1

        primary = self.parse_primary()
        return sign * primary

    def parse_primary(self):
        """Parse numbers and parenthesized expressions."""
        token = self.current()

        if token is None:
            raise ValueError("Unexpected end of expression")

        if token[0] == 'NUM':
            self.consume()
            return Fraction(token[1])
        elif token[0] == '(':
            self.consume('(')
            result = self.parse_expression()
            self.consume(')')
            return result
        else:
