    if pos < len(tokens) and tokens[pos][0] == '^':
        pos += 1
        exponent, pos = parse_power(tokens, pos)  # Right-associative

        # Exponent must be an integer
        if exponent.denominator != 1:
            raise ValueError("Exponent must be an integer")

        exp_int = exponent.numerator

        # Handle special case 0^0 = 1
        if base == 0 and exp_int == 0:
            return Fraction(1), pos

        # Handle 0 to negative power
        if base == 0 and exp_int < 0:
            raise ZeroDivisionError("Cannot raise 0 to negative power")

        # Calculate power
        if exp_int >= 0:
            result = base ** exp_int
        else:
            # Negative exponent
            if base == 0:
