def parse_primary(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse primary expression (numbers and parentheses)."""
    if pos >= len(tokens):
        raise ValueError("Unexpected end of expression")

    token_type, token_value = tokens[pos]

