    if token_type == '(':
        pos += 1
        value, pos = parse_expression(tokens, pos)

        if pos >= len(tokens) or tokens[pos][0] != ')':
            raise ValueError("Unbalanced parentheses")

        return value, pos + 1

    raise ValueError(f"Unexpected token: {token_type}")

