    return tokens


def parse_additive(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse addition and subtraction (lowest precedence)."""
    left, pos = parse_multiplicative(tokens, pos)

    while pos < len(tokens) and tokens[pos][0] in ('+', '-'):
        op = tokens[pos][0]
        pos += 1
        right, pos = parse_multiplicative(tokens, pos)
        if op == '+':
            left = left + right
        else:
            left = left - right

    return left, pos


def parse_multiplicative(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse multiplication and division (higher precedence than +/-)."""
    left, pos = parse_power(tokens, pos)

    while pos < len(tokens) and tokens[pos][0] in ('*', '/'):
        op = tokens[pos][0]
        pos += 1
        right, pos = parse_power(tokens, pos)
        if op == '*':
            left = left * right
        else:
            if right == 0:
                raise ZeroDivisionError("Division by zero")
            left = left / right

    return left, pos


def parse_power(tokens: list, pos: int) -> Tuple[Fraction, int]:
    """Parse exponentiation (right-associative, higher precedence than */÷)."""
    left, pos = parse_unary(tokens, pos)

    if pos < len(tokens) and tokens[pos][0] == '^':
        pos += 1
        right, pos = parse_power(tokens, pos)  # Right-associative

        # Exponent must be an integer
        if right.denominator != 1:
            raise ValueError("Exponent must be an integer")

        exp = right.numerator

