import re

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Uses fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """

    # Must start with P
    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    s = s[1:]  # Remove 'P'

    # Check for empty string after P
    if not s:
        raise ValueError("At least one component must be present")

    # Split into date and time parts
    if 'T' in s:
        parts = s.split('T')
        if len(parts) != 2:
            raise ValueError("Multiple 'T' characters not allowed")
        date_part, time_part = parts
        if not time_part:
            raise ValueError("'T' must be followed by at least one component")
    else:
        date_part = s
        time_part = ""

    total_seconds = 0

    # Parse date part
    if date_part:
        # Check if it's only weeks
        if 'W' in date_part:
            if len(date_part) != date_part.find('W') + 1 or any(c in date_part for c in 'YMD'):
                raise ValueError("'W' cannot be combined with other components")
            # Parse weeks only
            match = re.match(r'^(\d+(?:[.,]\d+)?)W$', date_part)
            if not match:
                raise ValueError("Invalid week component")
            weeks = parse_number(match.group(1))
            total_seconds += weeks * 7 * 86400
        else:
            # Parse Y, M, D components
            pattern = r'^(?:(\d+(?:[.,]\d+)?)Y)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)D)?$'
            match = re.match(pattern, date_part)
            if not match:
                raise ValueError("Invalid date component format")

            years, months, days = match.groups()

            if not any([years, months, days]):
                raise ValueError("At least one component must be present")

            # Check that fraction only appears in last component
            components = [years, months, days]
            last_component = next((c for c in reversed(components) if c is not None), None)
            for component in components:
                if component and component != last_component and ('.' in component or ',' in component):
                    raise ValueError("Only the last component can have a fractional part")

            if years:
                total_seconds += parse_number(years) * 365 * 86400
            if months:
                total_seconds += parse_number(months) * 30 * 86400
            if days:
                total_seconds += parse_number(days) * 86400

    # Parse time part
    if time_part:
        pattern = r'^(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?$'
        match = re.match(pattern, time_part)
        if not match:
            raise ValueError("Invalid time component format")

        hours, minutes, seconds = match.groups()

        if not any([hours, minutes, seconds]):
            raise ValueError("'T' must be followed by at least one component")

        # Check that fraction only appears in last component
        components = [hours, minutes, seconds]
        last_component = next((c for c in reversed(components) if c is not None), None)
        for component in components:
            if component and component != last_component and ('.' in component or ',' in component):
                raise ValueError("Only the last component can have a fractional part")

        if hours:
            total_seconds += parse_number(hours) * 3600
        if minutes:
            total_seconds += parse_number(minutes) * 60
        if seconds:
            total_seconds += parse_number(seconds)

    # Check if we have at least one component total
    if total_seconds == 0 and not date_part and not time_part:
        raise ValueError("At least one component must be present")

    return int(total_seconds)


def parse_number(s: str) -> float:
    """Parse a number that may contain . or , as decimal separator."""
    # Replace comma with dot for consistency
    s = s.replace(',', '.')
    return float(s)

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Uses fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """

    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("Duration must start with 'P'")

    if len(s) == 1:
        raise ValueError("Duration must have at least one component")

    s = s[1:]  # Remove 'P'

    # Split by 'T' to separate date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = s
        time_part = ""

    # Parse date part
    years = 0
    months = 0
    days = 0
    weeks = 0

    if date_part:
        # Check if 'W' is present
        if 'W' in date_part:
            # 'W' must be alone
            if len(date_part) != date_part.index('W') + 2:
                raise ValueError("'W' cannot be combined with other components")
            # Parse weeks
            weeks_str = date_part[:date_part.index('W')]
            if not weeks_str or not is_valid_number(weeks_str):
                raise ValueError("Invalid weeks component")
            weeks = int(weeks_str)
        else:
            # Parse Y, M, D
            date_part = parse_date_part(date_part)
            years = date_part.get('Y', 0)
            months = date_part.get('M', 0)
            days = date_part.get('D', 0)

    # Parse time part
    hours = 0
    minutes = 0
    seconds_val = 0.0

    if time_part:
        time_dict = parse_time_part(time_part)
        hours = time_dict.get('H', 0)
        minutes = time_dict.get('M', 0)
        seconds_val = time_dict.get('S', 0.0)

    # Check that at least one component is present
    if years == 0 and months == 0 and days == 0 and weeks == 0 and \
       hours == 0 and minutes == 0 and seconds_val == 0:
        raise ValueError("At least one component must be present")

    # Convert to seconds
    total_seconds = (
        years * 365 * 86400 +
        months * 30 * 86400 +
        days * 86400 +
        weeks * 7 * 86400 +
        hours * 3600 +
        minutes * 60 +
        seconds_val
    )

    return int(total_seconds)


def is_valid_number(s: str) -> bool:
    """Check if string is a valid non-negative decimal number."""
    if not s:
        return False

    # Count dots/commas (should be at most 1)
    frac_count = s.count('.') + s.count(',')
    if frac_count > 1:
        return False

    if frac_count == 0:
        return s.isdigit()

    # Has a fraction separator
    for char in s:
        if char not in '0123456789.,':
            return False

    parts = s.replace(',', '.').split('.')
    if len(parts) != 2:
        return False

    # Both sides must have at least one digit
    if not parts[0] or not parts[1]:
        return False

    return parts[0].isdigit() and parts[1].isdigit()


def parse_date_part(date_part: str) -> dict:
    """Parse the date part (Y, M, D components)."""
    result = {}
    expected_order = ['Y', 'M', 'D']
    last_letter_idx = -1
    i = 0

    while i < len(date_part):
        if date_part[i] in 'YMD':
            letter = date_part[i]
            # Check order
            current_idx = expected_order.index(letter)
            if current_idx <= last_letter_idx:
                raise ValueError(f"Invalid order or duplicate letter '{letter}'")

            # Find the number before this letter
            j = i - 1
            while j >= 0 and date_part[j] not in 'YMD':
                j -= 1

            if j < 0:
                num_start = 0
            else:
                num_start = j + 1

            num_str = date_part[num_start:i]
            if not num_str or not is_valid_number(num_str):
                raise ValueError(f"Invalid number before '{letter}'")

            if letter in result:
                raise ValueError(f"Duplicate letter '{letter}'")

            result[letter] = int(num_str.replace(',', '.').split('.')[0])
            last_letter_idx = current_idx
            i += 1
        else:
            i += 1

    return result


def parse_time_part(time_part: str) -> dict:
    """Parse the time part (H, M, S components)."""
    result = {}
    expected_order = ['H', 'M', 'S']
    last_letter_idx = -1

    # Find all letters and their positions
    letters_pos = []
    for i, char in enumerate(time_part):
        if char in 'HMS':
            letters_pos.append((i, char))

    if not letters_pos:
        raise ValueError("Time part must have at least one component")

    for idx, (pos, letter) in enumerate(letters_pos):
        # Check order
        current_idx = expected_order.index(letter)
        if current_idx <= last_letter_idx:
            raise ValueError(f"Invalid order or duplicate letter '{letter}'")

        # Get number before this letter
        if idx == 0:
            num_start = 0
        else:
            num_start = letters_pos[idx - 1][0] + 1

        num_str = time_part[num_start:pos]
        if not num_str or not is_valid_number(num_str):
            raise ValueError(f"Invalid number before '{letter}'")

        # Parse the number (may have fraction)
        if '.' in num_str or ',' in num_str:
            num_str = num_str.replace(',', '.')
            result[letter] = float(num_str)
        else:
            result[letter] = int(num_str)

        last_letter_idx = current_idx

    return result

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Uses fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """

    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    s = s[1:]  # Remove 'P'

    if not s:
        raise ValueError("At least one component must be present")

    # Split into date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
        if not time_part:
            raise ValueError("T must be followed by at least one component")
    else:
        date_part = s
        time_part = ""

    # Parse date part
    years = 0
    months = 0
    weeks = 0
    days = 0

    if date_part:
        i = 0
        while i < len(date_part):
            # Find the number (integer or decimal)
            j = i
            has_dot = False
            while j < len(date_part) and (date_part[j].isdigit() or date_part[j] in '.,'):
                if date_part[j] in '.,':
                    if has_dot:
                        raise ValueError("Multiple decimal points in one component")
                    has_dot = True
                j += 1

            if j == i:
                raise ValueError(f"Expected number in date part at position {i}")

            number_str = date_part[i:j]

            if j >= len(date_part):
                raise ValueError("Number must be followed by a letter")

            letter = date_part[j]

            if letter not in 'YMD W':
                raise ValueError(f"Invalid letter '{letter}' in date part")

            if letter == ' ':
                raise ValueError("No spaces allowed")

            # Parse the number
            if has_dot:
                raise ValueError("Fractional parts only allowed in the last component")

            number = int(number_str)

            if letter == 'Y':
                if months > 0 or days > 0 or weeks > 0:
                    raise ValueError("Y must come before M, D, and W")
                years = number
            elif letter == 'M':
                if days > 0 or weeks > 0:
                    raise ValueError("M (months) must come before D and W")
                months = number
            elif letter == 'W':
                if years > 0 or months > 0 or days > 0:
                    raise ValueError("W cannot be combined with other date components")
                weeks = number
            elif letter == 'D':
                if weeks > 0:
                    raise ValueError("D must come before W or W must be alone")
                days = number

            i = j + 1

        # Check for W exclusivity
        if weeks > 0 and (years > 0 or months > 0 or days > 0):
            raise ValueError("W cannot be combined with Y, M, or D")

    # Parse time part
    hours = 0
    minutes = 0
    seconds = 0

    if time_part:
        i = 0
        while i < len(time_part):
            # Find the number (integer or decimal)
            j = i
            has_dot = False
            while j < len(time_part) and (time_part[j].isdigit() or time_part[j] in '.,'):
                if time_part[j] in '.,':
                    if has_dot:
                        raise ValueError("Multiple decimal points in one component")
                    has_dot = True
                j += 1

            if j == i:
                raise ValueError(f"Expected number in time part at position {i}")

            number_str = time_part[i:j]

            if j >= len(time_part):
                raise ValueError("Number must be followed by a letter")

            letter = time_part[j]

            if letter not in 'HMS':
                raise ValueError(f"Invalid letter '{letter}' in time part")

            # Check if this is the last component
            is_last = (j + 1 == len(time_part))

            # Parse the number
            if has_dot:
                if not is_last:
                    raise ValueError("Fractional part only allowed in the last component")
                # Handle fractional part
                parts = number_str.replace(',', '.').split('.')
                if len(parts) != 2 or not parts[0] or not parts[1]:
                    raise ValueError("Fractional part must have digits on both sides")
                number = float(number_str.replace(',', '.'))
            else:
                number = int(number_str)

            if letter == 'H':
                if minutes > 0 or seconds > 0:
                    raise ValueError("H must come before M and S")
                hours = number
            elif letter == 'M':
                if seconds > 0:
                    raise ValueError("M (minutes) must come before S")
                minutes = number
            elif letter == 'S':
                seconds = number

            i = j + 1

    # Ensure at least one component is present
    if years == 0 and months == 0 and weeks == 0 and days == 0 and hours == 0 and minutes == 0 and seconds == 0:
        raise ValueError("At least one component must be present")

    # Convert everything to seconds
    total_seconds = 0
    total_seconds += years * 365 * 86400
    total_seconds += months * 30 * 86400
    total_seconds += weeks * 7 * 86400
    total_seconds += days * 86400
    total_seconds += hours * 3600
    total_seconds += minutes * 60
    total_seconds += seconds

    return int(total_seconds)

import re

def iso_duration_seconds(s: str) -> int:
    """Parse an ISO 8601 duration string and return its length in seconds."""

    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    s = s[1:]

    if not s:
        raise ValueError("Duration must contain at least one component")

    # Split by T
    if 'T' in s:
        t_pos = s.index('T')
        date_part = s[:t_pos]
        time_part = s[t_pos+1:]
        if not time_part:
            raise ValueError("Time part after 'T' cannot be empty")
    else:
        date_part = s
        time_part = ""

    # Parse with regex
    date_pattern = r'(\d+(?:[.,]\d+)?)([YMWD])'
    time_pattern = r'(\d+(?:[.,]\d+)?)([HMS])'

    components = {}

    # Parse date part
    if date_part:
        matches = re.findall(date_pattern, date_part)
        reconstructed = ''.join(f"{n}{l}" for n, l in matches)
        if reconstructed != date_part:
            raise ValueError("Invalid date part format")

        prev_order = -1
        order_map = {'Y': 0, 'M': 1, 'W': 2, 'D': 3}
        has_week = False

        for num_str, letter in matches:
            current_order = order_map.get(letter, -1)
            if current_order <= prev_order:
                raise ValueError("Components out of order")
            prev_order = current_order

            if letter == 'W':
                has_week = True

            if letter in components:
                raise ValueError(f"Duplicate component '{letter}'")

            components[letter] = _parse_number(num_str)

        if has_week and len(components) > 1:
            raise ValueError("Week cannot be combined with other date components")

    # Parse time part
    if time_part:
        matches = re.findall(time_pattern, time_part)
        reconstructed = ''.join(f"{n}{l}" for n, l in matches)
        if reconstructed != time_part:
            raise ValueError("Invalid time part format")

        prev_order = -1
        order_map = {'H': 0, 'M': 1, 'S': 2}

        for idx, (num_str, letter) in enumerate(matches):
            current_order = order_map.get(letter, -1)
            if current_order <= prev_order:
                raise ValueError("Components out of order")
            prev_order = current_order

            is_last = (idx == len(matches) - 1)
            value = _parse_number(num_str, allow_fraction=is_last)

            components[f'T{letter}'] = value

    if not components:
        raise ValueError("Duration must contain at least one component")

    # Calculate total seconds
    total = 0
    total += components.get('Y', 0) * 365 * 86400
    total += components.get('M', 0) * 30 * 86400
    total += components.get('W', 0) * 7 * 86400
    total += components.get('D', 0) * 86400
    total += components.get('TH', 0) * 3600
    total += components.get('TM', 0) * 60
    total += components.get('TS', 0)

    return total


def _parse_number(num_str: str, allow_fraction: bool = False) -> int:
    """Parse a number that may have fractional part."""
    if '.' in num_str or ',' in num_str:
        if not allow_fraction:
            raise ValueError("Fractional part not allowed")
        num_str = num_str.replace(',', '.')
        return int(float(num_str))
    return int(num_str)

import re
from decimal import Decimal

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Uses fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """

    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("Duration must start with 'P'")

    # Remove the leading 'P'
    remaining = s[1:]

    if not remaining:
        raise ValueError("At least one component must be present")

    # Split into date and time parts
    if 'T' in remaining:
        date_part, time_part = remaining.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one component")
    else:
        date_part = remaining
        time_part = ""

    total_seconds = 0

    # Parse date part
    if date_part:
        total_seconds += _parse_date_part(date_part)

    # Parse time part
    if time_part:
        total_seconds += _parse_time_part(time_part)

    if total_seconds == 0 and not date_part and not time_part:
        raise ValueError("At least one component must be present")

    return int(total_seconds)


def _parse_date_part(date_part: str) -> float:
    """Parse the date part of an ISO 8601 duration."""

    # Check for weeks (can only stand alone)
    if 'W' in date_part:
        # Weeks must be alone
        match = re.match(r'^(\d+(?:[.,]\d+)?)W$', date_part)
        if not match:
            raise ValueError("Weeks (W) cannot be combined with other date components")
        weeks_str = match.group(1).replace(',', '.')
        weeks = Decimal(weeks_str)
        return float(weeks * 7 * 86400)

    # Parse Y, M, D components (in that order)
    total_seconds = 0.0
    pattern = r'^(?:(\d+(?:[.,]\d+)?)Y)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)D)?$'
    match = re.match(pattern, date_part)

    if not match:
        raise ValueError("Invalid date part format")

    years_str, months_str, days_str = match.groups()

    if not any([years_str, months_str, days_str]):
        raise ValueError("Date part must contain at least one component")

    if years_str:
        # Fractional parts only allowed in last component
        if '.' in years_str or ',' in years_str:
            if months_str or days_str:
                raise ValueError("Fractional part only allowed in last component")
        years = Decimal(years_str.replace(',', '.'))
        total_seconds += float(years * 365 * 86400)

    if months_str:
        # Fractional parts only allowed in last component
        if '.' in months_str or ',' in months_str:
            if days_str:
                raise ValueError("Fractional part only allowed in last component")
        months = Decimal(months_str.replace(',', '.'))
        total_seconds += float(months * 30 * 86400)

    if days_str:
        days = Decimal(days_str.replace(',', '.'))
        total_seconds += float(days * 86400)

    return total_seconds


def _parse_time_part(time_part: str) -> float:
    """Parse the time part of an ISO 8601 duration (after T)."""

    # Parse H, M, S components (in that order)
    total_seconds = 0.0
    pattern = r'^(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?$'
    match = re.match(pattern, time_part)

    if not match:
        raise ValueError("Invalid time part format")

    hours_str, minutes_str, seconds_str = match.groups()

    if not any([hours_str, minutes_str, seconds_str]):
        raise ValueError("Time part must contain at least one component")

    if hours_str:
        # Fractional parts only allowed in last component
        if '.' in hours_str or ',' in hours_str:
            if minutes_str or seconds_str:
                raise ValueError("Fractional part only allowed in last component")
        hours = Decimal(hours_str.replace(',', '.'))
        total_seconds += float(hours * 3600)

    if minutes_str:
        # Fractional parts only allowed in last component
        if '.' in minutes_str or ',' in minutes_str:
            if seconds_str:
                raise ValueError("Fractional part only allowed in last component")
        minutes = Decimal(minutes_str.replace(',', '.'))
        total_seconds += float(minutes * 60)

    if seconds_str:
        seconds = Decimal(seconds_str.replace(',', '.'))
        total_seconds += float(seconds)

    return total_seconds


