import re

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Uses fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """

    # Must start with P
    if not s.startswith('P'):
        raise ValueError("Duration must start with 'P'")

    s = s[1:]  # Remove 'P'

    if not s:
        raise ValueError("Duration must have at least one component")

    # Split into date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = s
        time_part = ""

    total_seconds = 0

    # Parse date part
    if date_part:
        # Check for weeks - they must be alone
        if 'W' in date_part:
            # Weeks must be the only component
            if len(date_part) > date_part.index('W') + 1:
                raise ValueError("Weeks cannot be combined with other date components")
            # Check for other date letters before W
            if any(c in date_part[:date_part.index('W')] for c in 'YMD'):
                raise ValueError("Weeks cannot be combined with other date components")

            # Parse weeks
            match = re.match(r'^(\d+(?:[.,]\d+)?)W$', date_part)
            if not match:
                raise ValueError("Invalid weeks format")
            weeks = float(match.group(1).replace(',', '.'))
            total_seconds += int(weeks * 7 * 86400)
        else:
            # Parse Y, M, D components
            seen = set()
            i = 0
            while i < len(date_part):
                # Find the number part
                j = i
                while j < len(date_part) and (date_part[j].isdigit() or date_part[j] in '.,'):
                    j += 1

                if j == i:
                    raise ValueError("Invalid date component format")

                num_str = date_part[i:j]

                if j >= len(date_part):
                    raise ValueError("Number must be followed by a letter")

                letter = date_part[j]

                if letter not in 'YMD':
                    raise ValueError(f"Invalid date letter: {letter}")

                if letter in seen:
                    raise ValueError(f"Duplicate date component: {letter}")

                if letter == 'Y' and ('M' in seen or 'D' in seen):
                    raise ValueError("Date components must be in order: Y, M, D")
                if letter == 'M' and 'D' in seen:
                    raise ValueError("Date components must be in order: Y, M, D")

                seen.add(letter)

                # Check if this is the last component (may have fraction)
                is_last = (j + 1 == len(date_part))

                # Parse number
                if '.' in num_str or ',' in num_str:
                    if not is_last:
                        raise ValueError("Only the last component can have a fractional part")
                    num = float(num_str.replace(',', '.'))
                else:
                    num = float(num_str)

                if letter == 'Y':
                    total_seconds += int(num * 365 * 86400)
                elif letter == 'M':
                    total_seconds += int(num * 30 * 86400)
                elif letter == 'D':
                    total_seconds += int(num * 86400)

                i = j + 1

    # Parse time part
    if time_part:
        seen = set()
        i = 0
        while i < len(time_part):
            # Find the number part
            j = i
            while j < len(time_part) and (time_part[j].isdigit() or time_part[j] in '.,'):
                j += 1

            if j == i:
                raise ValueError("Invalid time component format")

            num_str = time_part[i:j]

            if j >= len(time_part):
                raise ValueError("Number must be followed by a letter")

            letter = time_part[j]

            if letter not in 'HMS':
                raise ValueError(f"Invalid time letter: {letter}")

            if letter in seen:
                raise ValueError(f"Duplicate time component: {letter}")

            if letter == 'H' and ('M' in seen or 'S' in seen):
                raise ValueError("Time components must be in order: H, M, S")
            if letter == 'M' and 'S' in seen:
                raise ValueError("Time components must be in order: H, M, S")

            seen.add(letter)

            # Check if this is the last component (may have fraction)
            is_last = (j + 1 == len(time_part))

            # Parse number
            if '.' in num_str or ',' in num_str:
                if not is_last:
                    raise ValueError("Only the last component can have a fractional part")
                num = float(num_str.replace(',', '.'))
            else:
                num = float(num_str)

            if letter == 'H':
                total_seconds += int(num * 3600)
            elif letter == 'M':
                total_seconds += int(num * 60)
            elif letter == 'S':
                total_seconds += int(num)

            i = j + 1

    return total_seconds

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Uses fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """
    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    s = s[1:]  # Remove 'P'

    # Split into date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one component")
    else:
        date_part = s
        time_part = ""

    # Parse date part
    years = 0
    months = 0
    weeks = 0
    days = 0

    if date_part:
        # Check for week format (W must be alone)
        if 'W' in date_part:
            if len(date_part) != date_part.index('W') + 1:
                raise ValueError("'W' cannot be combined with other date components")
            weeks = parse_component(date_part, 'W', is_last=True)
        else:
            # Find which component is last in date part
            last_letter = None
            for letter in ['D', 'M', 'Y']:
                if letter in date_part:
                    last_letter = letter
                    break

            years = parse_component(date_part, 'Y', is_last=(last_letter == 'Y'))
            months = parse_component(date_part, 'M', is_last=(last_letter == 'M'))
            days = parse_component(date_part, 'D', is_last=(last_letter == 'D'))

            # Validate order: Y before M before D
            indices = {}
            for letter, value in [('Y', years), ('M', months), ('D', days)]:
                if value > 0 or (letter in date_part and '.' not in date_part and ',' not in date_part):
                    idx = date_part.find(letter)
                    if idx >= 0:
                        indices[letter] = idx

            letters = list(indices.keys())
            expected_order = sorted(letters, key=lambda x: {'Y': 0, 'M': 1, 'D': 2}[x])
            if letters != expected_order:
                raise ValueError("Date components out of order")

    # Parse time part
    hours = 0
    minutes = 0
    seconds = 0

    if time_part:
        # Find which component is last in time part
        last_letter = None
        for letter in ['S', 'M', 'H']:
            if letter in time_part:
                last_letter = letter
                break

        hours = parse_component(time_part, 'H', is_last=(last_letter == 'H'))
        minutes = parse_component(time_part, 'M', is_last=(last_letter == 'M'))
        seconds = parse_component(time_part, 'S', is_last=(last_letter == 'S'))

        # Validate order: H before M before S
        indices = {}
        for letter in ['H', 'M', 'S']:
            if letter in time_part:
                idx = time_part.find(letter)
                indices[letter] = idx

        letters = list(indices.keys())
        expected_order = sorted(letters, key=lambda x: {'H': 0, 'M': 1, 'S': 2}[x])
        if letters != expected_order:
            raise ValueError("Time components out of order")

    # Check that at least one component is present
    if years + months + weeks + days + hours + minutes + seconds == 0:
        raise ValueError("At least one component must be present")

    # Convert everything to seconds
    total_seconds = (
        years * 365 * 86400 +
        months * 30 * 86400 +
        weeks * 7 * 86400 +
        days * 86400 +
        hours * 3600 +
        minutes * 60 +
        seconds
    )

    return int(total_seconds)


def parse_component(s: str, letter: str, is_last: bool = False) -> float:
    """
    Extract and parse a component from the duration string.
    Returns the numeric value (possibly fractional).
    Fractions are only allowed on the last component.
    """
    if letter not in s:
        return 0

    idx = s.find(letter)

    # Find the start of this component (after previous letter or at start)
    start = 0
    for i in range(idx - 1, -1, -1):
        if s[i].isalpha():
            start = i + 1
            break

    # Extract the number part
    num_str = s[start:idx]

    if not num_str:
        raise ValueError(f"Missing number before '{letter}'")

    # Check for fraction
    if '.' in num_str or ',' in num_str:
        if not is_last:
            raise ValueError(f"Fraction not allowed for '{letter}'")

        # Replace comma with dot for parsing
        num_str = num_str.replace(',', '.')

        # Validate fraction format: at least one digit on each side
        if '.' not in num_str:
            raise ValueError("Invalid fraction format")

        parts = num_str.split('.')
        if len(parts) != 2 or not parts[0] or not parts[1]:
            raise ValueError("Invalid fraction format")

        if not parts[0].isdigit() or not parts[1].isdigit():
            raise ValueError("Invalid number format")

        return float(num_str)
    else:
        if not num_str.isdigit():
            raise ValueError(f"Invalid number format before '{letter}'")
        return float(num_str)

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """

    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    s = s[1:]  # Remove 'P'

    if not s:
        raise ValueError("Duration must have at least one component")

    # Split into date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T')
        if not time_part:
            raise ValueError("'T' must be followed by at least one component")
    else:
        date_part = s
        time_part = ""

    # Parse date part
    years = 0
    months = 0
    weeks = 0
    days = 0

    if date_part:
        # Check for invalid week combination
        has_w = 'W' in date_part
        has_other = any(c in date_part for c in 'YMD')

        if has_w and has_other:
            raise ValueError("Week 'W' cannot be combined with other date components")

        i = 0
        while i < len(date_part):
            # Find the number
            j = i
            while j < len(date_part) and (date_part[j].isdigit() or date_part[j] in '.,'):
                j += 1

            if j == i:
                raise ValueError(f"Invalid date part format at position {i}")

            number_str = date_part[i:j]

            if j >= len(date_part):
                raise ValueError("Number without component letter in date part")

            component = date_part[j]

            # Parse the number (handle decimal point/comma)
            if '.' in number_str or ',' in number_str:
                raise ValueError("Fractional component only allowed as last component in time part")

            try:
                value = int(number_str)
            except ValueError:
                raise ValueError(f"Invalid number in date part: {number_str}")

            if component == 'Y':
                if years != 0:
                    raise ValueError("Component 'Y' appears more than once")
                years = value
            elif component == 'M':
                if months != 0:
                    raise ValueError("Component 'M' appears more than once in date part")
                months = value
            elif component == 'W':
                if weeks != 0:
                    raise ValueError("Component 'W' appears more than once")
                weeks = value
            elif component == 'D':
                if days != 0:
                    raise ValueError("Component 'D' appears more than once")
                days = value
            else:
                raise ValueError(f"Invalid component '{component}' in date part")

            i = j + 1

    # Parse time part
    hours = 0
    minutes = 0
    seconds = 0

    if time_part:
        i = 0
        last_component_index = None
        # Find the last component
        for j in range(len(time_part) - 1, -1, -1):
            if time_part[j] in 'HMS':
                last_component_index = j
                break

        while i < len(time_part):
            # Find the number
            j = i
            while j < len(time_part) and (time_part[j].isdigit() or time_part[j] in '.,'):
                j += 1

            if j == i:
                raise ValueError(f"Invalid time part format at position {i}")

            number_str = time_part[i:j]

            if j >= len(time_part):
                raise ValueError("Number without component letter in time part")

            component = time_part[j]

            # Check if this is the last component
            is_last = (j == last_component_index)

            # Parse the number
            if '.' in number_str or ',' in number_str:
                if not is_last:
                    raise ValueError("Fractional component only allowed as last component")
                # Replace comma with dot for parsing
                number_str = number_str.replace(',', '.')
                try:
                    value = float(number_str)
                except ValueError:
                    raise ValueError(f"Invalid number in time part: {number_str}")
            else:
                try:
                    value = int(number_str)
                except ValueError:
                    raise ValueError(f"Invalid number in time part: {number_str}")

            if component == 'H':
                if hours != 0:
                    raise ValueError("Component 'H' appears more than once")
                hours = value
            elif component == 'M':
                if minutes != 0:
                    raise ValueError("Component 'M' appears more than once in time part")
                minutes = value
            elif component == 'S':
                if seconds != 0:
                    raise ValueError("Component 'S' appears more than once")
                seconds = value
            else:
                raise ValueError(f"Invalid component '{component}' in time part")

            i = j + 1

    # Check that at least one component is present
    if years == 0 and months == 0 and weeks == 0 and days == 0 and hours == 0 and minutes == 0 and seconds == 0:
        raise ValueError("Duration must have at least one component")

    # Calculate total seconds
    total_seconds = 0
    total_seconds += years * 365 * 86400
    total_seconds += months * 30 * 86400
    total_seconds += weeks * 7 * 86400
    total_seconds += days * 86400
    total_seconds += hours * 3600
    total_seconds += minutes * 60
    total_seconds += seconds

    return int(total_seconds)

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    - 1 hour = 3600 seconds
    - 1 minute = 60 seconds
    """
    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    # Remove the 'P' prefix
    s = s[1:]

    if not s:
        raise ValueError("At least one component must be present")

    # Split into date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one component")
    else:
        date_part = s
        time_part = ""

    total_seconds = 0.0

    # Parse date part
    if date_part:
        total_seconds += parse_date_part(date_part)

    # Parse time part
    if time_part:
        total_seconds += parse_time_part(time_part)

    if total_seconds == 0 and not date_part and not time_part:
        raise ValueError("At least one component must be present")

    return int(total_seconds)


def parse_date_part(date_str: str) -> float:
    """Parse the date part (before T) and return seconds."""
    if not date_str:
        return 0.0

    total_seconds = 0.0
    i = 0
    has_W = False
    seen_letters = set()

    while i < len(date_str):
        # Extract number (including optional decimal part)
        num_start = i
        while i < len(date_str) and (date_str[i].isdigit() or date_str[i] in '.,'):
            i += 1

        if i == num_start:
            raise ValueError("Expected number in date part")

        num_str = date_str[num_start:i]

        if not date_str[i:i+1]:
            raise ValueError("Expected letter after number in date part")

        letter = date_str[i]
        i += 1

        # Validate letter and order
        if letter not in 'YMWD':
            raise ValueError(f"Invalid letter in date part: {letter}")

        if letter in seen_letters:
            raise ValueError(f"Duplicate letter in date part: {letter}")

        seen_letters.add(letter)

        # Check order and W exclusivity
        if letter == 'W':
            if seen_letters != {'W'}:
                raise ValueError("W cannot be combined with other components")
            has_W = True
        elif has_W:
            raise ValueError("W must be on its own")
        elif letter == 'Y':
            if 'M' in seen_letters or 'D' in seen_letters:
                raise ValueError("Invalid order of components in date part")
        elif letter == 'M':
            if 'D' in seen_letters:
                raise ValueError("Invalid order of components in date part")

        # Parse number
        value = parse_number(num_str)

        # Convert to seconds
        if letter == 'Y':
            total_seconds += value * 365 * 86400
        elif letter == 'M':
            total_seconds += value * 30 * 86400
        elif letter == 'W':
            total_seconds += value * 7 * 86400
        elif letter == 'D':
            total_seconds += value * 86400

    return total_seconds


def parse_time_part(time_str: str) -> float:
    """Parse the time part (after T) and return seconds."""
    if not time_str:
        return 0.0

    total_seconds = 0.0
    i = 0
    seen_letters = set()

    while i < len(time_str):
        # Extract number (including optional decimal part)
        num_start = i
        while i < len(time_str) and (time_str[i].isdigit() or time_str[i] in '.,'):
            i += 1

        if i == num_start:
            raise ValueError("Expected number in time part")

        num_str = time_str[num_start:i]

        if not time_str[i:i+1]:
            raise ValueError("Expected letter after number in time part")

        letter = time_str[i]
        i += 1

        # Validate letter and order
        if letter not in 'HMS':
            raise ValueError(f"Invalid letter in time part: {letter}")

        if letter in seen_letters:
            raise ValueError(f"Duplicate letter in time part: {letter}")

        seen_letters.add(letter)

        # Check order
        if letter == 'H':
            if 'M' in seen_letters or 'S' in seen_letters:
                raise ValueError("Invalid order of components in time part")
        elif letter == 'M':
            if 'S' in seen_letters:
                raise ValueError("Invalid order of components in time part")

        # Parse number
        value = parse_number(num_str)

        # Convert to seconds
        if letter == 'H':
            total_seconds += value * 3600
        elif letter == 'M':
            total_seconds += value * 60
        elif letter == 'S':
            total_seconds += value

    return total_seconds


def parse_number(num_str: str) -> float:
    """
    Parse a number that may contain a decimal point or comma.
    Returns a float to preserve fractional values.
    """
    # Replace comma with dot for consistency
    num_str = num_str.replace(',', '.')

    # Check if there's a decimal part
    if '.' in num_str:
        parts = num_str.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid number format")

        integer_part, fractional_part = parts

        if not integer_part or not fractional_part:
            raise ValueError("Decimal must have digits on both sides")

        if not integer_part.isdigit() or not fractional_part.isdigit():
            raise ValueError("Invalid number format")

        # Return as float to preserve fractional part
        return float(integer_part + '.' + fractional_part)
    else:
        if not num_str.isdigit():
            raise ValueError("Invalid number format")
        return float(num_str)

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.
    """
    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    s = s[1:]
    if not s:
        raise ValueError("Duration must have at least one component")

    # Split date and time parts
    if 'T' in s:
        date_part, time_part = s.split('T', 1)
        if not time_part:
            raise ValueError("'T' must be followed by at least one component")
    else:
        date_part = s
        time_part = ""

    total_seconds = 0.0

    # Parse date part
    if date_part:
        total_seconds += parse_date_part(date_part)

    # Parse time part
    if time_part:
        total_seconds += parse_time_part(time_part)

    return int(total_seconds)


def parse_date_part(s: str) -> float:
    """Parse the date part of a duration."""
    if 'W' in s:
        if any(c in s for c in ['Y', 'M', 'D']):
            raise ValueError("'W' cannot be combined with other components")
        return parse_component(s, 'W') * 7 * 86400

    total = 0.0
    last_pos = 0

    for component, multiplier in [('Y', 365 * 86400), ('M', 30 * 86400), ('D', 86400)]:
        if component in s:
            pos = s.index(component)
            if pos < last_pos:
                raise ValueError(f"Components out of order")
            num_str = s[last_pos:pos]
            if not is_valid_number(num_str):
                raise ValueError(f"Invalid value for {component}")
            total += float(num_str.replace(',', '.')) * multiplier
            last_pos = pos + 1

    if last_pos < len(s):
        raise ValueError(f"Invalid characters in date part")

    return total


def parse_time_part(s: str) -> float:
    """Parse the time part of a duration."""
    total = 0.0
    last_pos = 0

    for component, multiplier in [('H', 3600), ('M', 60), ('S', 1)]:
        if component in s:
            pos = s.index(component)
            if pos < last_pos:
                raise ValueError(f"Components out of order")
            num_str = s[last_pos:pos]
            if not is_valid_number(num_str):
                raise ValueError(f"Invalid value for {component}")
            total += float(num_str.replace(',', '.')) * multiplier
            last_pos = pos + 1

    if last_pos < len(s):
        raise ValueError(f"Invalid characters in time part")

    return total


def is_valid_number(s: str) -> bool:
    """Check if string is a valid number (integer or decimal)."""
    if not s:
        return False

    normalized = s.replace(',', '.')
    if '.' in normalized:
        parts = normalized.split('.')
        if len(parts) != 2 or not parts[0] or not parts[1]:
            return False
        return parts[0].isdigit() and parts[1].isdigit()

    return s.isdigit()


def parse_component(s: str, letter: str) -> float:
    """Parse a single component value."""
    if letter not in s:
        raise ValueError(f"Component {letter} not found")
    pos = s.index(letter)
    num_str = s[:pos]
    if not is_valid_number(num_str):
        raise ValueError(f"Invalid value for {letter}")
    return float(num_str.replace(',', '.'))

