def parse_date_part(s: str) -> int:
    """Parse the date part of an ISO 8601 duration."""
    seconds = 0
    i = 0
    has_week = False
    seen_letters = set()

    while i < len(s):
        # Extract number (including optional fraction)
        num_start = i
        while i < len(s) and (s[i].isdigit() or s[i] in '.,'):
            i += 1

