        if letter in seen_letters:
            raise ValueError(f"Duplicate letter '{letter}'")

        seen_letters.add(letter)

        # Check order
        order = {'Y': 0, 'M': 1, 'W': 2, 'D': 3}
        if len(seen_letters) > 1:
            prev_order = min(order.get(l, -1) for l in seen_letters if l != letter)
            if order[letter] < prev_order:
                raise ValueError("Letters out of order in date part")

        # Handle weeks separately
        if letter == 'W':
            if seen_letters - {'W'}:
                raise ValueError("'W' cannot be combined with other components")
            has_week = True
        elif has_week:
            raise ValueError("'W' cannot be combined with other components")

        # Parse the number
        num_value = parse_number(num_str)

        # Add to total
        if letter == 'Y':
            seconds += num_value * 365 * 86400
        elif letter == 'M':
            seconds += num_value * 30 * 86400
        elif letter == 'W':
            seconds += num_value * 7 * 86400
        elif letter == 'D':
            seconds += num_value * 86400

    return int(seconds)


def parse_time_part(s: str) -> int:
