def parse_date_part(s: str) -> int:
    """Parse the date part of an ISO 8601 duration (before T)."""
    if not s:
        return 0

    total_seconds = 0
    i = 0

    # Check for 'W' - weeks are standalone
    if 'W' in s:
        if len(s) > 1 and s.count('W') > 1:
            raise ValueError("'W' can only appear once")
        if 'Y' in s or 'M' in s or 'D' in s:
            raise ValueError("'W' cannot be combined with other date components")
        # Parse weeks only
        weeks_match = extract_number(s, 0)
        if weeks_match is None or weeks_match[1] != len(s) - 1 or s[-1] != 'W':
            raise ValueError("Invalid week format")
        weeks = weeks_match[0]
        return int(weeks * 7 * 86400)

    # Parse Y, M, D in order
    expected_order = ['Y', 'M', 'D']
    i = 0

    for expected_char in expected_order:
        if i >= len(s):
            break

        # Check if this character exists
        if expected_char in s[i:]:
            # Find the number before this character
            number_str = ""
            j = i
            while j < len(s) and (s[j].isdigit() or s[j] in '.,-'):
                number_str += s[j]
                j += 1

            if j >= len(s) or s[j] != expected_char:
                # This character exists but not in the right position
                raise ValueError(f"Component '{expected_char}' out of order or malformed")

            if not number_str:
                raise ValueError(f"No number before '{expected_char}'")

            number = parse_number(number_str, is_last=False)

            if expected_char == 'Y':
                total_seconds += int(number * 365 * 86400)
            elif expected_char == 'M':
                total_seconds += int(number * 30 * 86400)
            elif expected_char == 'D':
                total_seconds += int(number * 86400)

            i = j + 1

    # Check for unexpected characters
    if i < len(s):
        raise ValueError(f"Unexpected character in date part: '{s[i]}'")

    return total_seconds


def parse_time_part(s: str) -> int:
    """Parse the time part of an ISO 8601 duration (after T)."""
    if not s:
        return 0

    total_seconds = 0
    i = 0

    # Parse H, M, S in order
    expected_order = ['H', 'M', 'S']

    for expected_char in expected_order:
        if i >= len(s):
            break

        # Check if this character exists
        if expected_char in s[i:]:
            # Find the number before this character
            number_str = ""
            j = i
            while j < len(s) and (s[j].isdigit() or s[j] in '.,-'):
                number_str += s[j]
                j += 1

            if j >= len(s) or s[j] != expected_char:
                # This character exists but not in the right position
                raise ValueError(f"Component '{expected_char}' out of order or malformed")

            if not number_str:
                raise ValueError(f"No number before '{expected_char}'")

            # Check if this is the last component (can have fraction)
            is_last = (j == len(s) - 1)
            number = parse_number(number_str, is_last=is_last)

            if expected_char == 'H':
                total_seconds += int(number * 3600)
            elif expected_char == 'M':
                total_seconds += int(number * 60)
            elif expected_char == 'S':
                total_seconds += int(number)

            i = j + 1

    # Check for unexpected characters
    if i < len(s):
        raise ValueError(f"Unexpected character in time part: '{s[i]}'")

    return total_seconds


def parse_number(s: str, is_last: bool) -> float:
    """Parse a number that may contain a fractional part."""
    if not s:
        raise ValueError("Empty number")

    # Normalize comma to period
    s = s.replace(',', '.')

    # Check for fractional part
    if '.' in s:
        if not is_last:
            raise ValueError("Fractional part only allowed in last component")

        parts = s.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid fractional number")

        integer_part, fractional_part = parts

        if not integer_part or not integer_part.isdigit():
            raise ValueError("Integer part of number must be present and numeric")
        if not fractional_part or not fractional_part.isdigit():
            raise ValueError("Fractional part must have at least one digit")

        return float(s)

    if not s.isdigit():
        raise ValueError(f"Invalid number: {s}")

    return float(s)


def extract_number(s: str, start: int):
    """Extract a number starting at position start."""
    i = start
    while i < len(s) and (s[i].isdigit() or s[i] in '.,'):
        i += 1
    if i == start:
        return None
    return float(s[start:i]), i

def iso_duration_seconds(s: str) -> int:
    """
    Parse an ISO 8601 duration string and return its length in seconds.

    Fixed conversions:
    - 1 year = 365 days
    - 1 month = 30 days
    - 1 week = 7 days
    - 1 day = 86400 seconds
    """

    if not s or s[0] != 'P':
        raise ValueError("Duration must start with 'P'")

    s = s[1:]  # Remove 'P'

    if not s:
        raise ValueError("Duration must contain at least one component")

    # Split into date and time parts
    if 'T' in s:
        parts = s.split('T')
        if len(parts) != 2:
            raise ValueError("Invalid 'T' placement")
        date_part = parts[0]
        time_part = parts[1]
        if not time_part:
            raise ValueError("'T' must be followed by at least one component")
    else:
        date_part = s
        time_part = ""

    if not date_part and not time_part:
        raise ValueError("Duration must contain at least one component")

    total_seconds = 0

    # Parse date part
    if date_part:
        total_seconds += _parse_date_part(date_part)

    # Parse time part
    if time_part:
        total_seconds += _parse_time_part(time_part)

    return total_seconds


def _extract_number(s: str, start: int, end: int) -> float:
    """Extract and parse a number from position start to end (exclusive)."""
    number_str = s[start:end]

    if not number_str or not (number_str[0].isdigit() or number_str[0] in '.,'):
        raise ValueError(f"Invalid number: {number_str}")

    # Replace comma with dot
    number_str = number_str.replace(',', '.')

    try:
        return float(number_str) if '.' in number_str else int(number_str)
    except ValueError:
        raise ValueError(f"Invalid number format: {number_str}")


def _parse_date_part(date_part: str) -> int:
    """Parse the date part (before T) and return seconds."""

    if not date_part:
        return 0

    # Validate characters
    valid_chars = set('YMWD0123456789.,')
    for char in date_part:
        if char not in valid_chars:
            raise ValueError(f"Invalid character in date part: {char}")

    # Check if it's weeks-only format
    if 'W' in date_part:
        if any(c in date_part for c in 'YMD'):
            raise ValueError("Week component cannot be combined with other date components")

        # Extract W value
        w_index = date_part.index('W')
        if w_index == 0:
            raise ValueError("No number before 'W'")

        # Find start of number
        start = w_index - 1
        while start > 0 and (date_part[start-1].isdigit() or date_part[start-1] in '.,'):
            start -= 1

        weeks = _extract_number(date_part, start, w_index)
        if not isinstance(weeks, int):
            weeks = int(weeks)

        if w_index < len(date_part) - 1:
            raise ValueError("Week component must be last in date part")

        return weeks * 7 * 86400

    total_seconds = 0
    seen = set()

    # Parse Y, M, D components
    components = [('Y', 365 * 86400), ('M', 30 * 86400), ('D', 86400)]

    for letter, multiplier in components:
        if letter in date_part:
            if letter in seen:
                raise ValueError(f"Duplicate component '{letter}'")
            seen.add(letter)

            index = date_part.index(letter)
            if index == 0:
                raise ValueError(f"No number before '{letter}'")

            # Find start of number
            start = index - 1
            while start > 0 and (date_part[start-1].isdigit() or date_part[start-1] in '.,'):
                start -= 1

            value = _extract_number(date_part, start, index)

            if index < len(date_part) - 1:
                # Check if there's another component after this
                remaining = date_part[index+1:]
                if remaining and any(c in remaining for c in 'YMD'):
                    # Ensure order
                    next_letters = [c for c in 'YMD' if c in remaining]
                    if ord(letter) > ord(next_letters[0]):
                        raise ValueError("Components must be in order: Y, M, D")

            total_seconds += int(value * multiplier)

    return total_seconds


def _parse_time_part(time_part: str) -> int:
    """Parse the time part (after T) and return seconds."""

    if not time_part:
        return 0

    # Validate characters
    valid_chars = set('HMS0123456789.,')
    for char in time_part:
        if char not in valid_chars:
            raise ValueError(f"Invalid character in time part: {char}")

    total_seconds = 0
    seen = set()

    components = [('H', 3600), ('M', 60), ('S', 1)]

    for letter, multiplier in components:
        if letter in time_part:
            if letter in seen:
                raise ValueError(f"Duplicate component '{letter}'")
            seen.add(letter)

            index = time_part.index(letter)
            if index == 0:
                raise ValueError(f"No number before '{letter}'")

            # Find start of number
            start = index - 1
            while start > 0 and (time_part[start-1].isdigit() or time_part[start-1] in '.,'):
                start -= 1

            # Check if this is the last component for fractional handling
            is_last = index == len(time_part) - 1

            value = _extract_number(time_part, start, index)

            if not is_last and ('.' in time_part[start:index] or ',' in time_part[start:index]):
                raise ValueError("Fractional part is only allowed in the last component")

            if index < len(time_part) - 1:
                # Check order
                remaining = time_part[index+1:]
                if remaining and any(c in remaining for c in 'HMS'):
                    next_letters = [c for c in 'HMS' if c in remaining]
                    if ord(letter) > ord(next_letters[0]):
                        raise ValueError("Components must be in order: H, M, S")

            total_seconds += int(value * multiplier)

    return total_seconds

def parse_roman(s: str) -> int:
    """
    Convert a Roman numeral string to an integer.

    Valid strings represent integers from 1 to 3999 using uppercase I, V, X, L, C, D, M.
    Raises ValueError for invalid input.
    """
    if not s:
        raise ValueError("Empty string is not a valid Roman numeral")

    # Define Roman numeral values
    values = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    # Check all characters are valid
    for char in s:
        if char not in values:
            raise ValueError(f"Invalid character '{char}' in Roman numeral")

    # Valid subtractive pairs
    valid_subtractive = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}

    # Characters that can repeat (and how many times max)
    repeatable = {'I': 3, 'X': 3, 'C': 3, 'M': 3}
    non_repeatable = {'V', 'L', 'D'}

    result = 0
    i = 0

    while i < len(s):
        # Check for subtractive pair
        if i + 1 < len(s):
            pair = s[i:i+2]
            if pair in valid_subtractive:
                result += values[pair[1]] - values[pair[0]]
                i += 2
                continue

        # Single character
        char = s[i]

        # Check if this character can repeat
        if char in non_repeatable:
            # V, L, D cannot repeat
            result += values[char]
            i += 1
        elif char in repeatable:
            # Count consecutive occurrences
            count = 1
            while i + count < len(s) and s[i + count] == char:
                count += 1

            # Check if repetition is valid
            if count > repeatable[char]:
                raise ValueError(f"Too many consecutive '{char}' characters")

            result += values[char] * count
            i += count
        else:
            i += 1

    # Validate the result is in valid range (1-3999)
    if result < 1 or result > 3999:
        raise ValueError(f"Roman numeral value {result} is out of valid range (1-3999)")

    # Additional validation: ensure the string follows proper Roman numeral rules
    # Verify no invalid subtractive combinations and proper ordering
    for i in range(len(s) - 1):
        curr_val = values[s[i]]
        next_val = values[s[i+1]]

        # If current value is less than next, it must be a valid subtractive pair
        if curr_val < next_val:
            pair = s[i:i+2]
            if pair not in valid_subtractive:
                raise ValueError(f"Invalid subtractive pair '{pair}'")
        elif curr_val > next_val:
            # Value decreases - this is allowed (end of a group)
            pass
        # If equal, consecutive identical characters are handled above

    return result

def parse_roman(s: str) -> int:
    """
    Convert a Roman numeral to an integer.

    Only accepts correctly written Roman numerals from 1 to 3999.
    Raises ValueError for invalid input.
    """
    if not s:
        raise ValueError("Empty string is not a valid Roman numeral")

    # Define valid values and their order
    values = {
        'M': 1000,
        'D': 500,
        'C': 100,
        'L': 50,
        'X': 10,
        'V': 5,
        'I': 1
    }

    # Valid subtractive pairs
    subtractive_pairs = {'IV', 'IX', 'XL', 'XC', 'CD', 'CM'}

    # Check for invalid characters
    for char in s:
        if char not in values:
            raise ValueError(f"Invalid character '{char}' in Roman numeral")

    # Parse the numeral
    total = 0
    i = 0

    while i < len(s):
        # Check if this is a subtractive pair
        if i + 1 < len(s):
            pair = s[i:i+2]
            if pair in subtractive_pairs:
                total += values[pair[1]] - values[pair[0]]
                i += 2
                continue
            # Check for invalid subtractive cases
            if values[s[i]] < values[s[i+1]]:
                raise ValueError(f"Invalid subtractive pair '{pair}'")

        # Single character
        total += values[s[i]]
        i += 1

    # Now validate the structure by reconstructing it
    # and checking it matches the input exactly

    # Helper function to convert integer back to Roman
    def int_to_roman(num: int) -> str:
        if num < 1 or num > 3999:
            return None

        result = []

        # Thousands
        thousands = num // 1000
        result.append('M' * thousands)
        num %= 1000

        # Hundreds
        hundreds = num // 100
        if hundreds == 9:
            result.append('CM')
        elif hundreds >= 5:
            result.append('D' + 'C' * (hundreds - 5))
        elif hundreds == 4:
            result.append('CD')
        else:
            result.append('C' * hundreds)
        num %= 100

        # Tens
        tens = num // 10
        if tens == 9:
            result.append('XC')
        elif tens >= 5:
            result.append('L' + 'X' * (tens - 5))
        elif tens == 4:
            result.append('XL')
        else:
            result.append('X' * tens)
        num %= 10

        # Units
        units = num
        if units == 9:
            result.append('IX')
        elif units >= 5:
            result.append('V' + 'I' * (units - 5))
        elif units == 4:
            result.append('IV')
        else:
            result.append('I' * units)

        return ''.join(result)

    # Validate by reconstructing
    if total < 1 or total > 3999:
        raise ValueError(f"Roman numeral value {total} is out of range [1, 3999]")

    reconstructed = int_to_roman(total)
    if reconstructed != s:
        raise ValueError(f"'{s}' is not a correctly written Roman numeral")

    return total

def parse_roman(s: str) -> int:
    """
    Convert a Roman numeral string to an integer.

    Args:
        s: A string representing a Roman numeral in uppercase letters

    Returns:
        The integer value (1-3999)

    Raises:
        ValueError: If the string is not a valid Roman numeral
    """
    if not s:
        raise ValueError("Empty string is not a valid Roman numeral")

    # Check for invalid characters
    for char in s:
        if char not in "IVXLCDM":
            raise ValueError(f"Invalid character '{char}' in Roman numeral")

    # Define valid patterns for each position
    valid_thousands = ["", "M", "MM", "MMM"]
    valid_hundreds = ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"]
    valid_tens = ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"]
    valid_units = ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"]

    # Map Roman characters to their values
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50,
        'C': 100, 'D': 500, 'M': 1000
    }

    # Extract thousands
    idx = 0
    thousands_part = ""
    while idx < len(s) and s[idx] == 'M':
        thousands_part += 'M'
        idx += 1

    if thousands_part not in valid_thousands:
        raise ValueError(f"Invalid thousands part: {thousands_part}")

    # Extract hundreds
    hundreds_part = ""
    if idx < len(s) and s[idx] in "CDM":
        if s[idx] == 'C':
            hundreds_part += 'C'
            idx += 1
            while idx < len(s) and s[idx] == 'C':
                hundreds_part += 'C'
                idx += 1
            if idx < len(s) and s[idx] == 'D':
                hundreds_part += 'D'
                idx += 1
            elif idx < len(s) and s[idx] == 'M':
                hundreds_part += 'M'
                idx += 1
        elif s[idx] == 'D':
            hundreds_part += 'D'
            idx += 1
            while idx < len(s) and s[idx] == 'C':
                hundreds_part += 'C'
                idx += 1
        else:
            raise ValueError("M should only appear at the beginning")

    if hundreds_part not in valid_hundreds:
        raise ValueError(f"Invalid hundreds part: {hundreds_part}")

    # Extract tens
    tens_part = ""
    if idx < len(s) and s[idx] in "XLC":
        if s[idx] == 'X':
            tens_part += 'X'
            idx += 1
            while idx < len(s) and s[idx] == 'X':
                tens_part += 'X'
                idx += 1
            if idx < len(s) and s[idx] == 'L':
                tens_part += 'L'
                idx += 1
            elif idx < len(s) and s[idx] == 'C':
                tens_part += 'C'
                idx += 1
        elif s[idx] == 'L':
            tens_part += 'L'
            idx += 1
            while idx < len(s) and s[idx] == 'X':
                tens_part += 'X'
                idx += 1
        else:
            raise ValueError("Invalid tens part")

    if tens_part not in valid_tens:
        raise ValueError(f"Invalid tens part: {tens_part}")

    # Extract units
    units_part = ""
    if idx < len(s) and s[idx] in "IVX":
        if s[idx] == 'I':
            units_part += 'I'
            idx += 1
            while idx < len(s) and s[idx] == 'I':
                units_part += 'I'
                idx += 1
            if idx < len(s) and s[idx] == 'V':
                units_part += 'V'
                idx += 1
            elif idx < len(s) and s[idx] == 'X':
                units_part += 'X'
                idx += 1
        elif s[idx] == 'V':
            units_part += 'V'
            idx += 1
            while idx < len(s) and s[idx] == 'I':
                units_part += 'I'
                idx += 1
        else:
            raise ValueError("Invalid units part")

    if units_part not in valid_units:
        raise ValueError(f"Invalid units part: {units_part}")

    # Check if we've consumed the entire string
    if idx != len(s):
        raise ValueError(f"Invalid Roman numeral format: {s}")

    # Calculate the value
    value = 0
    for part, valid_list in [(thousands_part, valid_thousands),
                              (hundreds_part, valid_hundreds),
                              (tens_part, valid_tens),
                              (units_part, valid_units)]:
        for char in part:
            value += roman_values[char]

    return value

def parse_csv_line(line: str) -> list[str]:
    """
    Parse a single line of strict CSV format into its fields.
    """
    fields = []
    i = 0

    while i <= len(line):  # Changed to <= to process trailing empty field
        if i == len(line):
            # At end of line - only add field if previous char was comma
            if fields or i > 0:  # Add empty field if we had a comma at the end
                if i > 0 and line[i-1] == ',':
                    fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1  # Skip opening quote

            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        i += 1
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                            else:
                                raise ValueError(f"Character after closing quote")
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                raise ValueError("Unclosed quoted field")

            fields.append(field)
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    raise ValueError(f"Quote in unquoted field")
                field += line[i]
                i += 1

            fields.append(field)

            if i < len(line) and line[i] == ',':
                i += 1

    return fields

def parse_csv_line(line: str) -> list[str]:
    """
    Parse a strict CSV line into its fields.

    Fields are separated by commas. A quoted field starts with " and uses "" for literal quotes.
    An unquoted field is taken as-is and must not contain quotes.
    """
    fields = []
    i = 0

    while True:
        # Check if this field is quoted
        if i < len(line) and line[i] == '"':
            # Parse quoted field
            field = ""
            i += 1  # Skip opening quote

            while i < len(line):
                if line[i] == '"':
                    # Could be closing quote or escaped quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Escaped quote: "" means one literal "
                        field += '"'
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # After closing quote, must be comma or end of line
                        if i < len(line) and line[i] != ',':
                            raise ValueError(f"Character after closing quote must be comma or end of line, got '{line[i]}'")
                        fields.append(field)
                        if i < len(line) and line[i] == ',':
                            i += 1  # Skip the comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # We reached end of line without finding closing quote
                raise ValueError("Quoted field was never closed")
        else:
            # Parse unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    raise ValueError(f"Quote found in unquoted field")
                field += line[i]
                i += 1

            fields.append(field)
            if i < len(line) and line[i] == ',':
                i += 1  # Skip the comma
            else:
                # We've reached end of line
                break

    return fields

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.

    Args:
        a: First string
        b: Second string

    Returns:
        The lexicographically smallest LCS
    """
    m, n = len(a), len(b)

    # Build DP table for LCS length
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Backtrack to find all LCS candidates, keeping track of the lexicographically smallest
    def backtrack(i, j, current):
        """
        Backtrack through DP table to build LCS strings.
        Returns the lexicographically smallest LCS from position (i, j).
        """
        if i == 0 or j == 0:
            return current

        if a[i - 1] == b[j - 1]:
            # Characters match - must include this character
            return backtrack(i - 1, j - 1, a[i - 1] + current)
        else:
            # Characters don't match - try both directions
            # We need to follow the path that gives us the lexicographically smallest result

            if dp[i - 1][j] > dp[i][j - 1]:
                # Go up
                return backtrack(i - 1, j, current)
            elif dp[i][j - 1] > dp[i - 1][j]:
                # Go left
                return backtrack(i, j - 1, current)
            else:
                # Both paths are equally long - pick the one that gives smaller lexicographic result
                # We need to explore both and compare
                result_up = backtrack(i - 1, j, current)
                result_left = backtrack(i, j - 1, current)
                return min(result_up, result_left)

    # Use memoization to avoid recomputation
    memo = {}

    def backtrack_memo(i, j):
        """
        Returns the lexicographically smallest LCS starting from position (i, j).
        """
        if i == 0 or j == 0:
            return ""

        if (i, j) in memo:
            return memo[(i, j)]

        if a[i - 1] == b[j - 1]:
            # Characters match - include this character
            result = a[i - 1] + backtrack_memo(i - 1, j - 1)
        else:
            # Characters don't match - try both directions
            if dp[i - 1][j] > dp[i][j - 1]:
                # Going up is strictly better
                result = backtrack_memo(i - 1, j)
            elif dp[i][j - 1] > dp[i - 1][j]:
                # Going left is strictly better
                result = backtrack_memo(i, j - 1)
            else:
                # Both paths are equally long - pick the lexicographically smaller one
                result_up = backtrack_memo(i - 1, j)
                result_left = backtrack_memo(i, j - 1)
                result = min(result_up, result_left)

        memo[(i, j)] = result
        return result

    return backtrack_memo(m, n)

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.

    Args:
        a: First string
        b: Second string

    Returns:
        The lexicographically smallest longest common subsequence
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[0:i] and b[0:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Backtrack to find all LCS of the required length, keeping track of the smallest
    def backtrack(i: int, j: int, current: str) -> str:
        """
        Backtracks through the DP table to find all LCS sequences.
        Returns the lexicographically smallest one found.
        """
        if i == 0 or j == 0:
            return current

        if a[i - 1] == b[j - 1]:
            # Characters match, must include this character
            return backtrack(i - 1, j - 1, a[i - 1] + current)
        else:
            # Characters don't match, try both paths and pick the smallest result
            # We only go to the cell with the larger value (the one that contributes to LCS)
            left = None
            top = None

            if dp[i][j - 1] == dp[i][j]:
                # Can go left
                left = backtrack(i, j - 1, current)

            if dp[i - 1][j] == dp[i][j]:
                # Can go up
                top = backtrack(i - 1, j, current)

            if left is not None and top is not None:
                return min(left, top)
            elif left is not None:
                return left
            else:
                return top

    # More efficient approach: generate all LCS and return the smallest
    # For each position, we need to try all possible paths that lead to an LCS
    def find_all_lcs(i: int, j: int) -> list:
        """Returns all LCS sequences ending at position (i, j)"""
        if i == 0 or j == 0:
            return [""]

        if a[i - 1] == b[j - 1]:
            # Must use this character
            prev_lcs = find_all_lcs(i - 1, j - 1)
            return [lcs + a[i - 1] for lcs in prev_lcs]
        else:
            result = []
            if dp[i - 1][j] == dp[i][j]:
                result.extend(find_all_lcs(i - 1, j))
            if dp[i][j - 1] == dp[i][j]:
                result.extend(find_all_lcs(i, j - 1))
            return result

    # Use memoization for efficiency
    memo = {}

    def find_all_lcs_memo(i: int, j: int) -> list:
        """Returns all LCS sequences of a[0:i] and b[0:j]"""
        if (i, j) in memo:
            return memo[(i, j)]

        if i == 0 or j == 0:
            result = [""]
        elif a[i - 1] == b[j - 1]:
            # Must use this character
            prev_lcs = find_all_lcs_memo(i - 1, j - 1)
            result = [lcs + a[i - 1] for lcs in prev_lcs]
        else:
            result = []
            if dp[i - 1][j] == dp[i][j]:
                result.extend(find_all_lcs_memo(i - 1, j))
            if dp[i][j - 1] == dp[i][j]:
                result.extend(find_all_lcs_memo(i, j - 1))

        memo[(i, j)] = result
        return result

    all_lcs = find_all_lcs_memo(m, n)
    # Filter to only those of the correct length and return the smallest
    valid_lcs = [lcs for lcs in all_lcs if len(lcs) == lcs_length]

    return min(valid_lcs) if valid_lcs else ""

