        else:
            # Characters don't match
            up_length = dp[i - 1][j]
            left_length = dp[i][j - 1]

            if up_length > left_length:
                result = backtrack(i - 1, j)
            elif left_length > up_length:
                result = backtrack(i, j - 1)
            else:
                # Both have same length, pick lexicographically smaller
                up_result = backtrack(i - 1, j)
                left_result = backtrack(i, j - 1)
                result = min(up_result, left_result)

        memo[(i, j)] = result
        return result

    return backtrack(m, n)

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the longest common subsequence of a and b.
    When multiple LCS of the same length exist, returns the lexicographically smallest one.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Reconstruct all LCS strings and find the lexicographically smallest
    def reconstruct(i, j, current):
        """
        Recursively reconstruct all possible LCS strings.
        Returns a set of all LCS strings of length lcs_length.
        """
        if i == 0 or j == 0:
            if len(current) == lcs_length:
                return {current}
            else:
                return set()

        result = set()

        if a[i - 1] == b[j - 1]:
            # Character matches, include it
            subresults = reconstruct(i - 1, j - 1, a[i - 1] + current)
            result.update(subresults)
        else:
            # Character doesn't match, try both directions
            if dp[i - 1][j] >= dp[i][j - 1]:
                subresults = reconstruct(i - 1, j, current)
                result.update(subresults)

            if dp[i][j - 1] >= dp[i - 1][j]:
                subresults = reconstruct(i, j - 1, current)
                result.update(subresults)

        return result

    # Use an iterative approach with memoization to avoid stack overflow
    # Build all LCS by backtracking through the DP table
    def find_all_lcs():
        """Find all LCS strings using dynamic programming approach."""
        # memo[i][j] will store all LCS strings of a[:i] and b[:j]
        memo = [[set() for _ in range(n + 1)] for _ in range(m + 1)]

        # Base case: empty strings
        for i in range(m + 1):
            memo[i][0].add("")
        for j in range(n + 1):
            memo[0][j].add("")

        # Fill memo table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if a[i - 1] == b[j - 1]:
                    # Character matches, extend all LCS from previous state
                    for lcs in memo[i - 1][j - 1]:
                        memo[i][j].add(lcs + a[i - 1])
                else:
                    # Character doesn't match
                    if dp[i - 1][j] > dp[i][j - 1]:
                        memo[i][j] = memo[i - 1][j].copy()
                    elif dp[i][j - 1] > dp[i - 1][j]:
                        memo[i][j] = memo[i][j - 1].copy()
                    else:  # dp[i - 1][j] == dp[i][j - 1]
                        memo[i][j] = memo[i - 1][j] | memo[i][j - 1]

        return memo[m][n]

    all_lcs = find_all_lcs()

    # Return the lexicographically smallest LCS
    return min(all_lcs) if all_lcs else ""

