            if dp[i - 1][j] == dp[i][j]:
                results.update(reconstruct(i - 1, j, path))
            if dp[i][j - 1] == dp[i][j]:
                results.update(reconstruct(i, j - 1, path))

        return results

    # For larger inputs, use a more efficient approach
    # Instead of reconstructing all, we build the lexicographically smallest directly

    # Memoization for efficient reconstruction
    memo = {}

    def find_smallest_lcs(i, j, remaining_len):
        """
