        with remaining_len characters needed.
        """
        if remaining_len == 0:
            return ""
        if i == 0 or j == 0:
            return None

        if (i, j, remaining_len) in memo:
            return memo[(i, j, remaining_len)]

        result = None

        # If characters match, they must be in the LCS
        if a[i - 1] == b[j - 1]:
            suffix = find_smallest_lcs(i - 1, j - 1, remaining_len - 1)
            if suffix is not None:
                result = a[i - 1] + suffix
        else:
