    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Backtrack to find all LCS with the given length
    # Use a set to store all possible LCS strings
    def backtrack(i, j, current):
        """Backtrack to find all LCS strings."""
        if i == 0 or j == 0:
            return {current}

        if a[i - 1] == b[j - 1]:
            # Characters match, they're part of LCS
            return backtrack(i - 1, j - 1, a[i - 1] + current)
        else:
            results = set()
            # Try going up (skip character from a)
            if dp[i - 1][j] == dp[i][j]:
                results.update(backtrack(i - 1, j, current))
            # Try going left (skip character from b)
            if dp[i][j - 1] == dp[i][j]:
                results.update(backtrack(i, j - 1, current))
            return results

    # Get all LCS strings
    all_lcs = backtrack(m, n, "")

