    return min(all_lcs)

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Backtrack to find all LCS, but we'll use a greedy approach to get lexicographically smallest
    # We reconstruct by choosing the lexicographically smallest character at each step
    result = []
    i, j = m, n

    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            result.append(a[i - 1])
            i -= 1
            j -= 1
        else:
            # Move in the direction that preserves the LCS length
            # But we need to choose the direction that leads to lexicographically smallest result
            if dp[i - 1][j] > dp[i][j - 1]:
                i -= 1
            elif dp[i][j - 1] > dp[i - 1][j]:
                j -= 1
            else:
                # Both directions have the same LCS length
                # We need to explore both and pick the lexicographically smaller result
                option1 = find_lex_smallest_lcs(a, b, i - 1, j, dp)
                option2 = find_lex_smallest_lcs(a, b, i, j - 1, dp)
                if option1 <= option2:
                    i -= 1
                else:
                    j -= 1

    result.reverse()
    return ''.join(result)


def find_lex_smallest_lcs(a: str, b: str, i: int, j: int, dp: list) -> str:
    """
    Helper function to find lexicographically smallest LCS from position (i, j).
    """
    if i == 0 or j == 0:
        return ""

    if a[i - 1] == b[j - 1]:
        return a[i - 1] + find_lex_smallest_lcs(a, b, i - 1, j - 1, dp)
    else:
        if dp[i - 1][j] > dp[i][j - 1]:
            return find_lex_smallest_lcs(a, b, i - 1, j, dp)
        elif dp[i][j - 1] > dp[i - 1][j]:
            return find_lex_smallest_lcs(a, b, i, j - 1, dp)
        else:
            option1 = a[i - 1] + find_lex_smallest_lcs(a, b, i - 1, j, dp)
            option2 = b[j - 1] + find_lex_smallest_lcs(a, b, i, j - 1, dp)
            return min(option1, option2)


def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.
    Uses dynamic programming with backtracking to find all LCS candidates.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Backtrack to find the lexicographically smallest LCS
    def backtrack(i: int, j: int) -> str:
        if i == 0 or j == 0:
            return ""

        if a[i - 1] == b[j - 1]:
            return backtrack(i - 1, j - 1) + a[i - 1]
        else:
            # When we have a choice, we need to explore both paths
            if dp[i - 1][j] > dp[i][j - 1]:
                return backtrack(i - 1, j)
            elif dp[i][j - 1] > dp[i - 1][j]:
                return backtrack(i, j - 1)
            else:
                # Equal lengths - explore both and return the lexicographically smaller
                option1 = backtrack(i - 1, j)
                option2 = backtrack(i, j - 1)
                return min(option1, option2)

    return backtrack(m, n)

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Reconstruct all LCS strings and find the lexicographically smallest
    def reconstruct(i, j, current):
        """
        Recursively reconstruct all LCS strings.
        Returns a list of all possible LCS strings.
        """
        if i == 0 or j == 0:
            return [current]

        if a[i - 1] == b[j - 1]:
            # Character matches, include it
            return reconstruct(i - 1, j - 1, a[i - 1] + current)
        else:
            results = []
            # Try going up (skip character in a)
            if dp[i - 1][j] == dp[i][j]:
                results.extend(reconstruct(i - 1, j, current))
            # Try going left (skip character in b)
            if dp[i][j - 1] == dp[i][j]:
                results.extend(reconstruct(i, j - 1, current))
            return results

    # For large inputs, we need a more efficient approach
    # Instead of generating all LCS, we build the lexicographically smallest one

    def build_smallest_lcs():
        """
        Build the lexicographically smallest LCS by choosing characters greedily.
        """
        result = []
        i, j = m, n

        # Track which characters we still need to include
        remaining_length = dp[m][n]

        while i > 0 and j > 0 and remaining_length > 0:
            if a[i - 1] == b[j - 1]:
                # This character is part of the LCS
                result.append(a[i - 1])
                remaining_length -= 1
                i -= 1
                j -= 1
            else:
                # Need to decide whether to move up or left
                # We want the lexicographically smallest result
                # Look ahead to see what characters could be next

                # Collect all possible next characters from both directions
                next_chars = []

                # Check path going up (skip in a)
                if dp[i - 1][j] == dp[i][j]:
                    # We can go up and still get an LCS of the required length
                    # Find what character comes next in this path
                    ii, jj = i - 1, j
                    while ii > 0 and jj > 0:
                        if a[ii - 1] == b[jj - 1] and dp[ii - 1][jj - 1] == dp[ii][jj] - 1:
                            next_chars.append((a[ii - 1], 'up'))
                            break
                        if dp[ii - 1][jj] == dp[ii][jj]:
                            ii -= 1
                        else:
                            jj -= 1

                # Check path going left (skip in b)
                if dp[i][j - 1] == dp[i][j]:
                    # We can go left and still get an LCS of the required length
                    ii, jj = i, j - 1
                    while ii > 0 and jj > 0:
                        if a[ii - 1] == b[jj - 1] and dp[ii - 1][jj - 1] == dp[ii][jj] - 1:
                            next_chars.append((a[ii - 1], 'left'))
                            break
                        if dp[ii - 1][jj] == dp[ii][jj]:
                            ii -= 1
                        else:
                            jj -= 1

                # Choose the direction with the smaller next character
                if dp[i - 1][j] == dp[i][j]:
                    i -= 1
                else:
                    j -= 1

        return ''.join(reversed(result))

    # Use a simpler greedy approach with memoization
    memo = {}

    def find_lex_smallest(i, j, length_needed):
        """
        Find lexicographically smallest LCS of length length_needed
        using a[0:i] and b[0:j].
        """
        if length_needed == 0:
            return ""

        if i == 0 or j == 0:
            return ""

        key = (i, j, length_needed)
        if key in memo:
            return memo[key]

        candidates = []

        if a[i - 1] == b[j - 1]:
            # This character can be part of LCS
            rest = find_lex_smallest(i - 1, j - 1, length_needed - 1)
            if len(rest) == length_needed - 1:
                candidates.append(rest + a[i - 1])

        # Try skipping a[i-1]
        if dp[i - 1][j] >= length_needed:
            rest = find_lex_smallest(i - 1, j, length_needed)
            if len(rest) == length_needed:
                candidates.append(rest)

        # Try skipping b[j-1]
        if dp[i][j - 1] >= length_needed:
            rest = find_lex_smallest(i, j - 1, length_needed)
            if len(rest) == length_needed:
                candidates.append(rest)

        result = min(candidates) if candidates else ""
        memo[key] = result
        return result

    return find_lex_smallest(m, n, lcs_length)

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.
    """
    m, n = len(a), len(b)

    # DP table: dp[i][j] = length of LCS of a[0:i] and b[0:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Reconstruct all LCS candidates and find the lexicographically smallest
    def reconstruct_all_lcs(i, j):
        """Reconstruct all LCS strings ending at position (i, j)."""
        if i == 0 or j == 0:
            return [""]

        if a[i - 1] == b[j - 1]:
            # Characters match, extend all previous LCS
            prev = reconstruct_all_lcs(i - 1, j - 1)
            return [lcs + a[i - 1] for lcs in prev]
        else:
            results = []
            # Try going up (skip character in a)
            if dp[i - 1][j] == dp[i][j]:
                results.extend(reconstruct_all_lcs(i - 1, j))
            # Try going left (skip character in b)
            if dp[i][j - 1] == dp[i][j]:
                results.extend(reconstruct_all_lcs(i, j - 1))
            return results

    # For large inputs, reconstruct_all_lcs could be slow due to exponential branches.
    # Instead, use a greedy approach with memoization to find the lexicographically smallest.

    memo = {}

    def find_smallest_lcs(i, j, target_len):
        """
        Find the lexicographically smallest LCS of a[0:i] and b[0:j]
        with length exactly target_len.
        """
        if target_len == 0:
            return ""

        if i == 0 or j == 0:
            return None

        if (i, j, target_len) in memo:
            return memo[(i, j, target_len)]

        result = None

        if a[i - 1] == b[j - 1]:
            # Characters match
            if dp[i - 1][j - 1] == target_len - 1:
                prev = find_smallest_lcs(i - 1, j - 1, target_len - 1)
                if prev is not None:
                    candidate = prev + a[i - 1]
                    result = candidate

        # Try skipping character in a
        if dp[i - 1][j] == target_len:
            prev = find_smallest_lcs(i - 1, j, target_len)
            if prev is not None:
                if result is None or prev < result:
                    result = prev

        # Try skipping character in b
        if dp[i][j - 1] == target_len:
            prev = find_smallest_lcs(i, j - 1, target_len)
            if prev is not None:
                if result is None or prev < result:
                    result = prev

        memo[(i, j, target_len)] = result
        return result

    return find_smallest_lcs(m, n, lcs_length) or ""

def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)

    # Build DP table for LCS length
    dp = [[0] * (n + 1) for _ in range(m + 1)]

