                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    memo = {}

    # Backtrack to find lexicographically smallest LCS of maximum length
    def backtrack(i, j):
        if i == 0 or j == 0:
            return ""

        if (i, j) in memo:
            return memo[(i, j)]

        if a[i - 1] == b[j - 1]:
            result = backtrack(i - 1, j - 1) + a[i - 1]
        else:
            # Only follow paths that maintain maximum LCS length
            candidates = []
            if dp[i - 1][j] == dp[i][j]:
                candidates.append(backtrack(i - 1, j))
            if dp[i][j - 1] == dp[i][j]:
                candidates.append(backtrack(i, j - 1))
            result = min(candidates)

        memo[(i, j)] = result
        return result

    return backtrack(m, n)

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Backtrack to find lexicographically smallest LCS
    result = []
    i, j = m, n
    remaining_length = lcs_length

    while remaining_length > 0 and i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            # Must use this character
            result.append(a[i - 1])
            i -= 1
            j -= 1
            remaining_length -= 1
        else:
            # Choose which direction to go
            # Prefer the direction that gives lexicographically smaller result
            go_up = dp[i - 1][j] == dp[i][j]
            go_left = dp[i][j - 1] == dp[i][j]

            if go_up and go_left:
                # Both options maintain LCS length, pick the one with smaller next char
                # Recursively check both paths
                def get_remaining_lcs(ii, jj):
                    res = []
                    ii_tmp, jj_tmp = ii, jj
                    rem = dp[ii_tmp][jj_tmp]
                    while rem > 0 and ii_tmp > 0 and jj_tmp > 0:
                        if a[ii_tmp - 1] == b[jj_tmp - 1]:
                            res.append(a[ii_tmp - 1])
                            ii_tmp -= 1
                            jj_tmp -= 1
                            rem -= 1
                        else:
                            if dp[ii_tmp - 1][jj_tmp] == dp[ii_tmp][jj_tmp]:
                                ii_tmp -= 1
                            else:
                                jj_tmp -= 1
                    return ''.join(reversed(res))

                lcs_up = get_remaining_lcs(i - 1, j)
                lcs_left = get_remaining_lcs(i, j - 1)

                if lcs_up <= lcs_left:
                    i -= 1
                else:
                    j -= 1
            elif go_up:
                i -= 1
            else:
                j -= 1

    return ''.join(reversed(result))

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Reconstruct all LCS candidates and find the lexicographically smallest
    def reconstruct_all_lcs(i, j):
        """
        Reconstruct all LCS strings of a[:i] and b[:j].
        Returns a set of all possible LCS strings.
        """
        if i == 0 or j == 0:
            return {""}

        if a[i - 1] == b[j - 1]:
            # Characters match, extend all LCS from previous state
            prev_lcs = reconstruct_all_lcs(i - 1, j - 1)
            return {lcs + a[i - 1] for lcs in prev_lcs}
        else:
            result = set()
            # Take from top or left, whichever has the longer LCS
            if dp[i - 1][j] >= dp[i][j - 1]:
                result.update(reconstruct_all_lcs(i - 1, j))
            if dp[i][j - 1] >= dp[i - 1][j]:
                result.update(reconstruct_all_lcs(i, j - 1))
            return result

    # Use memoization to make reconstruction efficient
    memo = {}

    def reconstruct_all_lcs_memo(i, j):
        if (i, j) in memo:
            return memo[(i, j)]

        if i == 0 or j == 0:
            return {""}

        if a[i - 1] == b[j - 1]:
            prev_lcs = reconstruct_all_lcs_memo(i - 1, j - 1)
            result = {lcs + a[i - 1] for lcs in prev_lcs}
        else:
            result = set()
            if dp[i - 1][j] >= dp[i][j - 1]:
                result.update(reconstruct_all_lcs_memo(i - 1, j))
            if dp[i][j - 1] >= dp[i - 1][j]:
                result.update(reconstruct_all_lcs_memo(i, j - 1))

        memo[(i, j)] = result
        return result

    all_lcs = reconstruct_all_lcs_memo(m, n)
    return min(all_lcs)  # Return lexicographically smallest


