def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the lexicographically smallest longest common subsequence of a and b.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[:i] and b[:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Memoization for backtracking
    memo = {}

    def find_smallest_lcs(i, j, remaining):
        if remaining == 0:
            return ""

        if i == 0 or j == 0:
            return ""

        if (i, j, remaining) in memo:
            return memo[(i, j, remaining)]

        if a[i - 1] == b[j - 1]:
            # This character is in the LCS
            result = find_smallest_lcs(i - 1, j - 1, remaining - 1) + a[i - 1]
        else:
            # Try going up or left; pick the path that gives lexicographically smaller result
            candidates = []

            # Can we go up?
            if i > 0 and dp[i - 1][j] == dp[i][j]:
                candidates.append(find_smallest_lcs(i - 1, j, remaining))

            # Can we go left?
            if j > 0 and dp[i][j - 1] == dp[i][j]:
                candidates.append(find_smallest_lcs(i, j - 1, remaining))

            result = min(candidates) if candidates else ""

        memo[(i, j, remaining)] = result
        return result

    return find_smallest_lcs(m, n, lcs_length)

def smallest_lcs(a: str, b: str) -> str:
    """
    Returns the longest common subsequence of a and b.
    When multiple LCS exist, returns the lexicographically smallest one.
    """
    m, n = len(a), len(b)

    # dp[i][j] = length of LCS of a[0:i] and b[0:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    lcs_length = dp[m][n]

    if lcs_length == 0:
        return ""

    # Backtrack to find all LCS, then return the lexicographically smallest
    def backtrack(i, j):
        """Generate all LCS of a[0:i] and b[0:j]"""
        if i == 0 or j == 0:
            return [""]

        if a[i - 1] == b[j - 1]:
            # Character matches, include it in all LCS from previous state
            return [lcs + a[i - 1] for lcs in backtrack(i - 1, j - 1)]
        else:
            lcs_set = set()

            # Try going up (skip character from a)
            if dp[i - 1][j] == dp[i][j]:
                for lcs in backtrack(i - 1, j):
                    lcs_set.add(lcs)

            # Try going left (skip character from b)
            if dp[i][j - 1] == dp[i][j]:
                for lcs in backtrack(i, j - 1):
                    lcs_set.add(lcs)

            return list(lcs_set)

    # Memoized backtrack for efficiency
    memo = {}

    def backtrack_memo(i, j):
        """Generate all LCS of a[0:i] and b[0:j] with memoization"""
        if (i, j) in memo:
            return memo[(i, j)]

        if i == 0 or j == 0:
            return [""]

        result = []

        if a[i - 1] == b[j - 1]:
            # Character matches
            for lcs in backtrack_memo(i - 1, j - 1):
                result.append(lcs + a[i - 1])
        else:
            # Try going up
            if dp[i - 1][j] == dp[i][j]:
                result.extend(backtrack_memo(i - 1, j))

            # Try going left
            if dp[i][j - 1] == dp[i][j]:
                result.extend(backtrack_memo(i, j - 1))

        # Deduplicate
        result = list(set(result))
        memo[(i, j)] = result
        return result

    all_lcs = backtrack_memo(m, n)
    return min(all_lcs)

def smallest_lcs(a: str, b: str) -> str:
    m, n = len(a), len(b)

    # Build DP table for LCS length
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    target_len = dp[m][n]
    if target_len == 0:
        return ""

    # Build suffix DP for quick LCS length queries
    suffix_dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m - 1, -1, -1):
        for j in range(n - 1, -1, -1):
            if i == m or j == n:
                suffix_dp[i][j] = 0
            elif a[i] == b[j]:
                suffix_dp[i][j] = suffix_dp[i + 1][j + 1] + 1
            else:
                suffix_dp[i][j] = max(suffix_dp[i + 1][j], suffix_dp[i][j + 1])

    memo = {}

    def solve(i, j, needed):
        if needed == 0:
            return ""
        if i == m or j == n:
            return None

        if (i, j, needed) in memo:
            return memo[(i, j, needed)]

        result = None

        if a[i] == b[j]:
            rest = solve(i + 1, j + 1, needed - 1)
            if rest is not None:
                result = a[i] + rest
        else:
            candidates = []

            if i + 1 < m and suffix_dp[i + 1][j] >= needed:
                sub = solve(i + 1, j, needed)
                if sub is not None:
                    candidates.append(sub)

            if j + 1 < n and suffix_dp[i][j + 1] >= needed:
                sub = solve(i, j + 1, needed)
                if sub is not None:
                    candidates.append(sub)

            if candidates:
                result = min(candidates)

        memo[(i, j, needed)] = result
        return result

    return solve(0, 0, target_len) or ""

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    """
    Simulates an LRU cache with entry expiration.

    Args:
        capacity: Maximum number of non-expired entries
        ops: List of operations ("put", key, value, time, ttl) or ("get", key, time)

    Returns:
        List of results from "get" operations
    """
    # Store: key -> (value, expiry_time)
    cache = {}
    # Track recency: key -> last_access_time
    recency = {}
    results = []

    def is_expired(key, current_time):
        """Check if an entry is expired at current_time."""
        if key not in cache:
            return True
        value, expiry_time = cache[key]
        if expiry_time is None:
            return False
        return current_time >= expiry_time

    def get_non_expired_entries(current_time):
        """Get all non-expired entries at current_time."""
        return {k: v for k, v in cache.items() if not is_expired(k, current_time)}

    def evict_lru(current_time):
        """Evict the least recently used non-expired entry."""
        non_expired = get_non_expired_entries(current_time)
        if not non_expired:
            return

        # Find the least recently used among non-expired entries
        lru_key = min(non_expired.keys(), key=lambda k: recency.get(k, float('-inf')))
        del cache[lru_key]
        del recency[lru_key]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op

            # Calculate expiry time
            if ttl is None:
                expiry_time = None
            else:
                expiry_time = time + ttl

            # If key exists and is not expired, it's a replacement (no eviction needed)
            # If key is new or expired, we might need to evict
            if key not in cache or is_expired(key, time):
                # Check if we need to evict
                non_expired_count = len(get_non_expired_entries(time))
                if non_expired_count >= capacity:
                    evict_lru(time)

            # Store the new value
            cache[key] = (value, expiry_time)
            recency[key] = time

        elif op[0] == "get":
            _, key, time = op

            if key in cache and not is_expired(key, time):
                value, _ = cache[key]
                results.append(value)
                # Update recency
                recency[key] = time
            else:
                results.append(None)

    return results

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    """
    Simulates an LRU cache with entry expiration.

    Args:
        capacity: Maximum number of non-expired entries
        ops: List of operations ("put", key, value, time, ttl) or ("get", key, time)

    Returns:
        List of results from each "get" operation
    """
    # Store cache entries: key -> (value, expiry_time)
    cache = {}
    # Track recency: key -> last access time
    recency = {}
    results = []

    def is_expired(key, current_time):
        """Check if an entry is expired at the given time."""
        if key not in cache:
            return True
        _, expiry_time = cache[key]
        if expiry_time is None:
            return False
        return current_time >= expiry_time

    def get_non_expired_count():
        """Count non-expired entries."""
        return sum(1 for key in cache if not is_expired(key, current_time))

    current_time = 0

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            current_time = time

            # Calculate expiry time
            if ttl is None:
                expiry_time = None
            else:
                expiry_time = time + ttl

            # Check if key exists and is not expired
            key_exists_and_valid = key in cache and not is_expired(key, time)

            if key_exists_and_valid:
                # Replace value and expiry, update recency
                cache[key] = (value, expiry_time)
                recency[key] = time
            else:
                # New key or expired key
                non_expired_count = get_non_expired_count()

                if non_expired_count >= capacity:
                    # Need to evict the least recently used non-expired entry
                    # Find the key with minimum recency among non-expired entries
                    lru_key = None
                    lru_time = float('inf')

                    for k in cache:
                        if not is_expired(k, time):
                            if k in recency and recency[k] < lru_time:
                                lru_time = recency[k]
                                lru_key = k

                    if lru_key is not None:
                        del cache[lru_key]
                        del recency[lru_key]

                # Insert new entry
                cache[key] = (value, expiry_time)
                recency[key] = time

        elif op[0] == "get":
            _, key, time = op
            current_time = time

            # Check if key exists and is not expired
            if key in cache and not is_expired(key, time):
                value, _ = cache[key]
                results.append(value)
                # Update recency
                recency[key] = time
            else:
                results.append(None)

    return results
